-- BEGIN MODULE: src/Combat/Persistence.lua
do
  local moduleName = "src/Combat/Persistence.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local HttpService = game:GetService("HttpService")

	local Persistence = {}
	Persistence.__index = Persistence

	function Persistence.new(path)
		return setmetatable({
			path = path or "CLAW/combat-settings.json",
			version = 3,
		}, Persistence)
	end

	function Persistence:available()
		return type(rawget(environment, "readfile")) == "function" and type(rawget(environment, "writefile")) == "function"
	end

	function Persistence:_ensureFolder()
		local makefolder = rawget(environment, "makefolder")
		local isfolder = rawget(environment, "isfolder")
		if type(makefolder) ~= "function" then
			return
		end

		if type(isfolder) == "function" then
			local ok, exists = pcall(isfolder, "CLAW")
			if ok and exists then
				return
			end
		end

		pcall(makefolder, "CLAW")
	end

	function Persistence:load()
		if not self:available() then
			return nil, "executor file APIs are unavailable"
		end

		local isfile = rawget(environment, "isfile")
		if type(isfile) == "function" then
			local ok, exists = pcall(isfile, self.path)
			if not ok or not exists then
				return nil, "settings file does not exist"
			end
		end

		local okRead, encoded = pcall(rawget(environment, "readfile"), self.path)
		if not okRead or type(encoded) ~= "string" then
			return nil, "settings file could not be read"
		end

		local okDecode, envelope = pcall(HttpService.JSONDecode, HttpService, encoded)
		if not okDecode or type(envelope) ~= "table" then
			return nil, "settings file is invalid JSON"
		end

		if envelope.version ~= self.version or type(envelope.combat) ~= "table" then
			return nil, "settings file version is unsupported"
		end

		return envelope.combat
	end

	function Persistence:save(settings)
		if not self:available() then
			return false, "executor file APIs are unavailable"
		end

		self:_ensureFolder()

		local okEncode, encoded = pcall(HttpService.JSONEncode, HttpService, {
			version = self.version,
			combat = settings,
		})
		if not okEncode then
			return false, "settings could not be encoded"
		end

		local okWrite, writeError = pcall(rawget(environment, "writefile"), self.path, encoded)
		if not okWrite then
			return false, tostring(writeError)
		end

		return true
	end

	return Persistence
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Persistence.lua

-- BEGIN MODULE: src/Combat/State.lua
do
  local moduleName = "src/Combat/State.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local Signal = assert(environment.__CLAW_MODULES["src/Runtime/Signal.lua"])

	local State = {}
	State.__index = State

	function State.new()
		local self = setmetatable({}, State)
		self.Running = false
		self.Destroyed = false
		self.Character = nil
		self.Root = nil
		self.Humanoid = nil
		self.Targets = {}
		self.PrimaryTarget = nil
		self.ActiveTasks = {}
		self.Cooldowns = {}
		self.Flags = {}
		self.LastEvent = nil
		self.LastDetection = nil
		self.LastReject = nil
		self.LastPlan = nil
		self.LastActionResult = nil
		self.LastFailure = nil
		self.LastThreat = nil
		self.ThreatSummary = {
			enabled = false,
			activePlans = 0,
			noisySources = 0,
			mode = "OFF",
		}
		self.Metrics = {
			Detected = 0,
			Scheduled = 0,
			Executed = 0,
			Failed = 0,
			Cancelled = 0,
			Rejected = 0,
			ThreatAdmitted = 0,
			ThreatCoalesced = 0,
			ThreatDropped = 0,
			ThreatSpamBursts = 0,
			ThreatCorroborated = 0,
			ThreatPromoted = 0,
		}
		self.Changed = Signal.new()
		self.Event = Signal.new()
		return self
	end

	function State:set(key, value)
		local previous = self[key]
		if previous == value then
			return value
		end

		self[key] = value
		self.Changed:Fire(key, value, previous)
		return value
	end

	function State:setCharacter(character)
		self.Character = character
		self.Root = character and character:FindFirstChild("HumanoidRootPart") or nil
		self.Humanoid = character and character:FindFirstChildWhichIsA("Humanoid") or nil
		self.Changed:Fire("Character", character)
	end

	function State:setTargets(targets)
		self.Targets = targets or {}
		self.PrimaryTarget = self.Targets[1]
		self.Changed:Fire("Targets", self.Targets)
	end

	function State:emit(kind, payload)
		self.LastEvent = {
			kind = kind,
			payload = payload,
			at = os.clock(),
		}
		self.Event:Fire(self.LastEvent)
	end

	function State:increment(metric, amount)
		self.Metrics[metric] = (self.Metrics[metric] or 0) + (amount or 1)
	end

	function State:resetRuntime()
		self:setTargets({})
		table.clear(self.ActiveTasks)
		table.clear(self.Cooldowns)
		table.clear(self.Flags)
		self.LastEvent = nil
		self.LastDetection = nil
		self.LastReject = nil
		self.LastPlan = nil
		self.LastActionResult = nil
		self.LastFailure = nil
		self.LastThreat = nil
		self.ThreatSummary = {
			enabled = false,
			activePlans = 0,
			noisySources = 0,
			mode = "OFF",
		}
	end

	function State:Destroy()
		if self.Destroyed then
			return
		end

		self.Destroyed = true
		self.Running = false
		self:resetRuntime()
		self.Changed:Destroy()
		self.Event:Destroy()
	end

	return State
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/State.lua

-- BEGIN MODULE: src/Combat/EntityHistory.lua
do
  local moduleName = "src/Combat/EntityHistory.lua"
  local moduleFactory = function()
	local EntityHistory = {}
	EntityHistory.__index = EntityHistory

	function EntityHistory.new(maxSeconds)
		return setmetatable({
			_maxSeconds = maxSeconds or 3,
			_records = setmetatable({}, { __mode = "k" }),
		}, EntityHistory)
	end

	function EntityHistory:setWindow(seconds)
		self._maxSeconds = math.max(0.1, tonumber(seconds) or self._maxSeconds)
	end

	function EntityHistory:_prune(history, now)
		local cutoff = now - self._maxSeconds
		local records = history.records
		while history.head <= #records and records[history.head].at < cutoff do
			history.head = history.head + 1
		end

		-- Compact occasionally instead of shifting the array on every sample.
		if history.head > 64 and history.head > (#records * 0.5) then
			local compacted = {}
			for index = history.head, #records do
				compacted[#compacted + 1] = records[index]
			end
			history.records = compacted
			history.head = 1
		end
	end

	function EntityHistory:record(entity, cframe, velocity, timestamp)
		if not entity or typeof(cframe) ~= "CFrame" then
			return
		end

		local now = timestamp or os.clock()
		local history = self._records[entity]
		if not history then
			history = { records = {}, head = 1 }
			self._records[entity] = history
		end

		local records = history.records
		records[#records + 1] = {
			at = now,
			cframe = cframe,
			velocity = typeof(velocity) == "Vector3" and velocity or Vector3.zero,
		}
		self:_prune(history, now)
	end

	function EntityHistory:recent(entity, seconds, timestamp)
		local history = self._records[entity]
		if not history then
			return {}
		end

		local cutoff = (timestamp or os.clock()) - (seconds or self._maxSeconds)
		local result = {}
		for index = history.head, #history.records do
			local record = history.records[index]
			if record.at >= cutoff then
				result[#result + 1] = record
			end
		end
		return result
	end

	function EntityHistory:closest(entity, timestamp)
		local history = self._records[entity]
		if not history then
			return nil
		end

		local closest
		local closestDelta = math.huge
		for index = history.head, #history.records do
			local record = history.records[index]
			local delta = math.abs(record.at - timestamp)
			if delta < closestDelta then
				closest = record
				closestDelta = delta
			end
		end
		return closest
	end

	function EntityHistory:averageVelocity(entity, seconds)
		local history = self._records[entity]
		if not history then
			return Vector3.zero
		end

		local cutoff = os.clock() - (seconds or 0.20)
		local total = Vector3.zero
		local count = 0
		for index = history.head, #history.records do
			local record = history.records[index]
			if record.at >= cutoff then
				total = total + record.velocity
				count = count + 1
			end
		end
		return count > 0 and total / count or Vector3.zero
	end

	function EntityHistory:anyRecent(entity, seconds, predicate)
		local history = self._records[entity]
		if not history then
			return false
		end
		local cutoff = os.clock() - (seconds or self._maxSeconds)
		for index = history.head, #history.records do
			local record = history.records[index]
			if record.at >= cutoff and predicate(record) then
				return true
			end
		end
		return false
	end

	function EntityHistory:predict(entity, seconds)
		local history = self._records[entity]
		local latest = history and history.records[#history.records]
		if not latest then
			return nil
		end

		local predictionSeconds = math.max(0, tonumber(seconds) or 0)
		return latest.cframe + (self:averageVelocity(entity, 0.20) * predictionSeconds)
	end

	function EntityHistory:yawRate(entity)
		local history = self._records[entity]
		if not history or #history.records - history.head + 1 < 2 then
			return 0
		end

		local previous = history.records[#history.records - 1]
		local latest = history.records[#history.records]
		local deltaTime = latest.at - previous.at
		if deltaTime <= 0.0001 then
			return 0
		end

		local first = Vector3.new(previous.cframe.LookVector.X, 0, previous.cframe.LookVector.Z)
		local second = Vector3.new(latest.cframe.LookVector.X, 0, latest.cframe.LookVector.Z)
		if first.Magnitude <= 0.0001 or second.Magnitude <= 0.0001 then
			return 0
		end

		first = first.Unit
		second = second.Unit
		local angle = math.atan2(first:Cross(second).Y, math.clamp(first:Dot(second), -1, 1))
		return angle / deltaTime
	end

	function EntityHistory:clear(entity)
		if entity then
			self._records[entity] = nil
		else
			table.clear(self._records)
		end
	end

	return EntityHistory
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/EntityHistory.lua

-- BEGIN MODULE: src/Combat/Targeting.lua
do
  local moduleName = "src/Combat/Targeting.lua"
  local moduleFactory = function()
	local Players = game:GetService("Players")
	local UserInputService = game:GetService("UserInputService")

	local Targeting = {}
	Targeting.__index = Targeting

	local function listed(list, player, character)
		local name = string.lower(player and player.Name or character.Name)
		local displayName = player and string.lower(player.DisplayName) or nil
		local userID = player and tostring(player.UserId) or nil

		for _, value in ipairs(list or {}) do
			local normalized = string.lower(tostring(value))
			if normalized == name or (displayName and normalized == displayName) or (userID and normalized == userID) then
				return true
			end
		end

		return false
	end

	local function mobTargetsLocalPlayer(character, localCharacter)
		local localPlayer = Players.LocalPlayer
		local targetNames = { "Target", "CombatTarget", "CurrentTarget", "AggroTarget" }
		for _, name in ipairs(targetNames) do
			local object = character:FindFirstChild(name, true)
			if object and object:IsA("ObjectValue") and object.Value ~= nil then
				return object.Value == localCharacter or object.Value == localPlayer
			end
			local attribute = character:GetAttribute(name)
			if attribute ~= nil then
				local normalized = tostring(attribute)
				return normalized == localCharacter.Name
					or normalized == localPlayer.Name
					or normalized == tostring(localPlayer.UserId)
			end
		end
		-- Some entities do not replicate an aggro target. In that case, preserve the
		-- target instead of introducing a false negative.
		return true
	end

	function Targeting.new(settings, options)
		options = options or {}
		return setmetatable({
			settings = settings,
			isAlly = options.isAlly,
			entitySource = options.entitySource,
			friendCache = setmetatable({}, { __mode = "k" }),
		}, Targeting)
	end

	function Targeting:_isAlly(player)
		local localPlayer = Players.LocalPlayer
		local allied = player.Team ~= nil and player.Team == localPlayer.Team
		local localGuild = localPlayer:GetAttribute("Guild")
		if not allied and type(localGuild) == "string" and localGuild ~= "" then
			allied = player:GetAttribute("Guild") == localGuild
		end
		if not allied then
			local cached = self.friendCache[player]
			if cached == nil then
				local ok, status = pcall(localPlayer.GetFriendStatus, localPlayer, player)
				cached = ok and status == Enum.FriendStatus.Friend
				self.friendCache[player] = cached
			end
			allied = cached
		end
		if type(self.isAlly) == "function" then
			local ok, customAllied = pcall(self.isAlly, player)
			allied = ok and customAllied or allied
		end
		return allied
	end

	function Targeting:_entities()
		if type(self.entitySource) == "function" then
			local ok, entities = pcall(self.entitySource)
			if ok and type(entities) == "table" then
				return entities
			end
		end

		local live = workspace:FindFirstChild("Live")
		if live then
			return live:GetChildren()
		end

		local entities = {}
		for _, player in ipairs(Players:GetPlayers()) do
			if player.Character then
				entities[#entities + 1] = player.Character
			end
		end
		return entities
	end

	function Targeting:scan(localCharacter)
		local config = self.settings:get("Targeting")
		local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
		local camera = workspace.CurrentCamera
		if not localRoot or not camera then
			return {}
		end

		local mouse = UserInputService:GetMouseLocation()
		local candidates = {}

		for _, character in ipairs(self:_entities()) do
			if character == localCharacter or not character:IsA("Model") then
				continue
			end

			local humanoid = character:FindFirstChildWhichIsA("Humanoid")
			local root = character:FindFirstChild("HumanoidRootPart")
			if not humanoid or humanoid.Health <= 0 or not root or not root:IsA("BasePart") then
				continue
			end

			local player = Players:GetPlayerFromCharacter(character)
			if player and config.IgnorePlayers then
				continue
			end
			if not player and config.IgnoreMobs then
				continue
			end
			if not player and config.CheckMobTarget and not mobTargetsLocalPlayer(character, localCharacter) then
				continue
			end
			local whitelisted = listed(config.Whitelist, player, character)
			if config.WhitelistMode == "Only" and #config.Whitelist > 0 and not whitelisted then
				continue
			end
			if config.WhitelistMode == "Exclude" and whitelisted then
				continue
			end
			if listed(config.Blacklist, player, character) then
				continue
			end
			if player and config.IgnoreAllies then
				if self:_isAlly(player) then
					continue
				end
			end

			local offset = root.Position - localRoot.Position
			local distance = offset.Magnitude
			if distance > config.MaxDistance or distance <= 0.001 then
				continue
			end

			local facingDot = camera.CFrame.LookVector:Dot(offset.Unit)
			local minimumDot = math.cos(math.rad(math.clamp(config.FOVDegrees, 0, 360) * 0.5))
			if config.FOVDegrees < 360 and facingDot < minimumDot then
				continue
			end

			local screenPosition, onScreen = camera:WorldToViewportPoint(root.Position)
			if config.RequireOnScreen and not onScreen then
				continue
			end

			local crosshairDistance = Vector2.new(screenPosition.X - mouse.X, screenPosition.Y - mouse.Y).Magnitude
			candidates[#candidates + 1] = {
				Character = character,
				Player = player,
				Humanoid = humanoid,
				Root = root,
				Distance = distance,
				CrosshairDistance = crosshairDistance,
				FacingDot = facingDot,
				OnScreen = onScreen,
				HealthRatio = humanoid.MaxHealth > 0 and humanoid.Health / humanoid.MaxHealth or 1,
			}
		end

		return candidates
	end

	function Targeting:select(candidates)
		local config = self.settings:get("Targeting")
		local selection = config.Selection

		table.sort(candidates, function(first, second)
			if selection == "ClosestCrosshair" then
				return first.CrosshairDistance < second.CrosshairDistance
			elseif selection == "LeastHealth" then
				return first.Humanoid.Health < second.Humanoid.Health
			elseif selection == "LowestHealthRatio" then
				return first.HealthRatio < second.HealthRatio
			elseif selection == "HighestThreat" then
				local firstScore = first.Distance - (first.FacingDot * 10)
				local secondScore = second.Distance - (second.FacingDot * 10)
				return firstScore < secondScore
			end
			return first.Distance < second.Distance
		end)

		local selected = {}
		local limit = math.max(1, math.floor(config.MaxTargets))
		for index = 1, math.min(limit, #candidates) do
			selected[index] = candidates[index]
		end
		return selected
	end

	function Targeting:best(localCharacter)
		return self:select(self:scan(localCharacter))
	end

	function Targeting:find(localCharacter, model)
		for _, target in ipairs(self:best(localCharacter)) do
			if target.Character == model then
				return target
			end
		end
		return nil
	end

	return Targeting
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Targeting.lua

-- BEGIN MODULE: src/Combat/Action.lua
do
  local moduleName = "src/Combat/Action.lua"
  local moduleFactory = function()
	local Action = {}
	Action.__index = Action

	local VALID_KINDS = {
		Parry = true,
		Block = true,
		Dodge = true,
		FullDodge = true,
		Jump = true,
		Slide = true,
		Crouch = true,
		Teleport = true,
		Feint = true,
		M1 = true,
		Custom = true,
	}

	function Action.new(values)
		values = values or {}
		local kind = values.kind or "Parry"
		assert(VALID_KINDS[kind], "unsupported combat action: " .. tostring(kind))

		local hitbox = values.hitbox
		if type(hitbox) == "table" then
			hitbox = Vector3.new(hitbox.X or 0, hitbox.Y or 0, hitbox.Z or 0)
		end

		return setmetatable({
			kind = kind,
			name = values.name or kind,
			delay = math.max(0, tonumber(values.delay) or 0),
			duration = math.max(0, tonumber(values.duration) or 0),
			hitbox = typeof(hitbox) == "Vector3" and hitbox or Vector3.zero,
			ignoreHitbox = values.ignoreHitbox == true,
			chance = math.clamp(tonumber(values.chance) or 100, 0, 100),
			metadata = type(values.metadata) == "table" and values.metadata or {},
		}, Action)
	end

	function Action:clone()
		return Action.new(self:serialize())
	end

	function Action:serialize()
		local metadata = {}
		for key, value in pairs(self.metadata) do
			metadata[key] = value
		end
		return {
			kind = self.kind,
			name = self.name,
			delay = self.delay,
			duration = self.duration,
			hitbox = { X = self.hitbox.X, Y = self.hitbox.Y, Z = self.hitbox.Z },
			ignoreHitbox = self.ignoreHitbox,
			chance = self.chance,
			metadata = metadata,
		}
	end

	function Action:shouldRun(random)
		if self.chance >= 100 then
			return true
		end
		local roll = random and random:NextNumber(0, 100) or math.random() * 100
		return roll <= self.chance
	end

	return Action
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Action.lua

-- BEGIN MODULE: src/Combat/TimingProfile.lua
do
  local moduleName = "src/Combat/TimingProfile.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local Action = assert(environment.__CLAW_MODULES["src/Combat/Action.lua"])

	local TimingProfile = {}
	TimingProfile.__index = TimingProfile

	function TimingProfile.new(values)
		values = values or {}
		local hitbox = values.hitbox
		if type(hitbox) == "table" then
			hitbox = Vector3.new(hitbox.X or 0, hitbox.Y or 0, hitbox.Z or 0)
		end
		local self = setmetatable({}, TimingProfile)
		self.id = tostring(values.id or values.name or "unknown")
		self.name = tostring(values.name or self.id)
		self.detector = values.detector or "animation"
		self.tag = values.tag or "Undefined"
		self.minDistance = math.max(0, tonumber(values.minDistance) or 0)
		self.maxDistance = math.max(self.minDistance, tonumber(values.maxDistance) or 0)
		self.hitbox = typeof(hitbox) == "Vector3" and hitbox or Vector3.zero
		self.hitboxOffset = tonumber(values.hitboxOffset) or 0
		self.delayUntilHitbox = values.delayUntilHitbox == true
		self.punishableWindow = math.max(0, tonumber(values.punishableWindow) or 0)
		self.afterWindow = math.max(0, tonumber(values.afterWindow) or 0)
		self.repeatStartDelay = math.max(0, tonumber(values.repeatStartDelay) or 0)
		self.repeatDelay = math.max(0, tonumber(values.repeatDelay) or 0)
		self.preferRepeat = values.preferRepeat == true
		self.allowAttacking = values.allowAttacking == true
		self.facingHitbox = values.facingHitbox ~= false
		self.noDodgeFallback = values.noDodgeFallback == true
		self.noBlockFallback = values.noBlockFallback == true
		self.noVentFallback = values.noVentFallback == true
		self.blockFallbackHold = math.max(0, tonumber(values.blockFallbackHold) or 0.30)
		self.preferBlockFallback = values.preferBlockFallback == true
		self.hyperArmor = values.hyperArmor == true
		self.sourceModule = tostring(values.sourceModule or "")
		self.preferModule = values.preferModule == true
		self.suppressGeneric = values.suppressGeneric == true
		self.ignoreAnimationEnd = values.ignoreAnimationEnd == true
		self.ignoreEarlyAnimationEnd = values.ignoreEarlyAnimationEnd == true
		self.maxAnimationTime = math.max(0, tonumber(values.maxAnimationTime) or 0)
		self.pastHitbox = values.pastHitbox == true
		self.predictFacing = values.predictFacing == true
		self.historySeconds = math.max(0, tonumber(values.historySeconds) or 0)
		self.predictionSeconds = math.max(0, tonumber(values.predictionSeconds) or 0)
		self.disablePrediction = values.disablePrediction == true
		self.useHitboxCFrame = values.useHitboxCFrame == true
		self.allowLocalPlayer = values.allowLocalPlayer == true
		self.ignoreLocalPlayer = values.ignoreLocalPlayer == true
		self.forceLocalPlayer = values.forceLocalPlayer == true
		self.probability = type(values.probability) == "table" and values.probability or {}
		self.actions = {}

		for _, action in ipairs(values.actions or {}) do
			self.actions[#self.actions + 1] = getmetatable(action) == Action and action or Action.new(action)
		end

		return self
	end

	function TimingProfile:addAction(action)
		self.actions[#self.actions + 1] = getmetatable(action) == Action and action or Action.new(action)
		return self
	end

	function TimingProfile:clone()
		return TimingProfile.new(self:serialize())
	end

	function TimingProfile:serialize()
		local actions = {}
		for index, action in ipairs(self.actions) do
			actions[index] = action:serialize()
		end

		return {
			id = self.id,
			name = self.name,
			detector = self.detector,
			tag = self.tag,
			minDistance = self.minDistance,
			maxDistance = self.maxDistance,
			hitbox = { X = self.hitbox.X, Y = self.hitbox.Y, Z = self.hitbox.Z },
			hitboxOffset = self.hitboxOffset,
			delayUntilHitbox = self.delayUntilHitbox,
			punishableWindow = self.punishableWindow,
			afterWindow = self.afterWindow,
			repeatStartDelay = self.repeatStartDelay,
			repeatDelay = self.repeatDelay,
			preferRepeat = self.preferRepeat,
			allowAttacking = self.allowAttacking,
			facingHitbox = self.facingHitbox,
			noDodgeFallback = self.noDodgeFallback,
			noBlockFallback = self.noBlockFallback,
			noVentFallback = self.noVentFallback,
			blockFallbackHold = self.blockFallbackHold,
			preferBlockFallback = self.preferBlockFallback,
			hyperArmor = self.hyperArmor,
			sourceModule = self.sourceModule,
			preferModule = self.preferModule,
			suppressGeneric = self.suppressGeneric,
			ignoreAnimationEnd = self.ignoreAnimationEnd,
			ignoreEarlyAnimationEnd = self.ignoreEarlyAnimationEnd,
			maxAnimationTime = self.maxAnimationTime,
			pastHitbox = self.pastHitbox,
			predictFacing = self.predictFacing,
			historySeconds = self.historySeconds,
			predictionSeconds = self.predictionSeconds,
			disablePrediction = self.disablePrediction,
			useHitboxCFrame = self.useHitboxCFrame,
			allowLocalPlayer = self.allowLocalPlayer,
			ignoreLocalPlayer = self.ignoreLocalPlayer,
			forceLocalPlayer = self.forceLocalPlayer,
			probability = self.probability,
			actions = actions,
		}
	end

	return TimingProfile
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/TimingProfile.lua

-- BEGIN MODULE: src/Combat/TimingStore.lua
do
  local moduleName = "src/Combat/TimingStore.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local TimingProfile = assert(environment.__CLAW_MODULES["src/Combat/TimingProfile.lua"])
	local Signal = assert(environment.__CLAW_MODULES["src/Runtime/Signal.lua"])

	local TimingStore = {}
	TimingStore.__index = TimingStore

	local CATEGORIES = {
		animation = true,
		sound = true,
		part = true,
		effect = true,
	}

	function TimingStore.new()
		return setmetatable({
			Changed = Signal.new(),
			_containers = {
				animation = {},
				sound = {},
				part = {},
				effect = {},
			},
		}, TimingStore)
	end

	function TimingStore:register(profile, replace, silent)
		profile = getmetatable(profile) == TimingProfile and profile or TimingProfile.new(profile)
		assert(CATEGORIES[profile.detector], "invalid detector category: " .. tostring(profile.detector))

		local container = self._containers[profile.detector]
		if container[profile.id] and not replace then
			error("timing profile already exists: " .. profile.id)
		end
		container[profile.id] = profile
		if not silent then
			self.Changed:Fire("registered", profile.detector, profile.id, profile)
		end
		return profile
	end

	function TimingStore:has(category, id)
		local container = self._containers[category]
		return container ~= nil and container[tostring(id)] ~= nil
	end

	function TimingStore:get(category, id)
		local container = self._containers[category]
		return container and container[tostring(id)] or nil
	end

	function TimingStore:remove(category, id)
		local container = self._containers[category]
		if container then
			local key = tostring(id)
			local removed = container[key]
			container[key] = nil
			if removed then
				self.Changed:Fire("removed", category, key, removed)
			end
		end
	end

	function TimingStore:list(category)
		local result = {}
		local container = assert(self._containers[category], "invalid detector category")
		for _, profile in pairs(container) do
			result[#result + 1] = profile
		end
		table.sort(result, function(first, second)
			return first.name < second.name
		end)
		return result
	end

	function TimingStore:clear(category, silent)
		if category then
			table.clear(assert(self._containers[category], "invalid detector category"))
		else
			for name in pairs(CATEGORIES) do
				table.clear(self._containers[name])
			end
		end
		if not silent then
			self.Changed:Fire("cleared", category)
		end
	end

	function TimingStore:load(values)
		local staged = {
			animation = {},
			sound = {},
			part = {},
			effect = {},
		}
		for category in pairs(CATEGORIES) do
			local profiles = type(values) == "table" and values[category] or {}
			assert(type(profiles) == "table", "invalid timing category: " .. category)
			for _, valuesForProfile in ipairs(profiles) do
				assert(type(valuesForProfile) == "table", "invalid timing profile")
				local normalized = {}
				for key, value in pairs(valuesForProfile) do
					normalized[key] = value
				end
				normalized.detector = category
				local profile = TimingProfile.new(normalized)
				staged[category][profile.id] = profile
			end
		end
		self._containers = staged
		self.Changed:Fire("loaded")
		return self
	end

	function TimingStore:merge(values)
		for category in pairs(CATEGORIES) do
			local profiles = type(values) == "table" and values[category] or {}
			assert(type(profiles) == "table", "invalid timing category: " .. category)
			for _, valuesForProfile in ipairs(profiles) do
				assert(type(valuesForProfile) == "table", "invalid timing profile")
				local normalized = {}
				for key, value in pairs(valuesForProfile) do
					normalized[key] = value
				end
				normalized.detector = category
				self:register(normalized, true, true)
			end
		end
		self.Changed:Fire("merged")
		return self
	end

	function TimingStore:serialize()
		local result = {}
		for category in pairs(CATEGORIES) do
			result[category] = {}
			for index, profile in ipairs(self:list(category)) do
				result[category][index] = profile:serialize()
			end
		end
		return result
	end

	function TimingStore:count()
		local count = 0
		for category in pairs(CATEGORIES) do
			for _ in pairs(self._containers[category]) do
				count = count + 1
			end
		end
		return count
	end

	function TimingStore:Destroy()
		self:clear(nil, true)
		self.Changed:Destroy()
	end

	return TimingStore
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/TimingStore.lua

-- BEGIN MODULE: src/Combat/TimingPersistence.lua
do
  local moduleName = "src/Combat/TimingPersistence.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local HttpService = game:GetService("HttpService")

	local TimingPersistence = {}
	TimingPersistence.__index = TimingPersistence

	function TimingPersistence.new(store, path)
		return setmetatable({
			Store = store,
			Path = path or "CLAW/timings.json",
			Version = 1,
		}, TimingPersistence)
	end

	function TimingPersistence:export()
		return HttpService:JSONEncode({
			version = self.Version,
			timings = self.Store:serialize(),
		})
	end

	function TimingPersistence:import(encoded, merge)
		local ok, data = pcall(HttpService.JSONDecode, HttpService, encoded)
		if not ok or type(data) ~= "table" or type(data.timings) ~= "table" then
			return false, "invalid timing data"
		end
		if data.version ~= self.Version then
			return false, "unsupported timing version"
		end
		local method = merge and self.Store.merge or self.Store.load
		local loaded, loadError = pcall(method, self.Store, data.timings)
		if not loaded then
			return false, tostring(loadError)
		end
		return true
	end

	function TimingPersistence:load(merge)
		local readfile = rawget(environment, "readfile")
		local isfile = rawget(environment, "isfile")
		if type(readfile) ~= "function" then
			return false, "executor file APIs are unavailable"
		end
		if type(isfile) == "function" then
			local ok, exists = pcall(isfile, self.Path)
			if not ok or not exists then
				return false, "timing file does not exist"
			end
		end
		local ok, encoded = pcall(readfile, self.Path)
		if not ok then
			return false, tostring(encoded)
		end
		return self:import(encoded, merge)
	end

	function TimingPersistence:save()
		local writefile = rawget(environment, "writefile")
		if type(writefile) ~= "function" then
			return false, "executor file APIs are unavailable"
		end
		local makefolder = rawget(environment, "makefolder")
		if type(makefolder) == "function" then
			pcall(makefolder, "CLAW")
		end
		local ok, result = pcall(writefile, self.Path, self:export())
		return ok, ok and nil or tostring(result)
	end

	function TimingPersistence:copy()
		local setclipboard = rawget(environment, "setclipboard")
		if type(setclipboard) ~= "function" then
			return false, "clipboard API is unavailable"
		end
		local ok, result = pcall(setclipboard, self:export())
		return ok, ok and nil or tostring(result)
	end

	return TimingPersistence
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/TimingPersistence.lua

-- BEGIN MODULE: src/Combat/Scheduler.lua
do
  local moduleName = "src/Combat/Scheduler.lua"
  local moduleFactory = function()
	local Scheduler = {}
	Scheduler.__index = Scheduler

	function Scheduler.new(state, clock)
		return setmetatable({
			state = state,
			clock = clock or os.clock,
			_nextID = 0,
			_tasks = {},
			_destroyed = false,
		}, Scheduler)
	end

	function Scheduler:schedule(identifier, delaySeconds, windows, callback, ...)
		assert(not self._destroyed, "scheduler is destroyed")
		assert(type(callback) == "function", "scheduled callback must be a function")

		windows = windows or {}
		self._nextID = self._nextID + 1
		local id = self._nextID
		local now = self.clock()
		local scheduled = {
			id = id,
			identifier = tostring(identifier or id),
			createdAt = now,
			dueAt = now + math.max(0, tonumber(delaySeconds) or 0),
			punishableWindow = math.max(0, tonumber(windows.punishable) or 0),
			afterWindow = math.max(0, tonumber(windows.after) or 0),
			status = "scheduled",
		}
		local arguments = table.pack(...)

		self._tasks[id] = scheduled
		self.state.ActiveTasks[id] = scheduled
		self.state:increment("Scheduled")
		self.state:emit("scheduled", scheduled)

		scheduled.thread = task.delay(math.max(0, scheduled.dueAt - self.clock()), function()
			if scheduled.status ~= "scheduled" or self._destroyed then
				return
			end

			scheduled.status = "running"
			local callbackResults = table.pack(pcall(callback, table.unpack(arguments, 1, arguments.n)))
			local ok = callbackResults[1]
			local result = callbackResults[2]
			local detail = callbackResults[3]
			scheduled.status = ok and result ~= false and "completed" or "failed"
			scheduled.result = result
			scheduled.detail = detail
			scheduled.error = scheduled.status == "failed"
				and (ok and tostring(detail or "scheduled callback returned false") or tostring(result))
				or nil
			scheduled.completedAt = self.clock()
			if scheduled.status == "completed" then
				self.state:increment("Executed")
			else
				self.state:increment("Failed")
				self.state.LastFailure = {
					identifier = scheduled.identifier,
					reason = scheduled.error,
					at = scheduled.completedAt,
				}
			end
			self.state:emit(scheduled.status, scheduled)
			self._tasks[id] = nil
			self.state.ActiveTasks[id] = nil
		end)

		return scheduled
	end

	function Scheduler:isBlocking(timestamp)
		local now = timestamp or self.clock()
		for _, scheduled in pairs(self._tasks) do
			if scheduled.status == "scheduled" then
				local start = scheduled.dueAt - scheduled.punishableWindow
				local finish = scheduled.dueAt + scheduled.afterWindow
				if now >= start and now <= finish then
					return true, scheduled
				end
			end
		end
		return false
	end

	function Scheduler:cancel(id, reason)
		local scheduled = type(id) == "table" and id or self._tasks[id]
		if not scheduled or scheduled.status ~= "scheduled" then
			return false
		end

		scheduled.status = "cancelled"
		scheduled.reason = reason or "cancelled"
		if scheduled.thread then
			pcall(task.cancel, scheduled.thread)
		end
		if type(scheduled.onCancel) == "function" then
			pcall(scheduled.onCancel, scheduled.reason)
		end
		self._tasks[scheduled.id] = nil
		self.state.ActiveTasks[scheduled.id] = nil
		self.state:increment("Cancelled")
		self.state:emit("cancelled", scheduled)
		return true
	end

	function Scheduler:cancelAll(reason)
		local pending = {}
		for _, scheduled in pairs(self._tasks) do
			pending[#pending + 1] = scheduled
		end
		for _, scheduled in ipairs(pending) do
			self:cancel(scheduled, reason)
		end
	end

	function Scheduler:Destroy()
		if self._destroyed then
			return
		end
		self:cancelAll("scheduler destroyed")
		self._destroyed = true
	end

	return Scheduler
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Scheduler.lua

-- BEGIN MODULE: src/Combat/ThreatArbiter.lua
do
  local moduleName = "src/Combat/ThreatArbiter.lua"
  local moduleFactory = function()
	local ThreatArbiter = {}
	ThreatArbiter.__index = ThreatArbiter

	local TRUST = {
		animation = 1,
		sound = 2,
		part = 3,
		effect = 3,
		projectile = 4,
	}

	local function sourceFor(event)
		return event and (event.entity or event.instance) or nil
	end

	local function countPlans(record)
		local count = 0
		for _ in pairs(record.plans) do
			count = count + 1
		end
		return count
	end

	function ThreatArbiter.new(settings, state, scheduler, clock)
		if type(scheduler) == "function" and clock == nil then
			clock = scheduler
			scheduler = nil
		end
		local self = setmetatable({
			Settings = settings,
			State = state,
			Clock = clock or os.clock,
			Scheduler = scheduler,
			Sources = setmetatable({}, { __mode = "k" }),
			FallbackSource = nil,
			ActivePlans = 0,
			NextPlanID = 0,
		}, ThreatArbiter)
		state.ThreatSummary = self:_summary()
		return self
	end

	function ThreatArbiter:_record(event)
		local source = sourceFor(event)
		if not source then
			if not self.FallbackSource then
				self.FallbackSource = {
					animationTimes = {},
					plans = {},
					plansByEvent = setmetatable({}, { __mode = "k" }),
					noisyUntil = 0,
					lastCorroboratedAt = 0,
					lastNoisyPass = 0,
					lastNotice = 0,
				}
			end
			return self.FallbackSource, "unknown"
		end

		local record = self.Sources[source]
		if not record then
			record = {
				animationTimes = {},
				plans = {},
				plansByEvent = setmetatable({}, { __mode = "k" }),
				noisyUntil = 0,
				lastCorroboratedAt = 0,
				lastNoisyPass = 0,
				lastNotice = 0,
			}
			self.Sources[source] = record
		end
		local name = event.entity and event.entity.Name or event.instance and event.instance.Name or "unknown"
		return record, tostring(name)
	end

	function ThreatArbiter:_summary(now)
		now = now or self.Clock()
		local noisy = 0
		for _, record in pairs(self.Sources) do
			if record.noisyUntil > now then
				noisy = noisy + 1
			end
		end
		if self.FallbackSource and self.FallbackSource.noisyUntil > now then
			noisy = noisy + 1
		end
		local enabled = self.Settings:get("ThreatGuard.Enabled")
		return {
			enabled = enabled,
			activePlans = self.ActivePlans,
			noisySources = noisy,
			mode = not enabled and "OFF" or noisy > 0 and "DEGRADED" or "NORMAL",
		}
	end

	function ThreatArbiter:_decision(kind, event, reason, record, force)
		local now = self.Clock()
		self.State.LastThreat = {
			kind = kind,
			reason = tostring(reason or kind),
			detector = event and event.detector or "?",
			id = event and event.id or "?",
			entity = event and event.entity and event.entity.Name or "?",
			at = now,
		}
		self.State.ThreatSummary = self:_summary(now)

		-- A breaker can produce thousands of events per second. Preserve counters,
		-- but rate-limit trace emission so diagnostics do not become the new flood.
		if not force and record and now - record.lastNotice < 0.25 then
			return
		end
		if record then
			record.lastNotice = now
		end
		self.State:emit("threat-" .. kind, {
			event = event,
			reason = reason,
			summary = self.State.ThreatSummary,
		})
	end

	function ThreatArbiter:_pruneTimes(record, cutoff)
		local retained = {}
		for _, timestamp in ipairs(record.animationTimes) do
			if timestamp >= cutoff then
				retained[#retained + 1] = timestamp
			end
		end
		record.animationTimes = retained
	end

	function ThreatArbiter:observe(event)
		if not self.Settings:get("ThreatGuard.Enabled") then
			return true
		end

		local record, sourceName = self:_record(event)
		local now = self.Clock()
		if event.detector ~= "animation" then
			if (TRUST[event.detector] or 0) >= 3 then
				record.lastCorroboratedAt = now
			end
			return true
		end

		local window = math.max(0.05, self.Settings:get("ThreatGuard.BurstWindow"))
		local limit = math.max(2, math.floor(self.Settings:get("ThreatGuard.BurstLimit")))
		self:_pruneTimes(record, now - window)

		local corroborated = now - record.lastCorroboratedAt
			<= math.max(0, self.Settings:get("ThreatGuard.CorroborationWindow"))
		if record.noisyUntil > now then
			local passInterval = math.max(0.05, self.Settings:get("ThreatGuard.NoisyPassInterval"))
			if corroborated and now - record.lastNoisyPass >= passInterval then
				record.lastNoisyPass = now
				self.State:increment("ThreatCorroborated")
				self:_decision("corroborated", event, "trusted non-animation evidence", record)
				return true
			end
			self.State:increment("ThreatDropped")
			self:_decision("dropped", event, "animation channel quarantined for " .. sourceName, record)
			return false, "animation spam quarantine"
		end

		record.animationTimes[#record.animationTimes + 1] = now
		if #record.animationTimes > limit then
			record.noisyUntil = now + math.max(0.10, self.Settings:get("ThreatGuard.QuarantineSeconds"))
			record.animationTimes = {}
			self.State:increment("ThreatSpamBursts")
			self.State:increment("ThreatDropped")
			self:_decision("quarantined", event, "animation burst from " .. sourceName, record, true)
			return false, "animation burst quarantined"
		end

		return true
	end

	function ThreatArbiter:claim(event, dueAt)
		if not self.Settings:get("ThreatGuard.Enabled") then
			return true, nil
		end

		local record = self:_record(event)
		local existing = record.plansByEvent[event]
		if existing and not existing.settled then
			return true, existing
		end

		local separation = math.max(0, self.Settings:get("ThreatGuard.PlanSeparation"))
		local trust = TRUST[event.detector] or 1
		for _, plan in pairs(record.plans) do
			if not plan.settled and math.abs(plan.dueAt - dueAt) <= separation then
				plan.channels[event.detector] = true
				if trust > plan.trust and self.Scheduler then
					local pending = {}
					for scheduled in pairs(plan.tasks) do
						pending[#pending + 1] = scheduled
					end
					for _, scheduled in ipairs(pending) do
						self.Scheduler:cancel(scheduled, "superseded by stronger threat evidence")
					end
					if not plan.settled then
						plan.pending = 0
						self:settle(plan, nil, "superseded by stronger threat evidence")
					end
					self.State:increment("ThreatPromoted")
					self:_decision("promoted", event, "stronger evidence replaced animation plan", record, true)
					break
				end
				plan.trust = math.max(plan.trust, trust)
				self.State:increment("ThreatCoalesced")
				self:_decision("coalesced", event, "overlapping source plan", record)
				return false, nil, "overlapping threat coalesced"
			end
		end

		local maximum = math.max(1, math.floor(self.Settings:get("ThreatGuard.MaxPendingPerSource")))
		local pendingPlans = countPlans(record)
		-- Animation spam cannot spend the slots reserved for a server effect, part,
		-- or projectile. Higher-trust channels get a small independent allowance so
		-- a noisy Animator cannot starve the evidence that would confirm a real hit.
		local budgetReached = event.detector == "animation" and pendingPlans >= maximum
			or event.detector ~= "animation" and pendingPlans >= maximum + 2
		if budgetReached then
			self.State:increment("ThreatDropped")
			self:_decision("dropped", event, "source plan budget reached", record)
			return false, nil, "source threat budget"
		end

		self.NextPlanID = self.NextPlanID + 1
		local plan = {
			id = self.NextPlanID,
			record = record,
			event = event,
			dueAt = dueAt,
			trust = trust,
			channels = { [event.detector] = true },
			tasks = {},
			pending = 0,
			settled = false,
		}
		record.plans[plan.id] = plan
		record.plansByEvent[event] = plan
		self.ActivePlans = self.ActivePlans + 1
		self.State:increment("ThreatAdmitted")
		self:_decision("admitted", event, "source plan admitted", record)
		return true, plan
	end

	function ThreatArbiter:register(plan, scheduled)
		if not plan or not scheduled or plan.settled or plan.tasks[scheduled] then
			return
		end
		plan.tasks[scheduled] = true
		plan.pending = plan.pending + 1
	end

	function ThreatArbiter:settle(plan, scheduled, reason)
		if not plan or plan.settled then
			return
		end
		if scheduled and plan.tasks[scheduled] then
			plan.tasks[scheduled] = nil
			plan.pending = math.max(0, plan.pending - 1)
		end
		if plan.pending > 0 then
			return
		end

		plan.settled = true
		plan.record.plans[plan.id] = nil
		plan.record.plansByEvent[plan.event] = nil
		self.ActivePlans = math.max(0, self.ActivePlans - 1)
		self:_decision("settled", plan.event, reason or "plan settled", plan.record)
	end

	function ThreatArbiter:reset()
		local function resetRecord(record)
			for _, plan in pairs(record.plans) do
				plan.settled = true
			end
			table.clear(record.animationTimes)
			table.clear(record.plans)
			table.clear(record.plansByEvent)
			record.noisyUntil = 0
			record.lastCorroboratedAt = 0
			record.lastNoisyPass = 0
		end
		for _, record in pairs(self.Sources) do
			resetRecord(record)
		end
		if self.FallbackSource then
			resetRecord(self.FallbackSource)
		end
		self.FallbackSource = nil
		self.ActivePlans = 0
		self.State.ThreatSummary = self:_summary()
		self.State.LastThreat = nil
	end

	function ThreatArbiter:Destroy()
		self:reset()
		table.clear(self.Sources)
	end

	return ThreatArbiter
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/ThreatArbiter.lua

-- BEGIN MODULE: src/Combat/Performance.lua
do
  local moduleName = "src/Combat/Performance.lua"
  local moduleFactory = function()
	local Performance = {}
	Performance.__index = Performance

	function Performance.new(settings)
		return setmetatable({
			Settings = settings,
			Stages = {},
			Backoff = 1,
			LastFrameMs = 0,
		}, Performance)
	end

	function Performance:measure(name, callback, ...)
		local started = os.clock()
		local results = table.pack(pcall(callback, ...))
		local elapsedMs = (os.clock() - started) * 1000
		local stage = self.Stages[name] or { samples = 0, averageMs = 0, peakMs = 0 }
		stage.samples = stage.samples + 1
		stage.averageMs = stage.averageMs + ((elapsedMs - stage.averageMs) / stage.samples)
		stage.peakMs = math.max(stage.peakMs, elapsedMs)
		stage.lastMs = elapsedMs
		self.Stages[name] = stage

		local budget = self.Settings:get("Diagnostics.PerformanceBudgetMs")
		if self.Settings:get("Diagnostics.AdaptiveScan") then
			if elapsedMs > budget then
				self.Backoff = math.min(4, self.Backoff * 1.15)
			else
				self.Backoff = math.max(1, self.Backoff * 0.98)
			end
		end

		if not results[1] then
			error(results[2])
		end
		return table.unpack(results, 2, results.n)
	end

	function Performance:scanInterval(base)
		return math.max(0.01, base * self.Backoff)
	end

	function Performance:snapshot()
		local stages = {}
		for name, stage in pairs(self.Stages) do
			stages[name] = {
				samples = stage.samples,
				averageMs = stage.averageMs,
				peakMs = stage.peakMs,
				lastMs = stage.lastMs,
			}
		end
		return { backoff = self.Backoff, stages = stages }
	end

	return Performance
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Performance.lua

-- BEGIN MODULE: src/Combat/Detection/DetectorEvent.lua
do
  local moduleName = "src/Combat/Detection/DetectorEvent.lua"
  local moduleFactory = function()
	local DetectorEvent = {}
	DetectorEvent.__index = DetectorEvent

	local function findEntity(instance)
		local cursor = instance
		while cursor and cursor ~= workspace do
			if cursor:IsA("Model") and cursor:FindFirstChildWhichIsA("Humanoid") then
				return cursor
			end
			cursor = cursor.Parent
		end
		return nil
	end

	function DetectorEvent.new(detector, id, instance, values)
		values = values or {}
		local entity = values.entity or (instance and findEntity(instance))
		local root = entity and entity:FindFirstChild("HumanoidRootPart")

		return setmetatable({
			detector = detector,
			id = tostring(id or ""),
			instance = instance,
			entity = entity,
			root = root,
			track = values.track,
			position = values.position or (root and root.Position),
			startedAt = values.startedAt or os.clock(),
			metadata = values.metadata or {},
		}, DetectorEvent)
	end

	return DetectorEvent
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Detection/DetectorEvent.lua

-- BEGIN MODULE: src/Combat/Detection/AnimationDetector.lua
do
  local moduleName = "src/Combat/Detection/AnimationDetector.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local Signal = assert(environment.__CLAW_MODULES["src/Runtime/Signal.lua"])
	local DetectorEvent = assert(environment.__CLAW_MODULES["src/Combat/Detection/DetectorEvent.lua"])

	local AnimationDetector = {}
	AnimationDetector.__index = AnimationDetector

	local function cleanID(value)
		return tostring(value or ""):match("(%d+)") or tostring(value or "")
	end

	function AnimationDetector.new(options)
		options = options or {}
		return setmetatable({
			Detected = Signal.new(),
			_source = options.source,
			_ignoreTrack = options.ignoreTrack,
			_accept = options.accept,
			_connections = {},
			_animators = setmetatable({}, { __mode = "k" }),
			_running = false,
		}, AnimationDetector)
	end

	function AnimationDetector:_bind(signal, callback)
		local connection = signal:Connect(callback)
		self._connections[#self._connections + 1] = connection
		return connection
	end

	function AnimationDetector:_emit(animator, track)
		if type(self._ignoreTrack) == "function" then
			local ok, ignored = pcall(self._ignoreTrack, track)
			if ok and ignored then
				return
			end
		end

		local animation = track.Animation
		local id = cleanID(animation and animation.AnimationId)
		if id == "" then
			return
		end
		if type(self._accept) == "function" and not self._accept("animation", id, animator, track) then
			return
		end

		self.Detected:Fire(DetectorEvent.new("animation", id, animator, {
			track = track,
			metadata = {
				priority = tostring(track.Priority),
				looped = track.Looped,
				length = track.Length,
			},
		}))
	end

	function AnimationDetector:_hook(animator)
		if self._animators[animator] then
			return
		end

		local connection = animator.AnimationPlayed:Connect(function(track)
			self:_emit(animator, track)
		end)
		self._animators[animator] = connection
		self._connections[#self._connections + 1] = connection

		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			self:_emit(animator, track)
		end
	end

	function AnimationDetector:start()
		if self._running then
			return
		end
		self._running = true

		local source = type(self._source) == "function" and self._source()
			or self._source
			or workspace:FindFirstChild("Live")
			or workspace

		for _, descendant in ipairs(source:GetDescendants()) do
			if descendant:IsA("Animator") then
				self:_hook(descendant)
			end
		end

		self:_bind(source.DescendantAdded, function(descendant)
			if descendant:IsA("Animator") then
				self:_hook(descendant)
			end
		end)
	end

	function AnimationDetector:stop()
		if not self._running then
			return
		end
		self._running = false
		for _, connection in ipairs(self._connections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(self._connections)
		table.clear(self._animators)
	end

	function AnimationDetector:Destroy()
		self:stop()
		self.Detected:Destroy()
	end

	return AnimationDetector
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Detection/AnimationDetector.lua

-- BEGIN MODULE: src/Combat/Detection/SoundDetector.lua
do
  local moduleName = "src/Combat/Detection/SoundDetector.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local Signal = assert(environment.__CLAW_MODULES["src/Runtime/Signal.lua"])
	local DetectorEvent = assert(environment.__CLAW_MODULES["src/Combat/Detection/DetectorEvent.lua"])

	local SoundDetector = {}
	SoundDetector.__index = SoundDetector

	local function cleanID(value)
		return tostring(value or ""):match("(%d+)") or tostring(value or "")
	end

	function SoundDetector.new(options)
		options = options or {}
		return setmetatable({
			Detected = Signal.new(),
			_source = options.source,
			_accept = options.accept,
			_activeSource = nil,
			_connections = {},
			_sounds = setmetatable({}, { __mode = "k" }),
			_running = false,
		}, SoundDetector)
	end

	function SoundDetector:_emit(sound)
		local id = cleanID(sound.SoundId)
		if id == "" then
			return
		end
		if type(self._accept) == "function" and not self._accept("sound", id, sound) then
			return
		end

		self.Detected:Fire(DetectorEvent.new("sound", id, sound, {
			position = sound.Parent and sound.Parent:IsA("BasePart") and sound.Parent.Position or nil,
			metadata = {
				name = sound.Name,
				playbackSpeed = sound.PlaybackSpeed,
				timePosition = sound.TimePosition,
			},
		}))
	end

	function SoundDetector:_hook(sound)
		if self._sounds[sound] then
			return
		end
		local id = cleanID(sound.SoundId)
		if type(self._accept) == "function" and not self._accept("sound", id, sound) then
			return
		end

		local connection = sound.Played:Connect(function()
			self:_emit(sound)
		end)
		self._sounds[sound] = connection
		self._connections[#self._connections + 1] = connection

		if sound.Playing then
			self:_emit(sound)
		end
	end

	function SoundDetector:start()
		if self._running then
			return
		end
		self._running = true

		local source = type(self._source) == "function" and self._source()
			or self._source
			or workspace:FindFirstChild("Live")
			or workspace
		self._activeSource = source

		for _, descendant in ipairs(source:GetDescendants()) do
			if descendant:IsA("Sound") then
				self:_hook(descendant)
			end
		end

		local connection = source.DescendantAdded:Connect(function(descendant)
			if descendant:IsA("Sound") then
				self:_hook(descendant)
			end
		end)
		self._connections[#self._connections + 1] = connection
	end

	function SoundDetector:refresh()
		if not self._running or not self._activeSource then
			return
		end
		for _, descendant in ipairs(self._activeSource:GetDescendants()) do
			if descendant:IsA("Sound") then
				self:_hook(descendant)
			end
		end
	end

	function SoundDetector:stop()
		if not self._running then
			return
		end
		self._running = false
		for _, connection in ipairs(self._connections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(self._connections)
		table.clear(self._sounds)
		self._activeSource = nil
	end

	function SoundDetector:Destroy()
		self:stop()
		self.Detected:Destroy()
	end

	return SoundDetector
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Detection/SoundDetector.lua

