-- BEGIN MODULE: src/Combat/Detection/EffectDetector.lua
do
  local moduleName = "src/Combat/Detection/EffectDetector.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local CollectionService = game:GetService("CollectionService")
	local Signal = assert(environment.__CLAW_MODULES["src/Runtime/Signal.lua"])
	local DetectorEvent = assert(environment.__CLAW_MODULES["src/Combat/Detection/DetectorEvent.lua"])

	local EffectDetector = {}
	EffectDetector.__index = EffectDetector

	function EffectDetector.new(options)
		options = options or {}
		return setmetatable({
			Detected = Signal.new(),
			_source = options.source,
			_accept = options.accept,
			_connection = nil,
			_running = false,
		}, EffectDetector)
	end

	function EffectDetector:_emit(instance)
		if instance:IsA("Animator") or instance:IsA("Sound") or instance:IsA("BasePart") then
			return
		end

		local tags = CollectionService:GetTags(instance)
		local acceptName = type(self._accept) ~= "function" or self._accept("effect", instance.Name, instance)
		if acceptName then
			self.Detected:Fire(DetectorEvent.new("effect", instance.Name, instance, {
				metadata = {
					className = instance.ClassName,
					tags = tags,
					attributes = instance:GetAttributes(),
				},
			}))
		end

		for _, tag in ipairs(tags) do
			if type(self._accept) ~= "function" or self._accept("effect", tag, instance) then
				self.Detected:Fire(DetectorEvent.new("effect", tag, instance, {
					metadata = { source = "tag", name = instance.Name },
				}))
			end
		end
	end

	function EffectDetector:start()
		if self._running then
			return
		end
		self._running = true

		local source = type(self._source) == "function" and self._source()
			or self._source
			or workspace:FindFirstChild("Live")
			or workspace
		self._connection = source.DescendantAdded:Connect(function(descendant)
			self:_emit(descendant)
		end)
	end

	function EffectDetector:stop()
		self._running = false
		if self._connection then
			pcall(function()
				self._connection:Disconnect()
			end)
			self._connection = nil
		end
	end

	function EffectDetector:Destroy()
		self:stop()
		self.Detected:Destroy()
	end

	return EffectDetector
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Detection/EffectDetector.lua

-- BEGIN MODULE: src/Combat/Detection/ClientEffectDetector.lua
do
  local moduleName = "src/Combat/Detection/ClientEffectDetector.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local Signal = assert(environment.__CLAW_MODULES["src/Runtime/Signal.lua"])
	local DetectorEvent = assert(environment.__CLAW_MODULES["src/Combat/Detection/DetectorEvent.lua"])

	local ReplicatedStorage = game:GetService("ReplicatedStorage")

	local ClientEffectDetector = {}
	ClientEffectDetector.__index = ClientEffectDetector

	local CHANNELS = {
		ClientEffect = true,
		ClientEffectLarge = true,
		ClientEffectDirect = true,
	}

	local OWNER_KEYS = {
		"owner",
		"Owner",
		"caster",
		"Caster",
		"character",
		"Character",
		"entity",
		"Entity",
		"source",
		"Source",
	}

	local POSITION_KEYS = {
		"position",
		"Position",
		"pos",
		"Pos",
		"cframe",
		"CFrame",
		"cf",
		"CF",
		"part",
		"Part",
	}

	local function humanoidModel(instance)
		if typeof(instance) ~= "Instance" then
			return nil
		end
		local model
		if instance:IsA("Model") then
			model = instance
		elseif instance:IsA("BasePart") or instance:IsA("Attachment") then
			model = instance:FindFirstAncestorWhichIsA("Model")
		end
		if not model or not model:FindFirstChildWhichIsA("Humanoid") then
			return nil
		end
		local live = workspace:FindFirstChild("Live")
		if live and model ~= live and not model:IsDescendantOf(live) then
			return nil
		end
		return model
	end

	local function explicitOwner(data)
		for _, key in ipairs(OWNER_KEYS) do
			local owner = humanoidModel(data[key])
			if owner then
				return owner, "explicit"
			end
		end
		return nil
	end

	local function boundedOwner(data)
		local explicit, confidence = explicitOwner(data)
		if explicit then
			return explicit, confidence
		end

		local seen = {}
		local inspected = 0
		local function visit(value, depth)
			if inspected >= 32 or depth > 2 then
				return nil
			end
			inspected = inspected + 1
			local owner = humanoidModel(value)
			if owner then
				return owner
			end
			if type(value) ~= "table" or seen[value] then
				return nil
			end
			seen[value] = true
			for _, child in pairs(value) do
				local found = visit(child, depth + 1)
				if found then
					return found
				end
				if inspected >= 32 then
					break
				end
			end
			return nil
		end
		local owner = visit(data, 0)
		return owner, owner and "inferred" or "none"
	end

	local function originFor(data, owner)
		local root = owner and owner:FindFirstChild("HumanoidRootPart")
		if root and root:IsA("BasePart") then
			return root, root.Position
		end
		for _, key in ipairs(POSITION_KEYS) do
			local value = data[key]
			if typeof(value) == "Vector3" then
				return nil, value
			elseif typeof(value) == "CFrame" then
				return nil, value.Position
			elseif typeof(value) == "Instance" then
				if value:IsA("BasePart") then
					return value, value.Position
				elseif value:IsA("Attachment") then
					return value.Parent, value.WorldPosition
				end
			end
		end
		return owner, nil
	end

	local function shallowSnapshot(data)
		local snapshot = {}
		local count = 0
		for key, value in pairs(data) do
			if count >= 32 then
				break
			end
			local valueType = typeof(value)
			if
				type(key) == "string"
				and (
					valueType == "string"
					or valueType == "number"
					or valueType == "boolean"
					or valueType == "Vector3"
					or valueType == "CFrame"
					or valueType == "Instance"
				)
			then
				snapshot[key] = value
				count = count + 1
			end
		end
		return snapshot
	end

	local function rounded(value)
		return math.floor(value * 4 + 0.5) / 4
	end

	local function fingerprintFor(id, owner, position)
		local ownerKey = owner and owner:GetFullName() or "?"
		local positionKey = "?"
		if typeof(position) == "Vector3" then
			positionKey = string.format("%.2f,%.2f,%.2f", rounded(position.X), rounded(position.Y), rounded(position.Z))
		end
		return tostring(id) .. "|" .. ownerKey .. "|" .. positionKey
	end

	function ClientEffectDetector.new(options)
		options = options or {}
		return setmetatable({
			Detected = Signal.new(),
			_source = options.source,
			_accept = options.accept,
			_connections = {},
			_hooked = setmetatable({}, { __mode = "k" }),
			_recent = {},
			_running = false,
			Stats = {
				ClientEffect = 0,
				ClientEffectLarge = 0,
				ClientEffectDirect = 0,
				Deduplicated = 0,
			},
		}, ClientEffectDetector)
	end

	function ClientEffectDetector:_bind(signal, callback)
		local connection = signal:Connect(callback)
		self._connections[#self._connections + 1] = connection
		return connection
	end

	function ClientEffectDetector:_deduplicated(fingerprint, channel, now)
		local previous = self._recent[fingerprint]
		self._recent[fingerprint] = { channel = channel, at = now }
		if previous and previous.channel ~= channel and now - previous.at <= 0.03 then
			self.Stats.Deduplicated = self.Stats.Deduplicated + 1
			return true
		end
		if math.random(1, 32) == 1 then
			for key, value in pairs(self._recent) do
				if now - value.at > 0.25 then
					self._recent[key] = nil
				end
			end
		end
		return false
	end

	function ClientEffectDetector:_emit(channel, name, data)
		local id = tostring(name or "")
		if id == "" then
			return
		end
		if type(self._accept) == "function" and not self._accept("effect", id, nil) then
			return
		end
		if type(data) ~= "table" then
			data = {}
		end

		local owner, confidence = boundedOwner(data)
		local instance, position = originFor(data, owner)
		local fingerprint = fingerprintFor(id, owner, position)
		local now = os.clock()
		if self:_deduplicated(fingerprint, channel, now) then
			return
		end

		self.Stats[channel] = (self.Stats[channel] or 0) + 1
		local snapshot = shallowSnapshot(data)
		self.Detected:Fire(DetectorEvent.new("effect", id, instance, {
			entity = owner,
			position = position,
			startedAt = now,
			metadata = {
				channel = channel,
				attributes = snapshot,
				payload = snapshot,
				ownershipConfidence = confidence,
				fingerprint = fingerprint,
			},
		}))
	end

	function ClientEffectDetector:_hook(channel, remote)
		if self._hooked[remote] or not CHANNELS[channel] then
			return
		end
		local signal
		if remote:IsA("RemoteEvent") then
			signal = remote.OnClientEvent
		elseif remote:IsA("BindableEvent") then
			signal = remote.Event
		end
		if not signal then
			return
		end
		self._hooked[remote] = true
		self:_bind(signal, function(name, data)
			self:_emit(channel, name, data)
		end)
	end

	function ClientEffectDetector:start()
		if self._running then
			return
		end
		self._running = true
		local requests = type(self._source) == "function" and self._source()
			or self._source
			or ReplicatedStorage:FindFirstChild("Requests")
		if not requests then
			self:_bind(ReplicatedStorage.ChildAdded, function(child)
				if self._running and child.Name == "Requests" then
					for channel in pairs(CHANNELS) do
						local remote = child:FindFirstChild(channel)
						if remote then
							self:_hook(channel, remote)
						end
					end
					self:_bind(child.ChildAdded, function(remote)
						if CHANNELS[remote.Name] then
							self:_hook(remote.Name, remote)
						end
					end)
				end
			end)
			return
		end
		for channel in pairs(CHANNELS) do
			local remote = requests:FindFirstChild(channel)
			if remote then
				self:_hook(channel, remote)
			end
		end
		self:_bind(requests.ChildAdded, function(child)
			if CHANNELS[child.Name] then
				self:_hook(child.Name, child)
			end
		end)
	end

	function ClientEffectDetector:stop()
		if not self._running then
			return
		end
		self._running = false
		for _, connection in ipairs(self._connections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(self._connections)
		table.clear(self._hooked)
		table.clear(self._recent)
	end

	function ClientEffectDetector:Destroy()
		self:stop()
		self.Detected:Destroy()
	end

	return ClientEffectDetector
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Detection/ClientEffectDetector.lua

-- BEGIN MODULE: src/Combat/Detection/DetectorHub.lua
do
  local moduleName = "src/Combat/Detection/DetectorHub.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local modules = environment.__CLAW_MODULES
	local Signal = assert(modules["src/Runtime/Signal.lua"])
	local AnimationDetector = assert(modules["src/Combat/Detection/AnimationDetector.lua"])
	local SoundDetector = assert(modules["src/Combat/Detection/SoundDetector.lua"])
	local PartDetector = assert(modules["src/Combat/Detection/PartDetector.lua"])
	local EffectDetector = assert(modules["src/Combat/Detection/EffectDetector.lua"])
	local ClientEffectDetector = assert(modules["src/Combat/Detection/ClientEffectDetector.lua"])
	local Players = game:GetService("Players")

	local DetectorHub = {}
	DetectorHub.__index = DetectorHub

	function DetectorHub.new(settings, timings, options)
		options = options or {}
		local shared = options.shared or {}
		local function combatAnimation(track)
			if not track then
				return false
			end
			local ok, priority, looped, length = pcall(function()
				return track.Priority, track.Looped, track.Length
			end)
			if not ok or looped then
				return false
			end
			local actionPriority = priority == Enum.AnimationPriority.Action
				or priority == Enum.AnimationPriority.Action2
				or priority == Enum.AnimationPriority.Action3
				or priority == Enum.AnimationPriority.Action4
			if not actionPriority then
				return false
			end
			local maximum = settings:get("Defense.UnknownAnimationMaxLength")
			return length <= 0 or length <= maximum
		end
		local function accept(category, id, instance, track)
			-- Lycoris never sends the local character's animation tracks into the
			-- defense pipeline. Local attack assistance has its own animator hook,
			-- so rejecting them here removes misleading defense events without
			-- affecting action rolling, feints, or animation-speed assistance.
			local localCharacter = Players.LocalPlayer.Character
			if
				category == "animation"
				and localCharacter
				and instance
				and instance:IsDescendantOf(localCharacter)
			then
				return false
			end
			if timings:has(category, id) then
				return true
			end
			-- Unknown animation defense is a separate, visible policy. It catches
			-- newly introduced weapon animations without opening noisy sound, part,
			-- or effect detectors when indexed-only detection is selected.
			if category == "animation"
				and settings:get("Detection.UnknownAnimations")
				and settings:get("Enabled")
				and settings:get("Defense.Enabled")
			then
				return combatAnimation(track)
			end
			return not settings:get("Detection.OnlyConfigured")
		end
		local function detectorOptions(specific)
			local combined = {}
			for key, value in pairs(shared) do
				combined[key] = value
			end
			for key, value in pairs(specific or {}) do
				combined[key] = value
			end
			combined.accept = combined.accept or accept
			return combined
		end
		local self = setmetatable({
			Settings = settings,
			Timings = timings,
			Detected = Signal.new(),
			Connections = {},
			Running = false,
			Detectors = {
				Animations = AnimationDetector.new(detectorOptions(options.animation)),
				Sounds = SoundDetector.new(detectorOptions(options.sound)),
				Parts = PartDetector.new(detectorOptions(options.part)),
				Effects = EffectDetector.new(detectorOptions(options.effect)),
				ClientEffects = ClientEffectDetector.new(detectorOptions(options.clientEffect)),
			},
		}, DetectorHub)

		for settingName, detector in pairs(self.Detectors) do
			self.Connections[#self.Connections + 1] = detector.Detected:Connect(function(event)
				local setting = settingName == "ClientEffects" and "Effects" or settingName
				if self.Settings:get("Detection." .. setting) then
					self.Detected:Fire(event)
				end
			end)
		end

		self.Connections[#self.Connections + 1] = timings.Changed:Connect(function()
			self.Detectors.Sounds:refresh()
		end)

		return self
	end

	function DetectorHub:start()
		if self.Running then
			return
		end
		self.Running = true
		self:sync()
	end

	function DetectorHub:sync(settingName)
		if not self.Running then
			return
		end
		for name, detector in pairs(self.Detectors) do
			local setting = name == "ClientEffects" and "Effects" or name
			if not settingName or setting == settingName then
				if self.Settings:get("Detection." .. setting) then
					detector:start()
				else
					detector:stop()
				end
			end
		end
	end

	function DetectorHub:stop()
		if not self.Running then
			return
		end
		self.Running = false
		for _, detector in pairs(self.Detectors) do
			detector:stop()
		end
	end

	function DetectorHub:refresh()
		if self.Running then
			self.Detectors.Sounds:refresh()
		end
	end

	function DetectorHub:Destroy()
		self:stop()
		for _, connection in ipairs(self.Connections) do
			connection:Disconnect()
		end
		table.clear(self.Connections)
		for _, detector in pairs(self.Detectors) do
			detector:Destroy()
		end
		self.Detected:Destroy()
	end

	return DetectorHub
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Detection/DetectorHub.lua

-- BEGIN MODULE: src/Combat/NativeInputBridge.lua
do
  local moduleName = "src/Combat/NativeInputBridge.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G

	local Players = game:GetService("Players")
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local RunService = game:GetService("RunService")

	local NativeInputBridge = {}
	NativeInputBridge.__index = NativeInputBridge

	local ALLOWED_INPUT_KEYS = {
		Left = true,
		Right = true,
		W = true,
		A = true,
		S = true,
		D = true,
		Thumbstick1 = true,
		C = true,
		f = true,
		H = true,
		Space = true,
		ctrl = true,
	}

	local function executorFunction(name)
		local callback = rawget(environment, name)
		return type(callback) == "function" and callback or nil
	end

	local function debugFunction(name)
		local debugLibrary = rawget(environment, "debug") or debug
		local callback = debugLibrary and debugLibrary[name]
		return type(callback) == "function" and callback or executorFunction(name)
	end

	local function rawMetatable(value)
		local callback = executorFunction("getrawmetatable")
		if callback then
			local ok, result = pcall(callback, value)
			return ok and result or nil
		end
		return getmetatable(value)
	end

	local function isExecutorFunction(value)
		for _, name in ipairs({ "iscclosure", "isexecutorclosure", "checkclosure" }) do
			local callback = executorFunction(name)
			if callback then
				local ok, result = pcall(callback, value)
				if ok and result then
					return true
				end
			end
		end
		return false
	end

	local function tableLength(value)
		local count = 0
		for _ in pairs(value) do
			count = count + 1
		end
		return count
	end

	local function validInputTable(value)
		if type(value) ~= "table" or rawMetatable(value) then
			return false
		end
		for key, child in pairs(value) do
			if not ALLOWED_INPUT_KEYS[key] or type(child) ~= "boolean" then
				return false
			end
		end
		return tableLength(value) <= 12
	end

	local function includes(values, expected)
		for _, value in pairs(values or {}) do
			if value == expected then
				return true
			end
		end
		return false
	end

	local function numberToString(number, iterations)
		local result = ""
		for _ = 1, iterations do
			local byte = number % 256
			result = string.char(byte) .. result
			number = (number - byte) / 256
		end
		return result
	end

	local function stringToNumber(value, offset)
		local number = 0
		for index = offset, offset + 3 do
			number = number * 256 + string.byte(value, index)
		end
		return number
	end

	local function shaPreprocess(message)
		return message
			.. string.char(128)
			.. string.rep(string.char(0), 64 - (#message + 9) % 64)
			.. numberToString(8 * #message, 8)
	end

	local function shaDigest(message, offset, hashes, randomTable)
		local chunks = {}
		for index = 1, 16 do
			chunks[index] = stringToNumber(message, offset + ((index - 1) * 4))
		end
		for index = 17, 64 do
			local first = chunks[index - 15]
			local second = chunks[index - 2]
			chunks[index] = chunks[index - 16]
				+ bit32.bxor(bit32.rrotate(first, 7), bit32.rrotate(first, 18), bit32.rshift(first, 3))
				+ chunks[index - 7]
				+ bit32.bxor(bit32.rrotate(second, 17), bit32.rrotate(second, 19), bit32.rshift(second, 10))
		end

		local a, b, c, d = hashes[1], hashes[2], hashes[3], hashes[4]
		local e, f, g, h = hashes[5], hashes[6], hashes[7], hashes[8]
		for index = 1, 64 do
			local first = bit32.bxor(bit32.rrotate(a, 2), bit32.rrotate(a, 13), bit32.rrotate(a, 22))
				+ bit32.bxor(bit32.band(a, b), bit32.band(a, c), bit32.band(b, c))
			local second = bit32.bxor(bit32.rrotate(e, 6), bit32.rrotate(e, 11), bit32.rrotate(e, 25))
			local choose = bit32.bxor(bit32.band(e, f), bit32.band(bit32.bnot(e), g))
			local temporary = h + second + choose + randomTable[index] + chunks[index]
			h, g, f, e, d, c, b, a = g, f, e, d + temporary, c, b, a, temporary + first
		end

		hashes[1] = bit32.band(hashes[1] + a)
		hashes[2] = bit32.band(hashes[2] + b)
		hashes[3] = bit32.band(hashes[3] + c)
		hashes[4] = bit32.band(hashes[4] + d)
		hashes[5] = bit32.band(hashes[5] + e)
		hashes[6] = bit32.band(hashes[6] + f)
		hashes[7] = bit32.band(hashes[7] + g)
		hashes[8] = bit32.band(hashes[8] + h)
	end

	local function hashRemote(name, randomTable)
		local hashes = {
			1779033703,
			3144134277,
			1013904242,
			2773480762,
			1359893119,
			2600822924,
			528734635,
			1541459225,
		}
		local processed = shaPreprocess(name)
		for offset = 1, #name, 64 do
			shaDigest(processed, offset, hashes, randomTable)
		end
		local result = ""
		for _, value in ipairs(hashes) do
			result = result .. numberToString(value, 4)
		end
		return result
	end

	local function upvaluesOf(callback)
		local getter = debugFunction("getupvalues")
		if not getter then
			return {}
		end
		local ok, values = pcall(getter, callback)
		return ok and type(values) == "table" and values or {}
	end

	local function valueAtUpvalue(callback, index)
		local getter = debugFunction("getupvalue")
		if not getter then
			return nil
		end
		local results = table.pack(pcall(getter, callback, index))
		if not results[1] then
			return nil
		end
		if type(results[2]) == "table" then
			return results[2]
		end
		return type(results[3]) == "table" and results[3] or nil
	end

	local function remoteContainer(value)
		if type(value) ~= "table" then
			return nil
		end
		for _, candidate in pairs(value) do
			if type(candidate) == "table" and not rawMetatable(candidate) and #candidate == 0 and not candidate[10] then
				return candidate
			end
		end
		return nil
	end

	local function randomConstants(value)
		if type(value) ~= "table" or rawMetatable(value) or #value ~= 68 then
			return nil
		end
		local firstIndex, firstValue = next(value)
		if type(firstIndex) == "number" and type(firstValue) == "number" and firstValue >= 100000 and firstValue <= 100000000 then
			return value
		end
		return nil
	end

	function NativeInputBridge.new()
		local self = setmetatable({
			Initialized = false,
			Ready = false,
			Status = "not initialized",
			RemoteTable = nil,
			RandomTable = nil,
			InputData = nil,
			SprintFunction = nil,
			Remotes = {},
			Queue = {},
			NextQueueID = 0,
			NextRetry = 0,
			NextBlockRetry = 0,
			BlockRetryCount = 0,
			ReleaseSent = true,
			LastTransition = "idle",
			Stats = {
				Blocks = 0,
				Unblocks = 0,
				Retries = 0,
				Coalesced = 0,
				Dodges = 0,
				DodgeCancels = 0,
			},
			RenderConnection = nil,
			CharacterConnection = nil,
			EffectModule = nil,
		}, NativeInputBridge)
		self.CharacterConnection = Players.LocalPlayer.CharacterAdded:Connect(function()
			self:invalidate("character changed")
		end)
		return self
	end

	function NativeInputBridge:_effectModule()
		if self.EffectModule then
			return self.EffectModule
		end
		local source = ReplicatedStorage:FindFirstChild("EffectReplicator")
		if source then
			local ok, result = pcall(require, source)
			if ok then
				self.EffectModule = result
			end
		end
		return self.EffectModule
	end

	function NativeInputBridge:_hasEffect(name)
		local module = self:_effectModule()
		if not module then
			return false
		end
		local finder = module.FindEffect
		if type(finder) ~= "function" then
			return false
		end
		local ok, result = pcall(finder, module, name)
		return ok and result ~= nil and result ~= false
	end

	function NativeInputBridge:_removeEffect(name)
		local module = self:_effectModule()
		local finder = module and module.FindEffect
		if type(finder) ~= "function" then
			return
		end
		local ok, effect = pcall(finder, module, name)
		if ok and effect and type(effect.Remove) == "function" then
			pcall(effect.Remove, effect)
		end
	end

	function NativeInputBridge:_scanGC()
		local getGC = executorFunction("getgc")
		if not getGC then
			return false, "getgc unavailable"
		end
		local ok, values = pcall(getGC, true)
		if not ok or type(values) ~= "table" then
			ok, values = pcall(getGC)
		end
		if not ok or type(values) ~= "table" then
			return false, "getgc failed"
		end
		local getInfo = debugFunction("getinfo")

		for _, value in pairs(values) do
			if not self.RandomTable then
				self.RandomTable = randomConstants(value)
			end
			if type(value) == "function" and not isExecutorFunction(value) then
				if not self.RemoteTable and getInfo then
					local infoOK, info = pcall(getInfo, value)
					local source = infoOK
						and info
						and (tostring(info.source or "") .. " " .. tostring(info.short_src or ""))
						or ""
					if string.find(source, "KeyHandler", 1, true) then
						self.RemoteTable = remoteContainer(valueAtUpvalue(value, 10))
					end
				end
				if not self.SprintFunction and getInfo then
					local infoOK, info = pcall(getInfo, value)
					if infoOK and info and info.name == "Sprint" and next(upvaluesOf(value)) ~= nil then
						self.SprintFunction = value
					end
				end
			end
			if self.RemoteTable and self.RandomTable and self.SprintFunction then
				break
			end
		end
		return self.RemoteTable ~= nil and self.RandomTable ~= nil,
			self.RemoteTable and (self.RandomTable and nil or "hash constants unavailable") or "key-handler remotes unavailable"
	end

	function NativeInputBridge:_scanInputData()
		local getConnections = executorFunction("getconnections")
		local getConstants = debugFunction("getconstants")
		if not getConnections or not getConstants then
			return nil
		end
		local ok, connections = pcall(getConnections, RunService.RenderStepped)
		if not ok or type(connections) ~= "table" then
			return nil
		end
		for _, connection in pairs(connections) do
			local callback
			pcall(function()
				callback = connection.Function
			end)
			if type(callback) ~= "function" or isExecutorFunction(callback) then
				continue
			end
			local constantsOK, constants = pcall(getConstants, callback)
			if not constantsOK or not includes(constants, ".lastHBCheck") then
				continue
			end
			for _, value in pairs(upvaluesOf(callback)) do
				if validInputTable(value) then
					return value
				end
			end
		end
		return nil
	end

	function NativeInputBridge:_remote(name)
		local cached = self.Remotes[name]
		if cached and cached.Parent then
			return cached
		end
		if not self.RemoteTable or not self.RandomTable then
			return nil
		end
		local remote = self.RemoteTable[hashRemote(name, self.RandomTable)]
		if typeof(remote) == "Instance" then
			self.Remotes[name] = remote
			return remote
		end
		return nil
	end

	function NativeInputBridge:_fire(remote, ...)
		if not remote then
			return false, "remote unavailable"
		end
		local ok, result = pcall(remote.FireServer, remote, ...)
		return ok, ok and nil or tostring(result)
	end

	function NativeInputBridge:_sendBlock(retry)
		local fired, reason = self:_fire(self:_remote("Block"))
		if fired then
			self.Stats.Blocks = self.Stats.Blocks + 1
			if retry then
				self.Stats.Retries = self.Stats.Retries + 1
			end
			self.LastTransition = retry and "block retry" or "block sent"
		else
			self.LastTransition = "block failed: " .. tostring(reason)
		end
		return fired, reason
	end

	function NativeInputBridge:_sendUnblock(detail)
		local fired, reason = self:_fire(self:_remote("Unblock"))
		if fired then
			self.Stats.Unblocks = self.Stats.Unblocks + 1
			self.LastTransition = "unblock sent: " .. tostring(detail or "release")
		else
			self.LastTransition = "unblock failed: " .. tostring(reason)
		end
		return fired, reason
	end

	function NativeInputBridge:isBusy()
		return next(self.Queue) ~= nil or not self.ReleaseSent or self:_hasEffect("Blocking")
	end

	function NativeInputBridge:canParry()
		if self:_hasEffect("ParryCool") then
			return false, "parry-cooldown"
		end
		return true
	end

	function NativeInputBridge:canDodge()
		for _, effect in ipairs({ "NoRoll", "PreventRoll", "Dodged", "Dodge", "Stun" }) do
			if self:_hasEffect(effect) then
				return false, effect == "Stun" and "stunned" or "dodge-cooldown"
			end
		end
		return true
	end

	function NativeInputBridge:isDodging()
		return self:_hasEffect("ClientDodge")
			or self:_hasEffect("Dodge")
			or self:_hasEffect("DodgeFrame")
			or self:_hasEffect("DodgedFrame")
			or self:_hasEffect("Immortal")
			or self:_hasEffect("NoRoll")
	end

	function NativeInputBridge:directDodge()
		local ready, reason = self:initialize()
		if not ready then
			return false, reason
		end
		local canDodge, dodgeReason = self:canDodge()
		if not canDodge then
			return false, dodgeReason
		end
		if not self.InputData then
			return false, "native input state unavailable"
		end
		if self:_hasEffect("Blocking") or next(self.Queue) ~= nil then
			table.clear(self.Queue)
			self:_sendUnblock("dodge")
			self.ReleaseSent = true
		end
		local fired, fireReason = self:_fire(self:_remote("Dodge"), "roll", nil, nil, false)
		if fired then
			self.Stats.Dodges = self.Stats.Dodges + 1
			self.LastTransition = "direct dodge sent"
		else
			self.LastTransition = "direct dodge failed: " .. tostring(fireReason)
		end
		return fired, fired and "LycorisNativeDodge" or fireReason
	end

	function NativeInputBridge:stopDodge(direct)
		local ready, reason = self:initialize()
		if not ready then
			return false, reason
		end
		if not self.InputData then
			return false, "native input state unavailable"
		end
		local fired, fireReason
		if direct then
			fired, fireReason = self:_fire(
				self:_remote("StopDodge"),
				self.InputData,
				self:_hasEffect("LightAttack"),
				true
			)
		else
			fired, fireReason = self:_fire(
				self:_remote("StopDodge"),
				self.InputData,
				self:_hasEffect("LightAttack")
			)
		end
		if fired then
			self.Stats.DodgeCancels = self.Stats.DodgeCancels + 1
			self.LastTransition = "dodge cancel sent"
		else
			self.LastTransition = "dodge cancel failed: " .. tostring(fireReason)
		end
		return fired, fired and "LycorisNativeStopDodge" or fireReason
	end

	function NativeInputBridge:releaseAll(reason)
		local detail = reason or "safe reset"
		local blocking = self:_hasEffect("Blocking")
		local shouldUnblock = blocking or not self.ReleaseSent or next(self.Queue) ~= nil

		if self.InputData then
			self.InputData.f = false
		end
		table.clear(self.Queue)
		self.NextBlockRetry = 0
		self.BlockRetryCount = 0

		local ok, releaseReason = true, nil
		if shouldUnblock and self.Ready then
			ok, releaseReason = self:_sendUnblock(detail)
		end
		self.ReleaseSent = true
		self.LastTransition = ok and ("released: " .. detail)
			or ("release failed: " .. tostring(releaseReason))
		return ok, releaseReason or detail
	end

	function NativeInputBridge:_updateQueue()
		local now = os.clock()
		local hadEntries = next(self.Queue) ~= nil
		local blocking = self:_hasEffect("Blocking")
		for id, item in pairs(self.Queue) do
			if now >= item.expires or (item.sent and item.deflect and blocking) then
				self.Queue[id] = nil
			end
		end
		local active = next(self.Queue) ~= nil
		local hasPending = false
		for _, item in pairs(self.Queue) do
			if not item.sent then
				hasPending = true
				break
			end
		end

		if active and hasPending then
			-- A new parry arrived before the previous Blocking effect cleared. Keep
			-- input released until the server acknowledges that release, then send one
			-- fresh Block edge for every coalesced pending request.
			if self.InputData then
				self.InputData.f = false
			end
			if blocking then
				if not self.ReleaseSent then
					self:_sendUnblock("waiting for clear")
					self.ReleaseSent = true
				end
			elseif not self:_hasEffect("Action") and not self:_hasEffect("Knocked") then
				local fired = self:_sendBlock(false)
				if fired then
					for _, item in pairs(self.Queue) do
						item.sent = true
					end
					if self.InputData then
						self.InputData.f = true
					end
					self.ReleaseSent = false
					self.BlockRetryCount = 0
					self.NextBlockRetry = now + 0.12
				end
			end
		elseif active then
			if self.InputData then
				self.InputData.f = true
			end
			if
				not blocking
				and now >= self.NextBlockRetry
				and self.BlockRetryCount < 1
				and not self:_hasEffect("Action")
				and not self:_hasEffect("Knocked")
			then
				self.BlockRetryCount = self.BlockRetryCount + 1
				self.NextBlockRetry = now + 0.12
				self:_sendBlock(true)
			end
		else
			if self.InputData then
				self.InputData.f = false
			end
			-- Release once when the queue drains. The old implementation sent this
			-- remote every rendered frame while the Blocking effect lingered.
			if (hadEntries or blocking) and not self.ReleaseSent then
				self:_sendUnblock("queue drained")
				self.ReleaseSent = true
			end
		end
	end

	function NativeInputBridge:_startQueue()
		if self.RenderConnection then
			return
		end
		self.RenderConnection = RunService.RenderStepped:Connect(function()
			self:_updateQueue()
		end)
	end

	function NativeInputBridge:initialize(force)
		if self.Ready then
			return true, self.Status
		end
		if not force and os.clock() < self.NextRetry then
			return false, self.Status
		end
		self.Initialized = true
		self.NextRetry = os.clock() + 2
		local scanned, reason = self:_scanGC()
		if not scanned then
			self.Ready = false
			self.Status = reason or "native scan failed"
			return false, self.Status
		end
		self.InputData = self:_scanInputData()
		local block = self:_remote("Block")
		local unblock = self:_remote("Unblock")
		if not block or not unblock then
			self.Ready = false
			self.Status = "Block/Unblock remotes unresolved"
			return false, self.Status
		end
		self.Ready = true
		self.Status = self.InputData and "native remotes + input state" or "native remotes"
		self:_startQueue()
		return true, self.Status
	end

	function NativeInputBridge:block(duration, deflect)
		local ready, reason = self:initialize()
		if not ready then
			return false, reason
		end
		if self:_hasEffect("CastingSpell") then
			return false, "casting spell"
		end
		self:_removeEffect("M1Buffering")
		if self.SprintFunction then
			pcall(self.SprintFunction, false)
		end

		local now = os.clock()
		local blocking = self:_hasEffect("Blocking")
		local hasSent = false
		for _, item in pairs(self.Queue) do
			if item.sent then
				hasSent = true
				break
			end
		end
		self.NextQueueID = self.NextQueueID + 1
		local item = {
			deflect = deflect == true,
			expires = now
				+ (deflect and math.max(0.20, tonumber(duration) or 0) or math.max(0.05, tonumber(duration) or 0.30)),
			sent = false,
		}
		self.Queue[self.NextQueueID] = item

		if blocking then
			self.LastTransition = "queued until block clears"
			if self.InputData then
				self.InputData.f = false
			end
			return true, "LycorisNativeQueued"
		end
		if hasSent then
			-- Multiple detections inside one unacknowledged parry window share the
			-- already-sent Block edge instead of multiplying remote traffic.
			item.sent = true
			self.Stats.Coalesced = self.Stats.Coalesced + 1
			self.LastTransition = "coalesced"
			return true, "LycorisNativeCoalesced"
		end

		local fired, fireReason = self:_sendBlock(false)
		if not fired then
			self.Queue[self.NextQueueID] = nil
			return false, fireReason
		end
		item.sent = true
		self.ReleaseSent = false
		self.BlockRetryCount = 0
		self.NextBlockRetry = now + 0.12
		if self.InputData then
			self.InputData.f = true
		end
		return true, "LycorisNative"
	end

	function NativeInputBridge:invalidate(reason)
		if self.RenderConnection then
			self.RenderConnection:Disconnect()
			self.RenderConnection = nil
		end
		if self.InputData then
			self.InputData.f = false
		end
		table.clear(self.Queue)
		self.NextBlockRetry = 0
		self.BlockRetryCount = 0
		self.ReleaseSent = true
		self.LastTransition = "idle"
		self.InputData = nil
		self.SprintFunction = nil
		self.Initialized = false
		self.Ready = false
		self.NextRetry = 0
		self.Status = reason or "invalidated"
	end

	function NativeInputBridge:Destroy()
		if self.Ready then
			self:_sendUnblock("destroyed")
		end
		self:invalidate("destroyed")
		if self.CharacterConnection then
			self.CharacterConnection:Disconnect()
			self.CharacterConnection = nil
		end
	end

	return NativeInputBridge
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/NativeInputBridge.lua

-- BEGIN MODULE: src/Combat/InputAdapter.lua
do
  local moduleName = "src/Combat/InputAdapter.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local UserInputService = game:GetService("UserInputService")
	local NativeInputBridge = assert(environment.__CLAW_MODULES["src/Combat/NativeInputBridge.lua"])

	local InputAdapter = {}
	InputAdapter.__index = InputAdapter

	local KEY_CODES = {}
	for _, keyCode in ipairs(Enum.KeyCode:GetEnumItems()) do
		KEY_CODES[string.lower(keyCode.Name)] = keyCode
	end

	local VIRTUAL_KEY_CODES = {
		Backspace = 0x08,
		Tab = 0x09,
		Return = 0x0D,
		Escape = 0x1B,
		Space = 0x20,
		PageUp = 0x21,
		PageDown = 0x22,
		End = 0x23,
		Home = 0x24,
		Left = 0x25,
		Up = 0x26,
		Right = 0x27,
		Down = 0x28,
		Insert = 0x2D,
		Delete = 0x2E,
		LeftShift = 0x10,
		RightShift = 0x10,
		LeftControl = 0x11,
		RightControl = 0x11,
		LeftAlt = 0x12,
		RightAlt = 0x12,
	}

	local function virtualKeyCode(keyCode)
		local name = keyCode.Name
		if #name == 1 then
			local byte = string.byte(string.upper(name))
			if byte and ((byte >= 0x30 and byte <= 0x39) or (byte >= 0x41 and byte <= 0x5A)) then
				return byte
			end
		end
		local functionNumber = string.match(name, "^F(%d+)$")
		if functionNumber then
			local index = tonumber(functionNumber)
			if index and index >= 1 and index <= 24 then
				return 0x6F + index
			end
		end
		return VIRTUAL_KEY_CODES[name] or keyCode.Value
	end

	local function firstFunction(names)
		for _, name in ipairs(names) do
			local callback = rawget(environment, name)
			if type(callback) == "function" then
				return callback, name
			end
		end
		return nil, nil
	end

	function InputAdapter.new(options)
		options = options or {}
		local virtualInput
		pcall(function()
			virtualInput = game:GetService("VirtualInputManager")
		end)

		return setmetatable({
			VirtualInput = virtualInput,
			Custom = options.custom or {},
			Settings = options.settings,
			LastInput = nil,
			Native = NativeInputBridge.new(),
			DodgeCancelGeneration = 0,
		}, InputAdapter)
	end

	function InputAdapter:warmup()
		return self.Native:initialize(true)
	end

	function InputAdapter:nativeBlock(duration, deflect)
		local ok, detail = self.Native:block(duration, deflect)
		self.LastInput = {
			kind = "native",
			name = deflect and "Parry" or "Block",
			backend = ok and "LycorisNative" or "fallback",
			isDown = ok,
			ok = ok,
			detail = detail,
			at = os.clock(),
		}
		return ok, detail
	end

	function InputAdapter:directDodge()
		local ok, detail = self.Native:directDodge()
		self.LastInput = {
			kind = "native",
			name = "Dodge",
			backend = ok and "LycorisNativeDodge" or "fallback",
			isDown = ok,
			ok = ok,
			detail = detail,
			at = os.clock(),
		}
		return ok, detail
	end

	function InputAdapter:scheduleDodgeCancel(delaySeconds, direct)
		local delay = math.max(0, tonumber(delaySeconds) or 0)
		self.DodgeCancelGeneration = self.DodgeCancelGeneration + 1
		local generation = self.DodgeCancelGeneration
		task.spawn(function()
			local earliest = os.clock() + delay
			local observed = direct == true
			while os.clock() < earliest do
				if generation ~= self.DodgeCancelGeneration then
					return
				end
				if not direct and self.Native:isDodging() then
					observed = true
				end
				task.wait()
			end

			-- A normal Q dodge is created by the game's InputClient, so wait for its
			-- replicated roll state before cancelling. A direct remote dodge follows
			-- Lycoris's fixed 0.15 second path and can be stopped immediately here.
			if not direct and not observed then
				local stateDeadline = os.clock() + 0.22
				while
					generation == self.DodgeCancelGeneration
					and os.clock() < stateDeadline
					and not self.Native:isDodging()
				do
					task.wait()
				end
				observed = self.Native:isDodging()
			end
			if generation ~= self.DodgeCancelGeneration then
				return
			end
			if not observed then
				self.Native.LastTransition = "dodge cancel skipped: roll not observed"
				return
			end

			local ok, detail = self.Native:stopDodge(direct == true)
			if ok then
				self.LastInput = {
					kind = "native",
					name = "StopDodge",
					backend = "LycorisNativeStopDodge",
					isDown = false,
					ok = true,
					detail = detail,
					at = os.clock(),
				}
				return
			end

			-- Executors that expose the hashed remotes but not InputClient's state
			-- table can still use the game's ordinary mouse-based roll cancel.
			local mouseOK, mouseDetail = self:tapMouse(1, 0.035)
			self.Native.LastTransition = mouseOK
				and "dodge cancel via mouse"
				or ("dodge cancel failed: " .. tostring(mouseDetail or detail))
		end)
		return true, "dodge cancel scheduled"
	end

	function InputAdapter:cancelDodgeCancel(reason)
		self.DodgeCancelGeneration = self.DodgeCancelGeneration + 1
		self.Native.LastTransition = "dodge cancel cleared: " .. tostring(reason or "cancelled")
	end

	function InputAdapter:releaseAll(reason)
		self:cancelDodgeCancel(reason or "release all")
		local nativeOK, nativeDetail = self.Native:releaseAll(reason)
		-- These are releases only: they cannot start a new action, but they recover
		-- executors that were interrupted between a press and its delayed release.
		pcall(self.mouse, self, 0, false)
		pcall(self.mouse, self, 1, false)
		pcall(self.key, self, Enum.KeyCode.F, false)
		pcall(self.key, self, Enum.KeyCode.Q, false)
		self.LastInput = {
			kind = "release",
			name = "All",
			backend = nativeOK and "safe-reset" or "release-fallback",
			isDown = false,
			ok = nativeOK,
			detail = nativeDetail,
			at = os.clock(),
		}
		return nativeOK, nativeDetail
	end

	local function keyCodeFromName(name)
		return KEY_CODES[string.lower(name)]
	end

	function InputAdapter:_binding(name)
		if not self.Settings then
			return nil
		end
		local value = self.Settings:get("Bindings." .. tostring(name))
		if type(value) ~= "string" or value == "" then
			return nil
		end
		return value
	end

	function InputAdapter:key(keyCode, isDown)
		local callback, backend = firstFunction(isDown and { "keypress", "key_press" } or { "keyrelease", "key_release" })
		if callback then
			local ok, inputError = pcall(callback, virtualKeyCode(keyCode))
			self.LastInput = {
				kind = "key",
				name = keyCode.Name,
				backend = backend,
				isDown = isDown,
				ok = ok,
				detail = ok and nil or tostring(inputError),
				at = os.clock(),
			}
			if ok then
				return true, backend
			end
		end

		if self.VirtualInput then
			local ok = pcall(self.VirtualInput.SendKeyEvent, self.VirtualInput, isDown, keyCode, false, game)
			if ok then
				self.LastInput = {
					kind = "key",
					name = keyCode.Name,
					backend = "VirtualInputManager",
					isDown = isDown,
					ok = true,
					at = os.clock(),
				}
				return true, "VirtualInputManager"
			end
		end

		self.LastInput = {
			kind = "key",
			name = keyCode.Name,
			backend = "none",
			isDown = isDown,
			ok = false,
			detail = "no keyboard input implementation",
			at = os.clock(),
		}
		return false, "no keyboard input implementation"
	end

	function InputAdapter:mouse(button, isDown)
		local fallbackName = button == 0
			and (isDown and "mouse1press" or "mouse1release")
			or (isDown and "mouse2press" or "mouse2release")
		local fallback = rawget(environment, fallbackName)
		if type(fallback) == "function" then
			local ok, inputError = pcall(fallback)
			self.LastInput = {
				kind = "mouse",
				name = button == 0 and "Mouse1" or "Mouse2",
				backend = fallbackName,
				isDown = isDown,
				ok = ok,
				detail = ok and nil or tostring(inputError),
				at = os.clock(),
			}
			if ok then
				return true, fallbackName
			end
		end

		if self.VirtualInput then
			local position = UserInputService:GetMouseLocation()
			local ok = pcall(
				self.VirtualInput.SendMouseButtonEvent,
				self.VirtualInput,
				position.X,
				position.Y,
				button,
				isDown,
				game,
				0
			)
			if ok then
				self.LastInput = {
					kind = "mouse",
					name = button == 0 and "Mouse1" or "Mouse2",
					backend = "VirtualInputManager",
					isDown = isDown,
					ok = true,
					at = os.clock(),
				}
				return true, "VirtualInputManager"
			end
		end

		self.LastInput = {
			kind = "mouse",
			name = button == 0 and "Mouse1" or "Mouse2",
			backend = "none",
			isDown = isDown,
			ok = false,
			detail = "no mouse input implementation",
			at = os.clock(),
		}
		return false, "no mouse input implementation"
	end

	function InputAdapter:tapKey(keyCode, duration)
		local pressed, pressDetail = self:key(keyCode, true)
		if not pressed then
			return false, pressDetail
		end

		task.delay(duration or 0.035, function()
			self:key(keyCode, false)
		end)
		return true, pressDetail
	end

	function InputAdapter:tapMouse(button, duration)
		local pressed, pressDetail = self:mouse(button, true)
		if not pressed then
			return false, pressDetail
		end

		task.delay(duration or 0.035, function()
			self:mouse(button, false)
		end)
		return true, pressDetail
	end

	function InputAdapter:custom(name, ...)
		local callback = self.Custom[name]
		if type(callback) == "function" then
			local ok, success, result = pcall(callback, ...)
			if not ok then
				return false, success
			end
			if success == false then
				return false, result
			end
			return true, success
		end

		local binding = self:_binding(name)
		if not binding then
			return false, "no callback or key binding for " .. tostring(name)
		end
		local normalized = string.lower(binding)
		if normalized == "mouse1" or normalized == "mousebutton1" then
			return self:tapMouse(0)
		elseif normalized == "mouse2" or normalized == "mousebutton2" then
			return self:tapMouse(1)
		end

		local keyCode = keyCodeFromName(binding)
		if not keyCode or keyCode == Enum.KeyCode.Unknown then
			return false, "invalid key binding for " .. tostring(name)
		end
		return self:tapKey(keyCode)
	end

	function InputAdapter:Destroy()
		self:cancelDodgeCancel("destroyed")
		self.Native:Destroy()
	end

	return InputAdapter
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/InputAdapter.lua

-- BEGIN MODULE: src/Combat/ActionExecutor.lua
do
  local moduleName = "src/Combat/ActionExecutor.lua"
  local moduleFactory = function()
	local ActionExecutor = {}
	ActionExecutor.__index = ActionExecutor

	local KEY_BINDINGS = {
		Parry = Enum.KeyCode.F,
		Block = Enum.KeyCode.F,
		Dodge = Enum.KeyCode.Q,
		FullDodge = Enum.KeyCode.Q,
		Jump = Enum.KeyCode.Space,
		Slide = Enum.KeyCode.LeftControl,
		Crouch = Enum.KeyCode.LeftControl,
	}

	local DEFAULT_COOLDOWNS = {
		Parry = 0.075,
		Block = 0.075,
		Dodge = 0.20,
		FullDodge = 0.25,
		Jump = 0.10,
		Slide = 0.10,
		Crouch = 0.10,
		Feint = 0.075,
		M1 = 0.075,
	}

	function ActionExecutor.new(settings, state, input)
		return setmetatable({
			Settings = settings,
			State = state,
			Input = input,
			Cooldowns = DEFAULT_COOLDOWNS,
		}, ActionExecutor)
	end

	function ActionExecutor:canExecute(action)
		local readyAt = self.State.Cooldowns[action.kind] or 0
		return os.clock() >= readyAt
	end

	function ActionExecutor:_markCooldown(action)
		local duration = tonumber(action.metadata.cooldown) or self.Cooldowns[action.kind] or 0
		self.State.Cooldowns[action.kind] = os.clock() + math.max(0, duration)
	end

	function ActionExecutor:execute(action, context)
		if not self:canExecute(action) then
			return false, "action is on cooldown"
		end
		if not action:shouldRun() then
			return false, "probability rejected action"
		end

		local kind = action.kind
		local duration = action.duration
		if duration <= 0 then
			duration = kind == "Block" and self.Settings:get("Defense.BlockFallbackHold")
				or kind == "FullDodge" and 0.18
				or 0.035
		end
		local success, result
		local nativeDirectDodge = false

		if (kind == "Dodge" or kind == "FullDodge") and self.Settings:get("Defense.DirectRoll") then
			success, result = self.Input:directDodge()
			nativeDirectDodge = success
			if not success then
				success, result = self.Input:custom("DirectDodge", action, context)
			end
			if not success then
				success, result = self.Input:tapKey(KEY_BINDINGS[kind], duration)
			end
		elseif kind == "Parry" or kind == "Block" then
			success, result = self.Input:nativeBlock(duration, kind == "Parry")
			if not success then
				success, result = self.Input:tapKey(KEY_BINDINGS[kind], duration)
			end
		elseif KEY_BINDINGS[kind] then
			success, result = self.Input:tapKey(KEY_BINDINGS[kind], duration)
		elseif kind == "Feint" then
			success, result = self.Input:tapMouse(1, duration)
		elseif kind == "M1" then
			success, result = self.Input:tapMouse(0, duration)
		else
			local customName = action.metadata.customName or kind
			success, result = self.Input:custom(customName, action, context)
		end

		if not success then
			self.State.LastActionResult = {
				ok = false,
				kind = action.kind,
				reason = tostring(result),
				at = os.clock(),
			}
			return false, result
		end

		self:_markCooldown(action)
		self.State.LastActionResult = {
			ok = true,
			kind = action.kind,
			backend = tostring(result or "unknown"),
			at = os.clock(),
		}
		self.State:emit("action", {
			action = action,
			context = context,
		})

		if nativeDirectDodge then
			-- Lycoris's direct path always stops the server-side dodge after 0.15s.
			-- An enabled Roll Cancel may deliberately shorten that window.
			local cancelDelay = self.Settings:get("Defense.RollCancel")
				and self.Settings:get("Defense.RollCancelDelay")
				or 0.15
			self.Input:scheduleDodgeCancel(cancelDelay, true)
		elseif kind == "Dodge" and self.Settings:get("Defense.RollCancel") then
			self.Input:scheduleDodgeCancel(self.Settings:get("Defense.RollCancelDelay"), false)
		end

		return true, result
	end

	return ActionExecutor
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/ActionExecutor.lua

-- BEGIN MODULE: src/Combat/TimingResolver.lua
do
  local moduleName = "src/Combat/TimingResolver.lua"
  local moduleFactory = function()
	local Stats = game:GetService("Stats")

	local TimingResolver = {}
	TimingResolver.__index = TimingResolver

	function TimingResolver.new(settings)
		return setmetatable({ Settings = settings }, TimingResolver)
	end

	function TimingResolver:pingSeconds()
		local ok, value = pcall(function()
			return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() / 1000
		end)
		return ok and math.max(0, value) or 0
	end

	function TimingResolver:delay(action, event, target)
		local timing = self.Settings:get("Timing")
		local metadata = action.metadata or {}
		local baseDelay = action.delay
		local attributes = event and event.metadata and event.metadata.attributes
		if type(metadata.attributeDifference) == "table" and type(attributes) == "table" then
			local first = tonumber(attributes[metadata.attributeDifference[1]])
			local second = tonumber(attributes[metadata.attributeDifference[2]])
			if first and second then
				baseDelay = math.max(0, (first - second) * (tonumber(metadata.attributeScale) or 1))
			end
		end
		local distanceScale = tonumber(metadata.distanceScale) or 0
		local maximumDelay = tonumber(metadata.maxDelay)
		local minimumDelay = tonumber(metadata.minDelay)
		local fastSpeedThreshold = tonumber(metadata.fastSpeedThreshold)
		if
			event
			and event.entity
			and type(metadata.entityNamePattern) == "string"
			and string.find(string.lower(event.entity.Name), string.lower(metadata.entityNamePattern), 1, true)
		then
			baseDelay = tonumber(metadata.matchingDelay) or baseDelay
		end
		if event and event.track and fastSpeedThreshold then
			local speed = math.abs(event.track.Speed)
			if speed >= fastSpeedThreshold then
				baseDelay = tonumber(metadata.fastBaseDelay) or baseDelay
				distanceScale = tonumber(metadata.fastDistanceScale) or distanceScale
				maximumDelay = tonumber(metadata.fastMaxDelay) or maximumDelay
			end
		end
		local delay = baseDelay + ((target and target.Distance or 0) * distanceScale)
		if maximumDelay then
			delay = math.min(delay, maximumDelay)
		end
		if minimumDelay then
			delay = math.max(delay, minimumDelay)
		end
		delay = delay + timing.GlobalOffset
		if timing.PingCompensation then
			delay = delay - (self:pingSeconds() * timing.PingScale)
		end

		return math.clamp(delay, timing.MinDelay, timing.MaxDelay)
	end

	return TimingResolver
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/TimingResolver.lua

-- BEGIN MODULE: src/Combat/DynamicWeaponResolver.lua
do
  local moduleName = "src/Combat/DynamicWeaponResolver.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local Action = assert(environment.__CLAW_MODULES["src/Combat/Action.lua"])

	local DynamicWeaponResolver = {}

	local SUPPORTED_MODULES = {
		WeaponTest = "M1",
		WeaponFlourishTest = "Flourish",
		WeaponRunningAttackTest = "Running",
		WeaponAerialAttackTest = "Aerial",
		WeaponUppercutTest = "Uppercut",
	}

	local function valueOf(instance)
		if not instance then
			return nil
		end
		local ok, value = pcall(function()
			return instance.Value
		end)
		return ok and value or nil
	end

	local function weaponData(entity)
		if not entity then
			return nil
		end

		local handWeapon
		if entity:GetAttribute("MOB_rich_name") then
			local left = entity:FindFirstChild("LeftHand")
			local right = entity:FindFirstChild("RightHand")
			handWeapon = (left and left:FindFirstChild("HandWeapon"))
				or (right and right:FindFirstChild("HandWeapon"))
		else
			local thrown = workspace:FindFirstChild("Thrown")
			local attachment = thrown and thrown:FindFirstChild("Attach_" .. entity.Name)
			handWeapon = attachment and attachment:FindFirstChild("HandWeapon")
		end
		if not handWeapon then
			return nil
		end

		local stats = handWeapon:FindFirstChild("Stats")
		local swingValue = stats and stats:FindFirstChild("SwingSpeed")
		local lengthValue = stats and stats:FindFirstChild("Length")
		local typeValue = handWeapon:FindFirstChild("Type")
		local swingSpeed = tonumber(valueOf(swingValue))
		local length = tonumber(valueOf(lengthValue))
		local weaponType = tostring(valueOf(typeValue) or "")
		if not swingSpeed or swingSpeed <= 0 or not length or length <= 0 or weaponType == "" then
			return nil
		end

		return {
			swingSpeed = swingSpeed,
			length = length,
			weaponType = weaponType,
		}
	end

	function DynamicWeaponResolver.weaponInfo(event)
		return weaponData(event and event.entity)
	end

	local function inferredWeaponType(profile)
		local name = string.lower(tostring(profile and profile.name or ""))
		for _, candidate in ipairs({
			"Greatcannon",
			"Greathammer",
			"Greatsword",
			"Greataxe",
			"Twinblade",
			"Dagger",
			"Rapier",
			"Pistol",
			"Rifle",
			"Spear",
			"Staff",
			"Sword",
			"Club",
			"Fist",
			"Bow",
		}) do
			if string.find(name, string.lower(candidate), 1, true) then
				return candidate
			end
		end
		return "Sword"
	end

	local function trackSpeed(event)
		local speed = 1
		if event and event.track then
			pcall(function()
				speed = math.abs(event.track.Speed)
			end)
		end
		return math.max(0.01, tonumber(speed) or 1)
	end

	local function m1Windup(weaponType, speed, swingSpeed, profileName)
		local atDefaultSpeed = math.abs(speed - 1) <= 0.001
		if weaponType == "Greataxe" then
			return atDefaultSpeed and (0.171 + (0.250 / swingSpeed)) or ((0.171 / speed) + 0.120)
		elseif weaponType == "Greathammer" then
			return atDefaultSpeed and (0.150 + (0.250 / swingSpeed)) or ((0.150 / speed) + 0.200)
		elseif weaponType == "Greatcannon" then
			return atDefaultSpeed and (0.155 + 0.300) or ((0.155 / speed) + 0.160)
		elseif weaponType == "Rapier" then
			return (0.155 / speed) + 0.120
		elseif weaponType == "Bow" then
			return (0.147 / speed) + 0.160
		elseif weaponType == "Pistol" and not string.find(profileName, "Shot", 1, true) then
			return 0.350 / swingSpeed
		elseif weaponType == "Pistol" then
			return speed <= 0.01 and 0.100 or 0.075 / speed
		elseif weaponType == "Rifle" and string.find(profileName, "2", 1, true) then
			return speed <= 0.01 and 0.100 or 0.200 / speed
		elseif weaponType == "Rifle" then
			return (0.174 / speed) + 0.125
		elseif weaponType == "Club" then
			return (0.180 / speed) + 0.100
		elseif weaponType == "Twinblade" then
			return (0.150 / speed) + 0.050
		elseif weaponType == "Spear" then
			return (0.150 / speed) + 0.100
		elseif weaponType == "Greatsword" then
			return (0.158 / speed) + 0.150
		elseif weaponType == "Fist" then
			return (0.140 / speed) + 0.130
		elseif weaponType == "Dagger" then
			return (0.150 / speed) + 0.075
		elseif weaponType == "Staff" then
			return 0.350
		elseif weaponType == "Sword" then
			return (0.150 / speed) + 0.100
		end
		return nil
	end

	local function flourishWindup(weaponType, speed, swingSpeed)
		if weaponType == "Greataxe" then
			return (0.180 / speed) + 0.100
		elseif weaponType == "Greathammer" then
			return (0.140 / speed) + 0.140
		elseif weaponType == "Greatsword" then
			return (0.170 / speed) + 0.050
		elseif weaponType == "Twinblade" then
			return (0.166 / speed) + 0.140
		elseif weaponType == "Bow" then
			return (0.172 / speed) + 0.140
		elseif weaponType == "Pistol" then
			return 0.500 / swingSpeed
		elseif weaponType == "Greatcannon" then
			return (0.173 / speed) + 0.160
		elseif weaponType == "Dagger" then
			return (0.165 / speed) + 0.100
		elseif weaponType == "Rapier" then
			return (0.163 / speed) + 0.120
		elseif weaponType == "Spear" then
			return (0.135 / speed) + 0.180
		elseif weaponType == "Fist" then
			return (0.160 / speed) + 0.140
		elseif weaponType == "Sword" or weaponType == "Staff" then
			return (0.160 / speed) + 0.120
		elseif weaponType == "Club" or weaponType == "Rifle" then
			return (0.160 / speed) + 0.150
		end
		return nil
	end

	local function runningWindup(weaponType, speed, swingSpeed)
		if weaponType == "Dagger" then
			return (0.147 / speed) + 0.140
		elseif weaponType == "Greatsword" or weaponType == "Greatcannon" then
			return (0.160 / speed) + 0.180 + (0.100 / swingSpeed)
		elseif weaponType == "Spear" then
			return (0.150 / speed) + 0.170 + (0.100 / swingSpeed)
		elseif weaponType == "Pistol" then
			return 0.300 / speed
		elseif weaponType == "Rifle" then
			return (0.169 / speed) + 0.180 + (0.100 / swingSpeed)
		elseif weaponType == "Sword" then
			return (0.135 / speed) + 0.150 + (0.150 / swingSpeed)
		elseif weaponType == "Rapier" then
			return (0.238 / speed) + 0.060
		elseif weaponType == "Club" then
			return (0.173 / speed) + 0.140 + (0.150 / swingSpeed)
		elseif weaponType == "Bow" then
			return (0.160 / speed) + 0.130
		elseif weaponType == "Twinblade" then
			return (0.164 / speed) + 0.140 + (0.150 / swingSpeed)
		elseif weaponType == "Fist" then
			return (0.153 / speed) + 0.150
		end
		return nil
	end

	local function aerialWindup(weaponType, speed, swingSpeed, profileName)
		if weaponType == "Dagger" then
			return (0.165 / speed) + 0.100
		elseif weaponType == "Greataxe" then
			return (0.168 / speed) + 0.125
		elseif weaponType == "Twinblade" then
			return (0.160 / speed) + 0.100
		elseif weaponType == "Bow" then
			return (0.145 / speed) + 0.170
		elseif weaponType == "Club" then
			return (0.163 / speed) + 0.140
		elseif weaponType == "Pistol" then
			return 0.500 / swingSpeed
		elseif weaponType == "Rifle" and not string.find(profileName, "Fist", 1, true) then
			return speed <= 0.01 and 0.100 or 0.300 / speed
		elseif weaponType == "Rifle" then
			return (0.199 / speed) + 0.100
		elseif weaponType == "Greatsword" then
			return (0.166 / speed) + 0.160
		elseif weaponType == "Rapier" then
			return (0.225 / speed) + 0.080
		elseif weaponType == "Greatcannon" then
			return (0.163 / speed) + 0.183
		elseif weaponType == "Greathammer" then
			return (0.150 / speed) + 0.170
		elseif weaponType == "Fist" then
			return (0.160 / speed) + 0.130
		elseif weaponType == "Sword" or weaponType == "Staff" then
			return (0.160 / speed) + 0.100
		elseif weaponType == "Spear" then
			return (0.150 / speed) + 0.170
		end
		return nil
	end

	local function uppercutWindup(weaponType, speed, swingSpeed)
		if weaponType == "Dagger" then
			return (0.166 / speed) + 0.120
		elseif weaponType == "Greataxe" then
			return (0.141 / speed) + 0.100
		elseif weaponType == "Greathammer" then
			return (0.150 / speed) + 0.100
		elseif weaponType == "Greatsword" then
			return (0.157 / speed) + 0.100
		elseif weaponType == "Greatcannon" then
			return (0.166 / speed) + 0.100
		elseif weaponType == "Twinblade" then
			return (0.163 / speed) + 0.130
		elseif weaponType == "Bow" then
			return (0.150 / speed) + 0.140
		elseif weaponType == "Club" then
			return (0.166 / speed) + 0.140
		elseif weaponType == "Pistol" then
			return 0.166 / speed + 0.150
		elseif weaponType == "Rifle" then
			return (0.159 / speed) + 0.140
		elseif weaponType == "Rapier" then
			return (0.181 / speed) + 0.130
		elseif weaponType == "Fist" then
			return (0.150 / speed) + 0.120
		elseif weaponType == "Sword" or weaponType == "Staff" then
			return (0.150 / speed) + 0.100
		elseif weaponType == "Spear" then
			return (0.163 / speed) + 0.100 + (0.050 / swingSpeed)
		end
		return nil
	end

	local function resolvedAction(template, label, delay, hitbox, weaponType)
		local action = template and template:clone() or Action.new({ kind = "Parry" })
		action.kind = "Parry"
		action.name = string.format("Dynamic %s (%s)", label, weaponType)
		action.delay = action.metadata.preserveDelay == true and action.delay or math.max(0, delay)
		action.hitbox = hitbox
		action.metadata.dynamicWeapon = label
		action.metadata.weaponType = weaponType
		return action
	end

	function DynamicWeaponResolver.resolve(profile, event, sourceActions)
		local label = profile and SUPPORTED_MODULES[profile.sourceModule]
		if not label then
			return sourceActions
		end

		local data = weaponData(event and event.entity)
		local weaponType = data and data.weaponType or inferredWeaponType(profile)
		local speed = trackSpeed(event)
		local swingSpeed = data and data.swingSpeed or 1
		local length = data and data.length or 8
		local profileName = tostring(profile.name or "")
		local windup
		local hitbox

		if label == "M1" then
			windup = m1Windup(weaponType, speed, swingSpeed, profileName)
			hitbox = Vector3.new(length * 2.3, length * 2.3, length * 2.3)
		elseif label == "Flourish" then
			windup = flourishWindup(weaponType, speed, swingSpeed)
			hitbox = Vector3.new(length * 2.1, length * 2.1, length * 2.1)
		elseif label == "Running" then
			windup = runningWindup(weaponType, speed, swingSpeed)
			hitbox = weaponType == "Twinblade"
				and Vector3.new(length * 2.5, length * 2, length * 3.5)
				or Vector3.new(length * 2.5, length * 2, length * 2.5)
		elseif label == "Aerial" then
			windup = aerialWindup(weaponType, speed, swingSpeed, profileName)
			hitbox = Vector3.new(length * 2, length * 3.5, length * 3)
		elseif label == "Uppercut" then
			windup = uppercutWindup(weaponType, speed, swingSpeed)
			hitbox = Vector3.new(length * 2, length * 2, length * 2.2)
		end

		if not windup then
			windup = sourceActions[1] and sourceActions[1].delay or 0.25
		end
		local first = resolvedAction(sourceActions[1], label, windup, hitbox, weaponType)
		if label ~= "Running" or weaponType ~= "Twinblade" then
			return { first }
		end

		local second = first:clone()
		second.name = first.name .. " (follow-up)"
		second.delay = first.delay + (0.300 / swingSpeed)
		return { first, second }
	end

	return DynamicWeaponResolver
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/DynamicWeaponResolver.lua

-- BEGIN MODULE: src/Combat/ValidationEngine.lua
do
  local moduleName = "src/Combat/ValidationEngine.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local UserInputService = game:GetService("UserInputService")
	local Players = game:GetService("Players")

	local ValidationEngine = {}
	ValidationEngine.__index = ValidationEngine

	local ACTION_SETTING = {
		Parry = "Defense.AllowParry",
		Block = "Defense.AllowBlock",
		Dodge = "Defense.AllowDodge",
		FullDodge = "Defense.AllowFullDodge",
		Jump = "Defense.AllowJump",
		Slide = "Defense.AllowSlide",
		Crouch = "Defense.AllowCrouch",
		Teleport = "Defense.AllowTeleport",
	}

	local function hasState(character, names)
		if not character then
			return false
		end
		for _, name in ipairs(names) do
			if character:GetAttribute(name) == true or character:FindFirstChild(name) then
				return true
			end
		end
		return false
	end

	function ValidationEngine.new(settings, state, history, executor)
		return setmetatable({
			Settings = settings,
			State = state,
			History = history,
			Executor = executor,
		}, ValidationEngine)
	end

	function ValidationEngine:_sourceCFrame(event, profile)
		local source
		if profile and profile.useHitboxCFrame and event.instance and event.instance:IsA("BasePart") then
			source = event.instance.CFrame
		elseif event.root and event.root.Parent then
			source = event.root.CFrame
		elseif event.instance and event.instance:IsA("BasePart") then
			source = profile and profile.useHitboxCFrame and event.instance.CFrame or CFrame.new(event.instance.Position)
		end
		if not source or not profile or profile.disablePrediction or not self.Settings:get("Validation.Prediction") then
			return source
		end

		local seconds = profile.predictionSeconds > 0 and profile.predictionSeconds
			or self.Settings:get("Validation.PredictionSeconds")
		local movingPart = profile.useHitboxCFrame
			and event.instance
			and event.instance:IsA("BasePart")
			and event.instance
			or event.root
			or (event.instance and event.instance:IsA("BasePart") and event.instance)
		if movingPart then
			source = source + (movingPart.AssemblyLinearVelocity * seconds)
		end
		if profile.predictFacing and event.entity then
			source = source * CFrame.Angles(0, self.History:yawRate(event.entity) * seconds, 0)
		end
		return source
	end

	function ValidationEngine:_filtered(profile)
		local filters = self.Settings:get("Filters")
		local tag = string.lower(profile.tag or "")
		if filters.M1 and tag == "m1" then
			return true, "filtered-m1"
		end
		if filters.Mantra and tag == "mantra" then
			return true, "filtered-mantra"
		end
		if filters.Critical and tag == "critical" then
			return true, "filtered-critical"
		end
		if filters.Undefined and (tag == "" or tag == "undefined") then
			return true, "filtered-undefined"
		end
		if filters.TextboxFocused and UserInputService:GetFocusedTextBox() then
			return true, "textbox-focused"
		end
		if filters.HoldingBlock and UserInputService:IsKeyDown(Enum.KeyCode.F) then
			return true, "holding-block"
		end
		if filters.WindowInactive then
			local isActive = rawget(environment, "isrbxactive")
			if type(isActive) == "function" then
				local ok, active = pcall(isActive)
				if ok and not active then
					return true, "window-inactive"
				end
			end
		end
		if filters.ChimeCountdown and self.State.Flags.ChimeCountdown then
			return true, "chime-countdown"
		end
		if filters.SightlessBeam and self.State.Flags.SightlessBeam then
			return true, "sightless-beam"
		end
		return false
	end

	function ValidationEngine:_trackValid(event)
		if not self.Settings:get("Validation.AnimationSanity") or event.detector ~= "animation" or not event.track then
			return true
		end

		local ok, speed, length = pcall(function()
			return math.abs(event.track.Speed), event.track.Length
		end)
		if not ok then
			return false, "animation-unavailable"
		end

		local validation = self.Settings:get("Validation")
		local okProperties, priority, weightTarget = pcall(function()
			return event.track.Priority, event.track.WeightTarget
		end)
		if not okProperties then
			return false, "animation-properties"
		end
		if priority == Enum.AnimationPriority.Core then
			return false, "core-priority-animation"
		end
		-- AnimationPlayed can fire at weight zero during the first blend frame. Let
		-- the scheduler accept that fresh event; execution revalidates after the
		-- configured delay and rejects tracks that never actually blended in.
		local eventAge = os.clock() - (event.startedAt or os.clock())
		if
			event.entity
			and Players:GetPlayerFromCharacter(event.entity)
			and (tonumber(weightTarget) or 0) <= 0.05
			and eventAge > 0.10
		then
			return false, "low-weight-animation"
		end
		if
			speed < validation.MinAnimationSpeed
			or (validation.MaxAnimationSpeed > 0 and speed >= validation.MaxAnimationSpeed)
		then
			return false, "animation-speed"
		end
		if
			length > 0
			and (
				length < validation.MinAnimationLength
				or (validation.MaxAnimationLength > 0 and length > validation.MaxAnimationLength)
			)
		then
			return false, "animation-length"
		end
		return true
	end

	function ValidationEngine:_insideHitbox(event, profile, action)
		local hitbox = action.hitbox.Magnitude > 0 and action.hitbox or profile.hitbox
		if action.ignoreHitbox or not self.Settings:get("Validation.Hitbox") or hitbox.Magnitude <= 0 then
			return true
		end

		local source = self:_sourceCFrame(event, profile)
		local localRoot = self.State.Root
		if not source or not localRoot then
			return false, "missing-hitbox-origin"
		end

		local localFrame = localRoot.CFrame
		if self.Settings:get("Validation.Prediction") and not profile.disablePrediction then
			local seconds = profile.predictionSeconds > 0 and profile.predictionSeconds
				or self.Settings:get("Validation.PredictionSeconds")
			localFrame = self.History:predict(self.State.Character, seconds) or localFrame
		end

		local half = hitbox * 0.5
		local function contains(sourceFrame, targetFrame)
			local relative = sourceFrame:PointToObjectSpace(targetFrame.Position)
			-- Lycoris's fhb is a hitbox-center offset, not a directional
			-- validation switch. hso is positive backwards and negative forwards.
			local shiftedZ = relative.Z + (profile.facingHitbox and half.Z or 0) - profile.hitboxOffset
			return math.abs(relative.X) <= half.X and math.abs(relative.Y) <= half.Y and math.abs(shiftedZ) <= half.Z
		end

		local inside = contains(source, localFrame)
		if not inside and profile.pastHitbox then
			local seconds = profile.historySeconds > 0 and profile.historySeconds
				or self.Settings:get("Validation.PastHitboxSeconds")
			-- Past-hitbox detection replays the attacker's recent hitboxes against
			-- our current position. Replaying our own history against the current
			-- attacker position reverses the intended test.
			inside = self.History:anyRecent(event.entity, seconds, function(record)
				return contains(record.cframe, localFrame)
			end)
		end
		return inside, inside and nil or "outside-hitbox"
	end

	function ValidationEngine:insideHitbox(event, profile, action)
		return self:_insideHitbox(event, profile, action)
	end

	function ValidationEngine:_facing(event, profile)
		if not self.Settings:get("Validation.Facing") then
			return true
		end
		local source = self:_sourceCFrame(event, profile)
		if not source or not self.State.Root then
			return false, "missing-facing-origin"
		end
		local direction = self.State.Root.Position - source.Position
		if direction.Magnitude <= 0.001 then
			return true
		end
		local facing = source.LookVector:Dot(direction.Unit) > -0.15
		return facing, facing and nil or "not-facing"
	end

	function ValidationEngine:_visible(event, profile)
		if not self.Settings:get("Validation.Visibility") then
			return true
		end
		local source = self:_sourceCFrame(event, profile)
		if not source or not self.State.Root then
			return false, "missing-visibility-origin"
		end

		local parameters = RaycastParams.new()
		parameters.FilterType = Enum.RaycastFilterType.Exclude
		parameters.FilterDescendantsInstances = { self.State.Character, event.entity }
		local direction = self.State.Root.Position - source.Position
		local visible = workspace:Raycast(source.Position, direction, parameters) == nil
		return visible, visible and nil or "occluded"
	end

	function ValidationEngine:validate(event, profile, target, action, options)
		options = options or {}
		local debugState = self.Settings:get("DebugState")
		if
			(action.kind == "Parry" and debugState.BlockParry)
			or ((action.kind == "Dodge" or action.kind == "FullDodge") and debugState.BlockDodge)
			or (action.name == "Vent" and debugState.BlockVent)
			or (action.kind == "Block" and debugState.NoBlocking)
		then
			return false, "debug-state-block"
		end

		local filtered, filterReason = self:_filtered(profile)
		if filtered then
			return false, filterReason
		end

		local settingPath = ACTION_SETTING[action.kind]
		if settingPath and not self.Settings:get(settingPath) then
			return false, "action-disabled"
		end
		if not options.skipTransient then
			if self.Settings:get("Validation.Cooldown") and not self.Executor:canExecute(action) then
				return false, "cooldown"
			end

			-- The local executor cooldown only tells us when CLAW last sent an input.
			-- Deepwoken's replicated effects are the authoritative answer at the
			-- scheduled execution moment. Planning deliberately skips this block so
			-- a future parry does not become an immediate dodge while ParryCool is
			-- still active at detection time.
			local native = self.Executor.Input and self.Executor.Input.Native
			if action.kind == "Parry" and native then
				local canParry, parryReason = native:canParry()
				if not canParry then
					return false, parryReason
				end
			elseif (action.kind == "Dodge" or action.kind == "FullDodge") and native then
				local canDodge, dodgeReason = native:canDodge()
				if not canDodge then
					return false, dodgeReason
				end
			end
		end

		local character = self.State.Character
		if
			not options.skipTransient
			and
			self.Settings:get("Validation.IFrames")
			and hasState(character, { "IFrame", "Invulnerable", "Dodging", "Immortal" })
		then
			return false, "iframes"
		end
		if
			not options.skipTransient
			and
			action.kind == "Parry"
			and self.Settings:get("Validation.AutoParryFrames")
			and self.State.Flags.AutoParryFrames
		then
			return false, "auto-parry-frames"
		end
		if
			not options.skipTransient
			and
			self.Settings:get("Validation.Stun")
			and hasState(character, { "Stun", "Stunned", "Knocked", "Unconscious", "Carried" })
		then
			return false, "stunned"
		end
		if not options.skipTransient and self.State.Flags.Attacking and not profile.allowAttacking then
			return false, "already-attacking"
		end

		local trackValid, trackReason = self:_trackValid(event)
		if not trackValid then
			return false, trackReason
		end

		local maximumDistance = profile.maxDistance > 0 and profile.maxDistance
			or self.Settings:get("Targeting.MaxDistance")
		if target.Distance < profile.minDistance or target.Distance > maximumDistance then
			return false, "distance"
		end

		if not options.skipHitbox then
			local inside, hitboxReason = self:_insideHitbox(event, profile, action)
			if not inside then
				return false, hitboxReason
			end
		end
		local facing, facingReason = self:_facing(event, profile)
		if not facing then
			return false, facingReason
		end
		local visible, visibleReason = self:_visible(event, profile)
		if not visible then
			return false, visibleReason
		end

		return true
	end

	return ValidationEngine
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/ValidationEngine.lua

-- BEGIN MODULE: src/Combat/ProbabilityResolver.lua
do
  local moduleName = "src/Combat/ProbabilityResolver.lua"
  local moduleFactory = function()
	local ProbabilityResolver = {}
	ProbabilityResolver.__index = ProbabilityResolver

	local function rate(profile, name, fallback)
		local value = profile.probability and profile.probability[name]
		return math.clamp(tonumber(value) or fallback, 0, 100)
	end

	function ProbabilityResolver.new(settings, seed)
		return setmetatable({
			Settings = settings,
			Random = Random.new(seed or math.floor(os.clock() * 100000)),
		}, ProbabilityResolver)
	end

	function ProbabilityResolver:_roll(chance)
		return self.Random:NextNumber(0, 100) <= chance
	end

	function ProbabilityResolver:resolve(action, profile)
		if not self.Settings:get("Probability.Enabled") then
			return action
		end

		local probability = self.Settings:get("Probability")
		local failureRate = rate(profile, "FailureRate", probability.FailureRate)
		if probability.AllowFailure and self:_roll(failureRate) then
			return nil, "intentional-failure"
		end

		local resolved = action:clone()
		local actionChance = probability[resolved.kind]
		if type(actionChance) == "number" and not self:_roll(actionChance) then
			return nil, "action-probability"
		end

		if resolved.kind == "Parry" then
			local dashRate = rate(profile, "DashInsteadOfParryRate", probability.DashInsteadOfParryRate)
			if self:_roll(dashRate) then
				resolved.kind = "Dodge"
				resolved.name = resolved.name .. " (dash variation)"
			end
		end

		resolved.metadata.ignoreAnimationEnd =
			self:_roll(rate(profile, "IgnoreAnimationEndRate", probability.IgnoreAnimationEndRate))
		return resolved
	end

	return ProbabilityResolver
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/ProbabilityResolver.lua

-- BEGIN MODULE: src/Combat/FallbackResolver.lua
do
  local moduleName = "src/Combat/FallbackResolver.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local Action = assert(environment.__CLAW_MODULES["src/Combat/Action.lua"])

	local FallbackResolver = {}
	FallbackResolver.__index = FallbackResolver

	function FallbackResolver.new(settings)
		return setmetatable({ Settings = settings }, FallbackResolver)
	end

	function FallbackResolver:resolve(action, reason, profile)
		if reason == "iframes" or reason == "distance" or reason == "occluded" then
			return nil
		end

		if action.kind == "Dodge" and self.Settings:get("Defense.ParryOnly") then
			return Action.new({ kind = "Parry", name = action.name .. " (parry-only)" })
		end

		local parryUnavailable = reason == "cooldown" or reason == "parry-cooldown"
		if
			action.kind == "Parry"
			and parryUnavailable
			and (
				self.Settings:get("Defense.RollOnParryCooldown")
				or self.Settings:get("Defense.DodgeFallback")
			)
			and not profile.noDodgeFallback
			and self.Settings:get("Defense.AllowDodge")
		then
			return Action.new({
				kind = "Dodge",
				name = action.name .. " (parry unavailable roll)",
				metadata = { fallbackReason = reason },
			})
		end
		if self.Settings:get("Defense.BlockFallback") and profile.preferBlockFallback and not profile.noBlockFallback then
			return Action.new({
				kind = "Block",
				name = action.name .. " (preferred block fallback)",
				duration = profile.blockFallbackHold,
			})
		end

		if self.Settings:get("Defense.UsePredictionMantra") then
			return Action.new({ kind = "Custom", name = "Prediction", metadata = { customName = "Prediction" } })
		end
		if self.Settings:get("Defense.UsePunishmentMantra") then
			return Action.new({ kind = "Custom", name = "Punishment", metadata = { customName = "Punishment" } })
		end
		if self.Settings:get("Defense.BlockFallback") and not profile.noBlockFallback then
			return Action.new({
				kind = "Block",
				name = action.name .. " (block fallback)",
				duration = profile.blockFallbackHold,
			})
		end
		if self.Settings:get("Defense.VentFallback") and not profile.noVentFallback then
			return Action.new({ kind = "Custom", name = "Vent", metadata = { customName = "Vent" } })
		end
		if
			self.Settings:get("Defense.DodgeFallback")
			and not profile.noDodgeFallback
			and self.Settings:get("Defense.AllowDodge")
		then
			return Action.new({ kind = "Dodge", name = action.name .. " (dodge fallback)" })
		end
		return nil
	end

	return FallbackResolver
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/FallbackResolver.lua

-- BEGIN MODULE: src/Combat/Diagnostics.lua
do
  local moduleName = "src/Combat/Diagnostics.lua"
  local moduleFactory = function()
	local Diagnostics = {}
	Diagnostics.__index = Diagnostics

	local StarterGui = game:GetService("StarterGui")

	local SCHEDULER_EVENTS = {
		scheduled = true,
		completed = true,
		failed = true,
		cancelled = true,
	}

	function Diagnostics.new(settings, state, performance)
		local self = setmetatable({
			Settings = settings,
			State = state,
			Performance = performance,
			Buffer = {},
			WriteIndex = 0,
			Count = 0,
			Reasons = {},
			NotificationCooldowns = {},
		}, Diagnostics)

		self.Connection = state.Event:Connect(function(event)
			self:record(event)
		end)
		return self
	end

	function Diagnostics:_notify(event)
		if not self.Settings:get("Diagnostics.Notifications") then
			return
		end
		local title, message, key
		if event.kind == "assistance-unavailable" then
			local payload = event.payload or {}
			title = "CLAW MARK: binding needed"
			message = string.format("%s: %s", tostring(payload.name), tostring(payload.reason))
			key = "assist:" .. tostring(payload.name)
		elseif event.kind == "module-fallback" then
			local payload = event.payload or {}
			title = "CLAW MARK: generic module fallback"
			message = string.format("%s (%s)", tostring(payload.module), tostring(payload.profile))
			key = "module:" .. tostring(payload.module)
		elseif event.kind == "failed" then
			title = "CLAW MARK: scheduled action failed"
			message = tostring(event.payload and event.payload.result or "unknown error")
			key = "scheduler-failed"
		else
			return
		end

		local now = os.clock()
		if now < (self.NotificationCooldowns[key] or 0) then
			return
		end
		self.NotificationCooldowns[key] = now + 3
		pcall(StarterGui.SetCore, StarterGui, "SendNotification", {
			Title = title,
			Text = message,
			Duration = 3,
		})
	end

	function Diagnostics:record(event)
		self:_notify(event)
		if not self.Settings:get("Diagnostics.Enabled") then
			return
		end
		if event.kind == "detected" and not self.Settings:get("Diagnostics.TraceDetectors") then
			return
		end
		if SCHEDULER_EVENTS[event.kind] and not self.Settings:get("Diagnostics.TraceScheduler") then
			return
		end
		local maximum = math.max(10, math.floor(self.Settings:get("Diagnostics.MaxEvents")))
		self.WriteIndex = (self.WriteIndex % maximum) + 1
		self.Buffer[self.WriteIndex] = event
		self.Count = math.min(maximum, self.Count + 1)

		if event.kind == "action-rejected" then
			local reason = tostring(event.payload)
			self.Reasons[reason] = (self.Reasons[reason] or 0) + 1
		end
	end

	function Diagnostics:events()
		local result = {}
		if self.Count == 0 then
			return result
		end
		local maximum = math.max(10, math.floor(self.Settings:get("Diagnostics.MaxEvents")))
		local first = ((self.WriteIndex - self.Count) % maximum) + 1
		for offset = 0, self.Count - 1 do
			local index = ((first + offset - 1) % maximum) + 1
			result[#result + 1] = self.Buffer[index]
		end
		return result
	end

	function Diagnostics:snapshot()
		return {
			metrics = self.State.Metrics,
			reasons = self.Reasons,
			performance = self.Performance:snapshot(),
			events = self:events(),
		}
	end

	local function formatLast(value, formatter)
		if not value then
			return "none"
		end
		local ok, result = pcall(formatter, value)
		return ok and tostring(result) or "unavailable"
	end

	function Diagnostics:report(context)
		context = context or {}
		local state = self.State
		local metrics = state.Metrics
		local native = context.native or {}
		local stats = native.stats or {}
		local clientEffects = context.clientEffects or {}
		local settings = self.Settings
		local threat = state.ThreatSummary or {}
		local lines = {
			"CLAW MARK DIAGNOSTIC REPORT",
			"version=" .. tostring(context.version or "unknown"),
			"distribution_ref=" .. tostring(context.distributionRef or "unknown"),
			"runtime=" .. (state.Running and "running" or "stopped"),
			"master=" .. (settings:get("Enabled") and "on" or "off"),
			"defense=" .. (settings:get("Defense.Enabled") and "on" or "off"),
			"targets=" .. tostring(#state.Targets),
			"timings=" .. tostring(context.timingCount or 0),
			"timing_source=" .. tostring(context.timingSource or "unknown"),
			"native=" .. tostring(native.status or "unknown"),
			"native_last=" .. tostring(native.last or "idle"),
			string.format(
				"threat_guard=%s mode:%s active:%d noisy:%d",
				settings:get("ThreatGuard.Enabled") and "on" or "off",
				tostring(threat.mode or "unknown"),
				tonumber(threat.activePlans) or 0,
				tonumber(threat.noisySources) or 0
			),
			string.format(
				"client_effects=normal:%d large:%d direct:%d deduplicated:%d",
				clientEffects.ClientEffect or 0,
				clientEffects.ClientEffectLarge or 0,
				clientEffects.ClientEffectDirect or 0,
				clientEffects.Deduplicated or 0
			),
			string.format(
				"native_io=blocks:%d unblocks:%d retries:%d coalesced:%d dodges:%d cancels:%d",
				stats.Blocks or 0,
				stats.Unblocks or 0,
				stats.Retries or 0,
				stats.Coalesced or 0,
				stats.Dodges or 0,
				stats.DodgeCancels or 0
			),
			string.format(
				"settings=primary:%s dodge_fallback:%s roll_on_cd:%s roll_cancel:%s direct_roll:%s indexed_only:%s unknown_anims:%s hitbox:%s facing:%s prediction:%s",
				tostring(settings:get("Defense.Preferred")),
				settings:get("Defense.DodgeFallback") and "on" or "off",
				settings:get("Defense.RollOnParryCooldown") and "on" or "off",
				settings:get("Defense.RollCancel") and "on" or "off",
				settings:get("Defense.DirectRoll") and "on" or "off",
				settings:get("Detection.OnlyConfigured") and "on" or "off",
				settings:get("Detection.UnknownAnimations") and "on" or "off",
				settings:get("Validation.Hitbox") and "on" or "off",
				settings:get("Validation.Facing") and "on" or "off",
				settings:get("Validation.Prediction") and "on" or "off"
			),
			string.format(
				"metrics=detected:%d scheduled:%d executed:%d failed:%d rejected:%d cancelled:%d",
				metrics.Detected or 0,
				metrics.Scheduled or 0,
				metrics.Executed or 0,
				metrics.Failed or 0,
				metrics.Rejected or 0,
				metrics.Cancelled or 0
			),
			string.format(
				"threat_metrics=admitted:%d coalesced:%d dropped:%d bursts:%d corroborated:%d promoted:%d",
				metrics.ThreatAdmitted or 0,
				metrics.ThreatCoalesced or 0,
				metrics.ThreatDropped or 0,
				metrics.ThreatSpamBursts or 0,
				metrics.ThreatCorroborated or 0,
				metrics.ThreatPromoted or 0
			),
			"last_detection=" .. formatLast(state.LastDetection, function(value)
				return tostring(value.detector) .. ":" .. tostring(value.id)
			end),
			"last_reject=" .. formatLast(state.LastReject, function(value)
				return value.reason
			end),
			"last_plan=" .. formatLast(state.LastPlan, function(value)
				return string.format(
					"%s @ %.3fs distance=%.1f name=%s",
					tostring(value.kind),
					tonumber(value.delay) or 0,
					tonumber(value.distance) or 0,
					tostring(value.name or value.profile or "unknown")
				)
			end),
			"last_action=" .. formatLast(state.LastActionResult, function(value)
				return tostring(value.kind)
					.. ":"
					.. (value.ok and tostring(value.backend or "sent") or tostring(value.reason))
			end),
			"last_failure=" .. formatLast(state.LastFailure, function(value)
				return value.reason
			end),
			"last_threat=" .. formatLast(state.LastThreat, function(value)
				return tostring(value.kind) .. ":" .. tostring(value.reason)
			end),
		}

		local reasons = {}
		for reason, count in pairs(self.Reasons) do
			reasons[#reasons + 1] = { reason = tostring(reason), count = count }
		end
		table.sort(reasons, function(left, right)
			if left.count == right.count then
				return left.reason < right.reason
			end
			return left.count > right.count
		end)
		lines[#lines + 1] = "rejection_reasons="
		if #reasons == 0 then
			lines[#lines + 1] = "  none"
		else
			for _, item in ipairs(reasons) do
				lines[#lines + 1] = string.format("  %s: %d", item.reason, item.count)
			end
		end

		local events = self:events()
		lines[#lines + 1] = "recent_events="
		if #events == 0 then
			lines[#lines + 1] = "  none (enable diagnostics to record the event trace)"
		else
			for index = math.max(1, #events - 11), #events do
				local event = events[index]
				lines[#lines + 1] = string.format("  %.3f %s", tonumber(event.at) or 0, tostring(event.kind))
			end
		end

		return table.concat(lines, "\n")
	end

	function Diagnostics:clear()
		table.clear(self.Buffer)
		table.clear(self.Reasons)
		table.clear(self.NotificationCooldowns)
		self.WriteIndex = 0
		self.Count = 0
	end

	function Diagnostics:Destroy()
		if self.Connection then
			self.Connection:Disconnect()
			self.Connection = nil
		end
		self:clear()
	end

	return Diagnostics
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/Diagnostics.lua

-- BEGIN MODULE: src/Combat/HitboxVisualizer.lua
do
  local moduleName = "src/Combat/HitboxVisualizer.lua"
  local moduleFactory = function()
	local HitboxVisualizer = {}
	HitboxVisualizer.__index = HitboxVisualizer

	local MAX_POOL = 16

	function HitboxVisualizer.new(settings, state)
		local self = setmetatable({
			Settings = settings,
			State = state,
			Folder = nil,
			Pool = {},
			Active = {},
			Serial = 0,
		}, HitboxVisualizer)
		self.Connection = state.Event:Connect(function(event)
			if event.kind == "defense-profile" then
				self:show(event.payload)
			end
		end)
		return self
	end

	function HitboxVisualizer:_folder()
		if self.Folder and self.Folder.Parent then
			return self.Folder
		end
		local folder = Instance.new("Folder")
		folder.Name = "_CLAW_MARK_Hitboxes"
		folder.Parent = workspace
		self.Folder = folder
		return folder
	end

	function HitboxVisualizer:_acquire()
		local part = table.remove(self.Pool)
		if part then
			return part
		end
		part = Instance.new("Part")
		part.Name = "CLAW_MARK_Hitbox"
		part.Anchored = true
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Material = Enum.Material.ForceField
		part.Color = Color3.fromRGB(235, 78, 119)
		part.Transparency = 0.72
		return part
	end

	function HitboxVisualizer:_release(part, serial)
		if self.Active[part] ~= serial then
			return
		end
		self.Active[part] = nil
		part.Parent = nil
		if #self.Pool < MAX_POOL then
			self.Pool[#self.Pool + 1] = part
		else
			part:Destroy()
		end
	end

	function HitboxVisualizer:show(payload)
		if not self.Settings:get("Diagnostics.VisualizeHitboxes") then
			return
		end
		local event = payload and payload.event
		local profile = payload and payload.profile
		if not event or not profile or profile.hitbox.Magnitude <= 0 then
			return
		end
		local source
		if event.root and event.root.Parent then
			source = event.root.CFrame
		elseif event.instance and event.instance:IsA("BasePart") then
			source = event.instance.CFrame
		end
		if not source then
			return
		end

		local part = self:_acquire()
		self.Serial = self.Serial + 1
		local serial = self.Serial
		self.Active[part] = serial
		part.Size = Vector3.new(
			math.max(0.05, profile.hitbox.X),
			math.max(0.05, profile.hitbox.Y),
			math.max(0.05, profile.hitbox.Z)
		)
		part.CFrame = source * CFrame.new(0, 0, -profile.hitboxOffset)
		part.Parent = self:_folder()
		task.delay(0.15, function()
			self:_release(part, serial)
		end)
	end

	function HitboxVisualizer:Destroy()
		if self.Connection then
			self.Connection:Disconnect()
			self.Connection = nil
		end
		for part in pairs(self.Active) do
			part:Destroy()
		end
		for _, part in ipairs(self.Pool) do
			part:Destroy()
		end
		table.clear(self.Active)
		table.clear(self.Pool)
		if self.Folder then
			self.Folder:Destroy()
			self.Folder = nil
		end
	end

	return HitboxVisualizer
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/HitboxVisualizer.lua

-- BEGIN MODULE: src/Combat/HitboxWaiter.lua
do
  local moduleName = "src/Combat/HitboxWaiter.lua"
  local moduleFactory = function()
	local RunService = game:GetService("RunService")

	local HitboxWaiter = {}
	HitboxWaiter.__index = HitboxWaiter

	function HitboxWaiter.new(settings)
		return setmetatable({
			Settings = settings,
			Entries = {},
			Connection = nil,
		}, HitboxWaiter)
	end

	function HitboxWaiter:_disconnectIfIdle()
		if next(self.Entries) == nil and self.Connection then
			self.Connection:Disconnect()
			self.Connection = nil
		end
	end

	function HitboxWaiter:_step()
		local now = os.clock()
		for key, entry in pairs(self.Entries) do
			if now >= entry.expiresAt then
				self.Entries[key] = nil
				entry.callback(false, "hitbox-wait-timeout")
			elseif now >= entry.nextCheck then
				entry.nextCheck = now + entry.interval
				local ok, ready, terminalReason = pcall(entry.predicate)
				if not ok or terminalReason then
					self.Entries[key] = nil
					entry.callback(false, terminalReason or tostring(ready))
				elseif ready then
					self.Entries[key] = nil
					entry.callback(true)
				end
			end
		end
		self:_disconnectIfIdle()
	end

	function HitboxWaiter:wait(key, predicate, callback)
		self:cancel(key)
		local now = os.clock()
		self.Entries[key] = {
			predicate = predicate,
			callback = callback,
			nextCheck = now,
			interval = math.max(0.01, self.Settings:get("Timing.HitboxPollInterval")),
			expiresAt = now + math.max(0.1, self.Settings:get("Timing.MaxHitboxWait")),
		}
		if not self.Connection then
			self.Connection = RunService.Heartbeat:Connect(function()
				self:_step()
			end)
		end
	end

	function HitboxWaiter:cancel(key, reason)
		local entry = self.Entries[key]
		if not entry then
			return false
		end
		self.Entries[key] = nil
		if reason then
			entry.callback(false, reason)
		end
		self:_disconnectIfIdle()
		return true
	end

	function HitboxWaiter:cancelAll(reason)
		local entries = self.Entries
		self.Entries = {}
		if reason then
			for _, entry in pairs(entries) do
				entry.callback(false, reason)
			end
		end
		self:_disconnectIfIdle()
	end

	function HitboxWaiter:Destroy()
		self:cancelAll()
	end

	return HitboxWaiter
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/HitboxWaiter.lua

-- BEGIN MODULE: src/Combat/StateMonitor.lua
do
  local moduleName = "src/Combat/StateMonitor.lua"
  local moduleFactory = function()
	local Players = game:GetService("Players")

	local StateMonitor = {}
	StateMonitor.__index = StateMonitor

	local FLAGS = {
		InCombat = { "InCombat", "CombatTag", "Danger" },
		IFrames = { "IFrame", "Invulnerable", "Dodging", "Immortal" },
		AutoParryFrames = { "AutoParry", "AutoParryFrame", "AutoParryFrames" },
		Ragdolled = { "Ragdoll", "Ragdolled", "Knocked" },
		Stunned = { "Stun", "Stunned", "ActionLocked" },
		DamagedAnother = { "DamagedAnother" },
		UsingMantra = { "UsingMantra", "CastingSpell", "Casting" },
		Attacking = { "Attacking", "Swinging", "LightAttack", "UsingMove" },
		WispActive = { "Wisp", "WispActive" },
		WispCooldown = { "WispCooldown" },
		GoldenTongueCooldown = { "GoldenTongueCooldown" },
		ArdourActive = { "Ardour", "ArdourActive" },
		FlowStateActive = { "FlowState", "FlowStateActive" },
		SightlessBeam = { "SightlessBeam", "UsingSightlessBeam" },
	}

	function StateMonitor.new(state)
		return setmetatable({
			State = state,
			Connections = {},
			CharacterConnections = {},
			Running = false,
			RefreshQueued = false,
		}, StateMonitor)
	end

	function StateMonitor:_bind(list, signal, callback)
		local connection = signal:Connect(callback)
		list[#list + 1] = connection
		return connection
	end

	function StateMonitor:_disconnect(list)
		for _, connection in ipairs(list) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(list)
	end

	function StateMonitor:_has(character, names)
		for _, name in ipairs(names) do
			if character:GetAttribute(name) == true then
				return true
			end
			local state = character:FindFirstChild(name, true)
			if state then
				if state:IsA("BoolValue") then
					if state.Value then
						return true
					end
				elseif state:IsA("NumberValue") or state:IsA("IntValue") then
					if state.Value ~= 0 then
						return true
					end
				elseif state:IsA("ObjectValue") then
					if state.Value ~= nil then
						return true
					end
				else
					return true
				end
			end
		end
		return false
	end

	function StateMonitor:_setFlag(name, value)
		if self.State.Flags[name] == value then
			return
		end
		self.State.Flags[name] = value
		self.State:emit("flag", { name = name, value = value })
	end

	function StateMonitor:refresh()
		local character = self.State.Character
		if not character then
			for name in pairs(FLAGS) do
				self:_setFlag(name, false)
			end
			self:_setFlag("WeaponEquipped", false)
			return
		end
		for name, aliases in pairs(FLAGS) do
			self:_setFlag(name, self:_has(character, aliases))
		end
		self:_setFlag("WeaponEquipped", character:FindFirstChildWhichIsA("Tool") ~= nil)
	end

	function StateMonitor:_watchValue(instance)
		if not instance:IsA("ValueBase") then
			return
		end
		self:_bind(self.CharacterConnections, instance.Changed, function()
			self:queueRefresh()
		end)
	end

	function StateMonitor:queueRefresh()
		if self.RefreshQueued then
			return
		end
		self.RefreshQueued = true
		task.defer(function()
			self.RefreshQueued = false
			if self.Running then
				self:refresh()
			end
		end)
	end

	function StateMonitor:attach(character)
		self:_disconnect(self.CharacterConnections)
		self.State:setCharacter(character)
		if not character then
			return
		end

		self:_bind(self.CharacterConnections, character.DescendantAdded, function(descendant)
			self:_watchValue(descendant)
			self:queueRefresh()
		end)
		self:_bind(self.CharacterConnections, character.DescendantRemoving, function()
			self:queueRefresh()
		end)

		for _, aliases in pairs(FLAGS) do
			for _, attribute in ipairs(aliases) do
				self:_bind(self.CharacterConnections, character:GetAttributeChangedSignal(attribute), function()
					self:queueRefresh()
				end)
			end
		end
		for _, descendant in ipairs(character:GetDescendants()) do
			self:_watchValue(descendant)
		end
		self:refresh()
	end

	function StateMonitor:start()
		if self.Running then
			return
		end
		self.Running = true
		self:_bind(self.Connections, Players.LocalPlayer.CharacterAdded, function(character)
			self:attach(character)
		end)
		self:_bind(self.Connections, Players.LocalPlayer.CharacterRemoving, function(character)
			if self.State.Character == character then
				self:attach(nil)
			end
		end)
		self:attach(Players.LocalPlayer.Character)
	end

	function StateMonitor:stop()
		self.Running = false
		self:_disconnect(self.CharacterConnections)
		self:_disconnect(self.Connections)
	end

	function StateMonitor:Destroy()
		self:stop()
	end

	return StateMonitor
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/StateMonitor.lua

-- BEGIN MODULE: src/Combat/PresetManager.lua
do
  local moduleName = "src/Combat/PresetManager.lua"
  local moduleFactory = function()
	local PresetManager = {}
	PresetManager.__index = PresetManager

	-- Every preset starts by clearing optional/risky switches. Numeric tuning,
	-- bindings, and target lists are preserved, but stale toggles from a previous
	-- experiment cannot silently leak into the next preset.
	local PRESET_BASE = {
		Enabled = true,
		Detection = {
			Animations = true,
			Sounds = true,
			Parts = true,
			Effects = true,
			Projectiles = true,
			OnlyConfigured = true,
			UnknownAnimations = false,
		},
		Defense = {
			Enabled = true,
			Preferred = "Parry",
			RollCancel = false,
			DirectRoll = false,
			RollOnParryCooldown = false,
			DodgeFallback = false,
			VentFallback = false,
			BlockFallback = false,
			ParryOnly = false,
			UsePredictionMantra = false,
			UsePunishmentMantra = false,
		},
		ThreatGuard = { Enabled = true },
		Validation = {
			Hitbox = true,
			Facing = false,
			Visibility = false,
			Stun = false,
			Cooldown = true,
			IFrames = false,
			AutoParryFrames = false,
			Prediction = false,
			AnimationSanity = true,
		},
		Filters = {
			M1 = false,
			Mantra = false,
			Critical = false,
			Undefined = false,
			TextboxFocused = false,
			WindowInactive = false,
			HoldingBlock = false,
			ChimeCountdown = false,
			SightlessBeam = false,
		},
		Probability = { Enabled = false, AllowFailure = false, FailureRate = 0 },
		AttackAssistance = {
			AutoFeint = false,
			DelayedFeint = false,
			HoldM1 = false,
			FlourishFeint = false,
			ActionRolling = false,
			AnimationSpeed = { Enabled = false },
		},
		CombatAssistance = {
			Wisp = false,
			GoldenTongue = false,
			MantraFollowUp = false,
			Ardour = false,
			FlowState = false,
			Rhythm = false,
			RagdollResponse = false,
		},
		Diagnostics = {
			Enabled = false,
			Notifications = false,
			TraceDetectors = false,
			TraceScheduler = false,
			VisualizeHitboxes = false,
		},
		DebugState = { BlockParry = false, BlockDodge = false, BlockVent = false, NoBlocking = false },
	}

	local PRESETS = {
		Stable = {
			Targeting = {
				Selection = "ClosestDistance",
				MaxTargets = 4,
				MaxDistance = 3000,
				FOVDegrees = 360,
			},
			Validation = { Hitbox = true, Facing = true, Prediction = false },
			Diagnostics = { AdaptiveScan = true, PerformanceBudgetMs = 2 },
		},
		Legit = {
			Targeting = { ScanInterval = 0.05, MaxTargets = 2, MaxDistance = 65 },
			Validation = { Hitbox = true, Facing = false, Prediction = true, Visibility = false },
			Probability = { Enabled = true, AllowFailure = true, FailureRate = 3 },
			Diagnostics = { PerformanceBudgetMs = 2, AdaptiveScan = true },
		},
		Responsive = {
			Targeting = { ScanInterval = 0.025, MaxTargets = 4, MaxDistance = 90 },
			Validation = { Hitbox = true, Facing = false, Prediction = true },
			Diagnostics = { PerformanceBudgetMs = 3, AdaptiveScan = true },
		},
		Performance = {
			Targeting = { ScanInterval = 0.08, MaxTargets = 2, MaxDistance = 55 },
			Detection = { Sounds = false, Effects = false, OnlyConfigured = true },
			Validation = { Visibility = false, Prediction = false },
			Diagnostics = { PerformanceBudgetMs = 1.25, AdaptiveScan = true },
		},
		Lab = {
			Defense = { Enabled = false },
			Detection = { OnlyConfigured = false, UnknownAnimations = true },
			Diagnostics = { Enabled = true, TraceDetectors = true, TraceScheduler = true },
		},
	}

	local DESCRIPTIONS = {
		Stable = "Known-good indexed parry baseline from live trainer testing.",
		Legit = "Short range with prediction and a small intentional failure rate.",
		Responsive = "Faster scans and prediction for live combat testing.",
		Performance = "Reduced detector and scan load for weaker machines.",
		Lab = "Defense off; broad detection and traces on for animation research.",
	}

	local function merge(target, source)
		for key, value in pairs(source) do
			if type(value) == "table" and type(target[key]) == "table" then
				merge(target[key], value)
			else
				target[key] = value
			end
		end
	end

	function PresetManager.new(settings)
		return setmetatable({ Settings = settings }, PresetManager)
	end

	function PresetManager:names()
		local names = {}
		for name in pairs(PRESETS) do
			names[#names + 1] = name
		end
		table.sort(names)
		return names
	end

	function PresetManager:describe(name)
		return DESCRIPTIONS[name] or ""
	end

	function PresetManager:apply(name)
		local preset = PRESETS[name]
		if not preset then
			return false, "unknown preset"
		end
		local current = self.Settings:serialize()
		merge(current, PRESET_BASE)
		merge(current, preset)
		self.Settings:load(current)
		return true
	end

	return PresetManager
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/PresetManager.lua

-- BEGIN MODULE: src/Combat/AssistanceEngine.lua
do
  local moduleName = "src/Combat/AssistanceEngine.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local modules = environment.__CLAW_MODULES
	local Action = assert(modules["src/Combat/Action.lua"])

	local Players = game:GetService("Players")
	local UserInputService = game:GetService("UserInputService")
	local ContextActionService = game:GetService("ContextActionService")

	local AssistanceEngine = {}
	AssistanceEngine.__index = AssistanceEngine

	local DELAYED_FEINT_ACTION = "CLAW_MARK_DELAYED_FEINT"

	-- Small, first-party bootstrap map for the local weapon animations already
	-- exposed by CLAW MARK's Burster. Assistance therefore works before a user
	-- creates or imports a timing profile.
	local LOCAL_ATTACK_TAGS = {
		["7318254065"] = "critical",
		["9484850093"] = "flourish",
		["7600450739"] = "m1",
		["7600485223"] = "m1",
	}

	local function cleanID(value)
		return tostring(value or ""):match("(%d+)") or tostring(value or "")
	end

	local function includes(list, value)
		for _, item in ipairs(list or {}) do
			if item == value then
				return true
			end
		end
		return false
	end

	function AssistanceEngine.new(settings, state, timings, scheduler, input, executor)
		return setmetatable({
			Settings = settings,
			State = state,
			Timings = timings,
			Scheduler = scheduler,
			Input = input,
			Executor = executor,
			Connections = {},
			CharacterConnections = {},
			ActiveAttack = nil,
			Cooldowns = {},
			Running = false,
			Random = Random.new(),
			HoldingM1 = false,
			FeintedTracks = setmetatable({}, { __mode = "k" }),
		}, AssistanceEngine)
	end

	function AssistanceEngine:_bind(list, signal, callback)
		local connection = signal:Connect(callback)
		list[#list + 1] = connection
		return connection
	end

	function AssistanceEngine:_disconnect(list)
		for _, connection in ipairs(list) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(list)
	end

	function AssistanceEngine:_ready(name, cooldown)
		local now = os.clock()
		if now < (self.Cooldowns[name] or 0) then
			return false
		end
		self.Cooldowns[name] = now + (cooldown or self.Settings:get("CombatAssistance.AssistanceCooldown"))
		return true
	end

	function AssistanceEngine:_custom(name, delay)
		if not self.Settings:get("Enabled") then
			return
		end
		if not self:_ready(name) then
			return
		end
		self.Scheduler:schedule("assist:" .. name, delay or 0, {}, function()
			local ok, reason = self.Input:custom(name, self.State)
			self.State:emit(ok and "assistance" or "assistance-unavailable", {
				name = name,
				reason = reason,
			})
		end)
	end

	function AssistanceEngine:_roll(trigger)
		if not self.Settings:get("Enabled") then
			return
		end
		local attack = self.Settings:get("AttackAssistance")
		if not attack.ActionRolling or not includes(attack.ActionRollingActions, trigger) then
			return
		end
		if not self:_ready("ActionRoll", attack.ActionRollCooldown) then
			return
		end

		local action = Action.new({ kind = "Dodge", name = "Action Roll: " .. trigger })
		local ok, reason = self.Executor:execute(action, { trigger = trigger })
		if ok and attack.ActionRollCancelDelay >= 0 then
			self.Input:scheduleDodgeCancel(attack.ActionRollCancelDelay, false)
		elseif not ok then
			self.State:emit("assistance-unavailable", { name = "ActionRoll", reason = reason })
		end
	end

	function AssistanceEngine:_speed(track, profile)
		local options = self.Settings:get("AttackAssistance.AnimationSpeed")
		if not options.Enabled or (options.LimitToConfigured and not profile) then
			return
		end

		local minimum = math.min(options.Minimum, options.Maximum)
		local maximum = math.max(options.Minimum, options.Maximum)
		local speed
		if options.SwitchExtremes then
			speed = self.Random:NextInteger(0, 1) == 0 and minimum or maximum
		else
			speed = self.Random:NextNumber(minimum, maximum)
		end
		pcall(function()
			track:AdjustSpeed(speed)
		end)
	end

	function AssistanceEngine:_onIncoming(payload)
		if not self.Settings:get("Enabled") then
			return
		end
		local attack = self.Settings:get("AttackAssistance")
		local active = self.ActiveAttack
		if not attack.AutoFeint or not active or not active.track or self.FeintedTracks[active.track] then
			return
		end

		local incomingDelay = math.max(0, tonumber(payload and payload.delay) or 0)
		if attack.AutoFeintMode == "Passive" and not (payload.profile and payload.profile.hyperArmor) then
			local ok, remaining = pcall(function()
				local speed = math.max(0.01, math.abs(active.track.Speed))
				return math.max(0, (active.track.Length - active.track.TimePosition) / speed)
			end)
			-- If our current attack completes before theirs can connect, a passive
			-- feint would accomplish nothing.
			if ok and remaining > 0 and incomingDelay > remaining then
				return
			end
		end

		local delay = math.max(0, incomingDelay - attack.FeintLead)
		if incomingDelay <= 0 then
			delay = math.max(0, attack.FeintDelay)
		end
		self.FeintedTracks[active.track] = true
		self.Scheduler:schedule("assist:auto-feint:" .. tostring(active.track), delay, {}, function()
			if self.ActiveAttack ~= active then
				return
			end
			self.Executor:execute(Action.new({ kind = "Feint", name = "Incoming Auto Feint" }), {
				incoming = payload,
				profile = active.profile,
			})
		end)
	end

	function AssistanceEngine:_onAnimation(track)
		local animation = track.Animation
		local id = cleanID(animation and animation.AnimationId)
		local profile = self.Timings:get("animation", id)

		local clawMark = environment.__CLAW_MARK or environment.__ANIM_LAB_V6
		if clawMark and clawMark.OwnGhostTracks and clawMark.OwnGhostTracks[track] then
			return
		end
		if not self.Settings:get("Enabled") then
			return
		end

		self:_speed(track, profile)

		local tag = profile and string.lower(profile.tag or "") or LOCAL_ATTACK_TAGS[id] or ""
		local name = profile and string.lower(profile.name or "") or ""
		local isAttack = tag == "m1" or tag == "critical" or tag == "mantra" or tag == "flourish"
		if not isAttack then
			return
		end

		self.ActiveAttack = { track = track, profile = profile }
		if self.Settings:get("AttackAssistance.HoldM1") and not self.HoldingM1 then
			self.HoldingM1 = self.Input:mouse(0, true) == true
		end
		self:_bind(self.CharacterConnections, track.Stopped, function()
			if self.ActiveAttack and self.ActiveAttack.track == track then
				self.ActiveAttack = nil
				if self.HoldingM1 then
					self.Input:mouse(0, false)
					self.HoldingM1 = false
				end
			end
		end)

		if
			self.Settings:get("AttackAssistance.FlourishFeint")
			and (tag == "flourish" or string.find(name, "flourish", 1, true))
		then
			self.Scheduler:schedule("assist:flourish-feint", 0, {}, function()
				self.Executor:execute(Action.new({ kind = "Feint", name = "Flourish Feint" }))
			end)
		end

		if tag == "m1" then
			self:_roll("M1")
		elseif tag == "critical" then
			self:_roll("Critical")
		elseif tag == "mantra" then
			self:_roll("Cast")
		end

		if
			self.Settings:get("CombatAssistance.FlowState")
			and (string.find(tag, "silentheart", 1, true) or string.find(name, "silentheart", 1, true))
		then
			self:_custom("FlowState")
		end
	end

	function AssistanceEngine:_attach(character)
		self:_disconnect(self.CharacterConnections)
		self.ActiveAttack = nil
		if not character then
			return
		end

		local function hookAnimator(animator)
			self:_bind(self.CharacterConnections, animator.AnimationPlayed, function(track)
				self:_onAnimation(track)
			end)
		end

		local animator = character:FindFirstChildWhichIsA("Animator", true)
		if animator then
			hookAnimator(animator)
		end
		self:_bind(self.CharacterConnections, character.DescendantAdded, function(descendant)
			if descendant:IsA("Animator") and not animator then
				animator = descendant
				hookAnimator(descendant)
			end
		end)
	end

	function AssistanceEngine:_onFlag(payload)
		if not self.Settings:get("Enabled") then
			return
		end
		if payload.name == "UsingMantra" and payload.value then
			self:_roll("Cast")
		end
		if payload.name == "Ragdolled" and payload.value and self.Settings:get("CombatAssistance.RagdollResponse") then
			self:_custom("RagdollRecover")
		elseif
			payload.name == "WispCooldown"
			and not payload.value
			and not self.State.Flags.WispActive
			and self.Settings:get("CombatAssistance.Wisp")
		then
			self:_custom("Wisp", self.Settings:get("CombatAssistance.WispDelay"))
		elseif
			payload.name == "GoldenTongueCooldown"
			and payload.value
			and self.Settings:get("CombatAssistance.GoldenTongue")
		then
			if not self.Settings:get("CombatAssistance.GoldenTongueCombatOnly") or self.State.Flags.InCombat then
				self:_custom("GoldenTongue")
			end
		elseif payload.name == "UsingMantra" and payload.value and self.Settings:get("CombatAssistance.MantraFollowUp") then
			if not self.Settings:get("CombatAssistance.MantraFollowUpRequireHit") or self.State.Flags.DamagedAnother then
				self:_custom("MantraFollowUp")
			end
		elseif
			payload.name == "DamagedAnother"
			and payload.value
			and self.State.Flags.UsingMantra
			and self.Settings:get("CombatAssistance.MantraFollowUp")
			and self.Settings:get("CombatAssistance.MantraFollowUpRequireHit")
		then
			self:_custom("MantraFollowUp")
		elseif
			(payload.name == "WeaponEquipped" or payload.name == "ArdourActive")
			and self.State.Flags.WeaponEquipped
			and not self.State.Flags.ArdourActive
			and self.Settings:get("CombatAssistance.Ardour")
		then
			self:_custom("Ardour")
		end
	end

	function AssistanceEngine:_delayedFeint(_, inputState)
		if
			inputState ~= Enum.UserInputState.Begin
			or not self.Settings:get("Enabled")
			or not self.Settings:get("AttackAssistance.DelayedFeint")
			or not self.ActiveAttack
		then
			return Enum.ContextActionResult.Pass
		end

		local profile = self.ActiveAttack.profile
		local delay = self.Settings:get("AttackAssistance.FeintDelay")
		if profile and profile.actions[1] then
			delay = math.max(0, profile.actions[1].delay - self.Settings:get("AttackAssistance.FeintLead"))
		end
		self.Scheduler:schedule("assist:delayed-feint", delay, {}, function()
			self.Executor:execute(Action.new({ kind = "Feint", name = "Delayed Feint" }))
		end)
		return Enum.ContextActionResult.Sink
	end

	function AssistanceEngine:_onSetting(payload)
		if not self.Settings:get("Enabled") then
			self.ActiveAttack = nil
			if self.HoldingM1 then
				self.Input:mouse(0, false)
				self.HoldingM1 = false
			end
			return
		end
		if payload.path == "CombatAssistance.Rhythm" and payload.value then
			self:_custom("Rhythm")
		elseif payload.path == "AttackAssistance.HoldM1" and not payload.value and self.HoldingM1 then
			self.Input:mouse(0, false)
			self.HoldingM1 = false
		elseif
			payload.path == "CombatAssistance.Wisp"
			and payload.value
			and not self.State.Flags.WispCooldown
			and not self.State.Flags.WispActive
		then
			self:_custom("Wisp", self.Settings:get("CombatAssistance.WispDelay"))
		elseif
			payload.path == "CombatAssistance.Ardour"
			and payload.value
			and self.State.Flags.WeaponEquipped
			and not self.State.Flags.ArdourActive
		then
			self:_custom("Ardour")
		end
	end

	function AssistanceEngine:start()
		if self.Running then
			return
		end
		self.Running = true
		self:_bind(self.Connections, Players.LocalPlayer.CharacterAdded, function(character)
			self:_attach(character)
		end)
		self:_bind(self.Connections, self.State.Event, function(event)
			if event.kind == "flag" then
				self:_onFlag(event.payload)
			elseif event.kind == "setting" then
				self:_onSetting(event.payload)
			elseif event.kind == "incoming-action" then
				self:_onIncoming(event.payload)
			elseif event.kind == "action" and event.payload.action.kind == "Parry" then
				self:_roll("Parry")
			end
		end)
		self:_bind(self.Connections, UserInputService.InputBegan, function(input, processed)
			if processed then
				return
			end
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				self:_roll("M1")
			elseif input.KeyCode == Enum.KeyCode.F then
				self:_roll("Parry")
			end
		end)
		ContextActionService:BindActionAtPriority(DELAYED_FEINT_ACTION, function(...)
			return self:_delayedFeint(...)
		end, false, Enum.ContextActionPriority.High.Value, Enum.UserInputType.MouseButton2)
		self:_attach(Players.LocalPlayer.Character)
	end

	function AssistanceEngine:stop()
		if not self.Running then
			return
		end
		self.Running = false
		ContextActionService:UnbindAction(DELAYED_FEINT_ACTION)
		self:_disconnect(self.CharacterConnections)
		self:_disconnect(self.Connections)
		self.ActiveAttack = nil
		if self.HoldingM1 then
			self.Input:mouse(0, false)
			self.HoldingM1 = false
		end
		table.clear(self.Cooldowns)
	end

	function AssistanceEngine:Destroy()
		self:stop()
	end

	return AssistanceEngine
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/AssistanceEngine.lua

-- BEGIN MODULE: src/Combat/DefenseEngine.lua
do
  local moduleName = "src/Combat/DefenseEngine.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local modules = environment.__CLAW_MODULES
	local Action = assert(modules["src/Combat/Action.lua"])
	local TimingProfile = assert(modules["src/Combat/TimingProfile.lua"])
	local DynamicWeaponResolver = assert(modules["src/Combat/DynamicWeaponResolver.lua"])

	local DefenseEngine = {}
	DefenseEngine.__index = DefenseEngine

	function DefenseEngine.new(
		settings,
		state,
		timings,
		scheduler,
		executor,
		resolver,
		validator,
		probability,
		fallbacks,
		hitboxWaiter,
		threats
	)
		return setmetatable({
			Settings = settings,
			State = state,
			Timings = timings,
			Scheduler = scheduler,
			Executor = executor,
			Resolver = resolver,
			Validator = validator,
			Probability = probability,
			Fallbacks = fallbacks,
			HitboxWaiter = hitboxWaiter,
			Threats = threats,
			Recent = {},
			GenericRecent = setmetatable({}, { __mode = "k" }),
			Repeats = {},
			ModuleNotified = {},
			LastPrune = 0,
		}, DefenseEngine)
	end

	function DefenseEngine:_prune(now)
		if now - self.LastPrune < 5 then
			return
		end
		self.LastPrune = now
		for key, timestamp in pairs(self.Recent) do
			if now - timestamp > 2 then
				self.Recent[key] = nil
			end
		end
	end

	function DefenseEngine:_targetFor(entity, position)
		local function live(target)
			if not target or not target.Root or not target.Root.Parent then
				return nil
			end
			local localRoot = self.State.Root
			return {
				Character = target.Character,
				Player = target.Player,
				Humanoid = target.Humanoid,
				Root = target.Root,
				Distance = localRoot and (target.Root.Position - localRoot.Position).Magnitude or target.Distance,
				CrosshairDistance = target.CrosshairDistance,
				FacingDot = target.FacingDot,
				OnScreen = target.OnScreen,
				HealthRatio = target.HealthRatio,
			}
		end
		for _, target in ipairs(self.State.Targets) do
			if target.Character == entity then
				return live(target)
			end
		end

		if typeof(position) ~= "Vector3" then
			return nil
		end

		local nearest
		local nearestDistance = math.huge
		for _, target in ipairs(self.State.Targets) do
			local distance = (target.Root.Position - position).Magnitude
			if distance < nearestDistance then
				nearest = target
				nearestDistance = distance
			end
		end
		return live(nearest)
	end

	function DefenseEngine:_defaultAction()
		local preferred = self.Settings:get("Defense.Preferred")
		local allowPath = "Defense.Allow" .. preferred
		if self.Settings:get(allowPath) == false then
			preferred = self.Settings:get("Defense.Fallback")
		end
		return Action.new({ kind = preferred })
	end

	function DefenseEngine:_unknownAnimationProfile(event)
		if event.detector ~= "animation" or not event.track or event.entity == self.State.Character then
			return nil, "not an enemy animation"
		end

		local ok, priority, looped, length = pcall(function()
			return event.track.Priority, event.track.Looped, event.track.Length
		end)
		if not ok then
			return nil, "animation properties unavailable"
		end
		local actionPriority = priority == Enum.AnimationPriority.Action
			or priority == Enum.AnimationPriority.Action2
			or priority == Enum.AnimationPriority.Action3
			or priority == Enum.AnimationPriority.Action4
		if not actionPriority then
			return nil, "non-combat animation priority"
		end
		if looped then
			return nil, "non-combat animation playback"
		end
		if length > 0 and length > self.Settings:get("Defense.UnknownAnimationMaxLength") then
			return nil, "animation is too long"
		end

		local default = self:_defaultAction()
		local weapon = DynamicWeaponResolver.weaponInfo(event)
		local speed = 1
		pcall(function()
			speed = math.max(0.05, math.abs(event.track.Speed))
		end)
		default.name = "Generic " .. default.kind .. ": " .. event.id
		default.delay = self.Settings:get("Defense.UnknownAnimationDelay") / speed
		default.ignoreHitbox = weapon == nil
		default.metadata.preserveDelay = weapon ~= nil
		local profile = TimingProfile.new({
			id = event.id,
			name = (weapon and "Unindexed weapon attack " or "Unindexed animation ") .. event.id,
			detector = "animation",
			tag = weapon and "M1" or "Undefined",
			maxDistance = math.min(
				self.Settings:get("Targeting.MaxDistance"),
				weapon and math.max(64, weapon.length * 4) or 100
			),
			delayUntilHitbox = weapon ~= nil,
			facingHitbox = weapon ~= nil,
			pastHitbox = weapon ~= nil,
			predictFacing = weapon ~= nil,
			historySeconds = weapon and self.Settings:get("Validation.PastHitboxSeconds") or 0,
			predictionSeconds = weapon and self.Settings:get("Validation.PredictionSeconds") or 0,
			sourceModule = weapon and "WeaponTest" or "",
			maxAnimationTime = 2,
			punishableWindow = self.Settings:get("Timing.DefaultPunishableWindow"),
			afterWindow = self.Settings:get("Timing.DefaultAfterWindow"),
			actions = { default },
		})
		profile.genericUnknown = true
		return profile, nil
	end

	function DefenseEngine:_dynamicAction(action, event)
		local metadata = action.metadata or {}
		if not metadata.actionFromTelegraph and not metadata.alternativeChild then
			return action
		end
		local resolved = action:clone()
		local attributes = event.metadata and event.metadata.attributes or {}
		if metadata.actionFromTelegraph then
			local telegraph = tostring(attributes.telegraph or attributes.Telegraph or "")
			resolved.kind = telegraph == "dodge_only" and "Dodge" or "Parry"
		end
		if metadata.alternativeChild and event.entity and event.entity:FindFirstChild(metadata.alternativeChild, true) then
			resolved.kind = metadata.alternativeKind or resolved.kind
			resolved.delay = tonumber(metadata.alternativeDelay) or resolved.delay
			local hitbox = metadata.alternativeHitbox
			if type(hitbox) == "table" then
				resolved.hitbox = Vector3.new(hitbox.X or 0, hitbox.Y or 0, hitbox.Z or 0)
			end
		end
		return resolved
	end

	function DefenseEngine:_reject(reason)
		local detail = tostring(reason)
		self.State:increment("Rejected")
		self.State.LastReject = {
			reason = detail,
			at = os.clock(),
		}
		self.State:emit("action-rejected", reason)
		return false, detail
	end

	function DefenseEngine:_waitForHitbox(key, event, profile, target, action)
		self.HitboxWaiter:wait(key, function()
			if event.track and not profile.ignoreAnimationEnd then
				local ok, playing = pcall(function()
					return event.track.IsPlaying
				end)
				if not ok or not playing then
					return false, "animation-ended"
				end
			end
			local inside = self.Validator:insideHitbox(event, profile, action)
			return inside
		end, function(ready, reason)
			if ready then
				self:_execute(key, event, profile, target, action, true)
			else
				self:_reject(reason)
			end
		end)
	end

	function DefenseEngine:_execute(key, event, profile, target, action, hitboxReady)
		if not self.Settings:get("Enabled") or not self.Settings:get("Defense.Enabled") then
			return self:_reject("defense disabled before execution")
		end
		local currentTarget
		if event.entity == self.State.Character then
			currentTarget = {
				Character = self.State.Character,
				Root = self.State.Root,
				Humanoid = self.State.Humanoid,
				Distance = 0,
			}
		else
			currentTarget = self:_targetFor(event.entity, event.position)
		end
		if not currentTarget or not currentTarget.Root or not currentTarget.Root.Parent then
			return self:_reject("target-lost")
		end

		local valid, reason = self.Validator:validate(event, profile, currentTarget, action)
		local finalAction = action
		if not valid then
			if reason == "outside-hitbox" and profile.delayUntilHitbox and not hitboxReady then
				self:_waitForHitbox(key, event, profile, currentTarget, action)
				return true
			end
			finalAction = self.Fallbacks:resolve(action, reason, profile)
			if not finalAction then
				return self:_reject(reason)
			end
			local fallbackValid, fallbackReason = self.Validator:validate(event, profile, currentTarget, finalAction)
			if not fallbackValid then
				return self:_reject(fallbackReason)
			end
		end

		local ok, executeReason = self.Executor:execute(finalAction, {
			event = event,
			profile = profile,
			target = currentTarget,
		})
		if not ok then
			return self:_reject(executeReason)
		end
		return true
	end

	function DefenseEngine:_startRepeat(key, event, profile, target)
		if not profile.preferRepeat or profile.repeatDelay <= 0 then
			return
		end
		local threatPlan
		if self.Threats then
			local admitted, claimed = self.Threats:claim(event, os.clock() + profile.repeatStartDelay)
			if not admitted then
				return
			end
			threatPlan = claimed
		end
		local token = {}
		local startedAt = os.clock()
		self.Repeats[key] = token

		local function queue(delay)
			local scheduled
			scheduled = self.Scheduler:schedule("repeat:" .. key, math.max(0.03, delay), {
				punishable = profile.punishableWindow,
				after = profile.afterWindow,
			}, function()
				if self.Repeats[key] ~= token then
					if self.Threats then
						self.Threats:settle(threatPlan, scheduled, "repeat replaced")
					end
					return
				end
				if os.clock() - startedAt >= 10 then
					self.Repeats[key] = nil
					if self.Threats then
						self.Threats:settle(threatPlan, scheduled, "repeat timeout")
					end
					return
				end
				if event.track then
					local ok, playing = pcall(function()
						return event.track.IsPlaying
					end)
					if not ok or not playing then
						self.Repeats[key] = nil
						if self.Threats then
							self.Threats:settle(threatPlan, scheduled, "repeat animation ended")
						end
						return
					end
				end

				local action = Action.new({ kind = "Parry", name = profile.name .. " (repeat)" })
				local resolved, reason = self.Probability:resolve(action, profile)
				if resolved then
					self:_execute("repeat:" .. key, event, profile, target, resolved)
				else
					self:_reject(reason)
				end
				queue(profile.repeatDelay)
				if self.Threats then
					self.Threats:settle(threatPlan, scheduled, "repeat advanced")
				end
			end)
			if self.Threats then
				self.Threats:register(threatPlan, scheduled)
			end
			scheduled.onCancel = function(reason)
				if self.Threats then
					self.Threats:settle(threatPlan, scheduled, reason or "repeat cancelled")
				end
			end
		end

		queue(profile.repeatStartDelay)
	end

	function DefenseEngine:reset()
		table.clear(self.Recent)
		table.clear(self.GenericRecent)
		table.clear(self.Repeats)
		table.clear(self.ModuleNotified)
		self.HitboxWaiter:cancelAll()
		if self.Threats then
			self.Threats:reset()
		end
		self.LastPrune = 0
	end

	function DefenseEngine:handle(event)
		self.State:increment("Detected")
		self.State.LastDetection = {
			detector = event.detector,
			id = event.id,
			entity = event.entity and event.entity.Name or "?",
			at = os.clock(),
		}
		self.State:emit("detected", event)

		if not self.Settings:get("Enabled") or not self.Settings:get("Defense.Enabled") then
			return false, "defense is disabled"
		end
		if self.Threats then
			local observed, observeReason = self.Threats:observe(event)
			if not observed then
				return false, observeReason
			end
		end
		local profile = self.Timings:get(event.detector, event.id)
		if not profile then
			local reason
			profile, reason = self:_unknownAnimationProfile(event)
			if not profile then
				return self:_reject(reason or "no timing profile")
			end
			self.State:emit("generic-defense", {
				event = event,
				profile = profile,
			})
		end
		if profile.genericUnknown then
			local now = os.clock()
			local lastGeneric = self.GenericRecent[event.entity]
			if lastGeneric and now - lastGeneric < 0.18 then
				return self:_reject("generic defense rearm")
			end
			local native = self.Executor.Input and self.Executor.Input.Native
			if native and native:isBusy() then
				return self:_reject("generic event while defense input active")
			end
			self.GenericRecent[event.entity] = now
		end
		local localEvent = event.entity == self.State.Character
		if localEvent and profile.ignoreLocalPlayer then
			return self:_reject("ignored local character event")
		end
		if localEvent and not profile.allowLocalPlayer and not profile.forceLocalPlayer then
			return self:_reject("local character event is not allowed")
		end
		if profile.forceLocalPlayer and not localEvent then
			return self:_reject("effect is not on local character")
		end

		local target = localEvent
				and (self.State.PrimaryTarget or {
					Character = self.State.Character,
					Root = self.State.Root,
					Distance = 0,
				})
			or self:_targetFor(event.entity, event.position)
		if not target then
			return self:_reject("event entity is not a selected target")
		end

		local dedupeKey = string.format("%s:%s:%s", event.detector, event.id, tostring(event.entity or event.instance))
		local now = os.clock()
		self:_prune(now)
		if now - (self.Recent[dedupeKey] or 0) < 0.02 then
			return self:_reject("duplicate event")
		end
		self.Recent[dedupeKey] = now
		self.State:emit("defense-profile", {
			event = event,
			profile = profile,
			target = target,
		})

		local actions = #profile.actions > 0 and profile.actions
			or ((profile.preferRepeat or profile.suppressGeneric) and {} or { self:_defaultAction() })
		actions = DynamicWeaponResolver.resolve(profile, event, actions)
		if
			profile.preferModule
			and not profile.preferRepeat
			and not profile.suppressGeneric
			and #profile.actions == 0
			and not self.ModuleNotified[profile.sourceModule]
		then
			self.ModuleNotified[profile.sourceModule] = true
			self.State:emit("module-fallback", {
				module = profile.sourceModule,
				profile = profile.name,
			})
		end
		for index, action in ipairs(actions) do
			local resolved, probabilityReason = self.Probability:resolve(self:_dynamicAction(action, event), profile)
			if not resolved then
				self:_reject(probabilityReason)
				continue
			end

			local valid, validationReason = self.Validator:validate(event, profile, target, resolved, {
				skipHitbox = profile.delayUntilHitbox,
				skipTransient = true,
			})
			if not valid then
				resolved = self.Fallbacks:resolve(resolved, validationReason, profile)
				if not resolved then
					self:_reject(validationReason)
					continue
				end
				local fallbackValid, fallbackReason = self.Validator:validate(event, profile, target, resolved)
				if not fallbackValid then
					self:_reject(fallbackReason)
					continue
				end
			end

			local delay = self.Resolver:delay(resolved, event, target)
			local scheduledAction = resolved
			local threatPlan
			if self.Threats then
				local admitted, claimed = self.Threats:claim(event, os.clock() + delay)
				if not admitted then
					continue
				end
				threatPlan = claimed
			end
			self.State.LastPlan = {
				kind = scheduledAction.kind,
				name = scheduledAction.name,
				profile = profile.name,
				distance = target.Distance,
				delay = delay,
				at = os.clock(),
			}
			self.State:emit("incoming-action", {
				event = event,
				profile = profile,
				action = scheduledAction,
				delay = delay,
				target = target,
			})
			local stopConnection
			-- Predeclare the handle so the delayed closure captures this local. In
			-- Lua/Luau a local is not in scope inside its own initializer, which made
			-- `scheduled` resolve to nil when the callback eventually ran.
			local scheduled
			scheduled = self.Scheduler:schedule(string.format("%s:%s:%d", event.detector, event.id, index), delay, {
				punishable = profile.punishableWindow,
				after = profile.afterWindow,
			}, function()
				if stopConnection then
					stopConnection:Disconnect()
					stopConnection = nil
				end
				local executionKey = scheduled.identifier .. ":" .. tostring(scheduled.id)
				local called, ok, detail = pcall(
					self._execute,
					self,
					executionKey,
					event,
					profile,
					target,
					scheduledAction
				)
				if self.Threats then
					self.Threats:settle(threatPlan, scheduled, called and (detail or "executed") or "execution error")
				end
				if not called then
					error(ok, 0)
				end
				return ok, detail
			end)
			if self.Threats then
				self.Threats:register(threatPlan, scheduled)
			end
			scheduled.onCancel = function(reason)
				if stopConnection then
					stopConnection:Disconnect()
					stopConnection = nil
				end
				if self.Threats then
					self.Threats:settle(threatPlan, scheduled, reason or "plan cancelled")
				end
			end

			if event.track and not profile.ignoreAnimationEnd and not scheduledAction.metadata.ignoreAnimationEnd then
				stopConnection = event.track.Stopped:Connect(function()
					local elapsed = os.clock() - event.startedAt
					local ignoreEarly = profile.ignoreEarlyAnimationEnd
						and profile.maxAnimationTime > 0
						and elapsed < profile.maxAnimationTime
					if not ignoreEarly then
						self.Scheduler:cancel(scheduled, "animation ended")
					end
					if stopConnection then
						stopConnection:Disconnect()
						stopConnection = nil
					end
				end)
			end
		end

		self:_startRepeat(dedupeKey, event, profile, target)

		return true
	end

	return DefenseEngine
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/DefenseEngine.lua

-- BEGIN MODULE: src/Combat/init.lua
do
  local moduleName = "src/Combat/init.lua"
  local moduleFactory = function()
	local environment = getgenv and getgenv() or _G
	local modules = environment.__CLAW_MODULES

	local Settings = assert(modules["src/Combat/Settings.lua"])
	local Action = assert(modules["src/Combat/Action.lua"])
	local Persistence = assert(modules["src/Combat/Persistence.lua"])
	local State = assert(modules["src/Combat/State.lua"])
	local EntityHistory = assert(modules["src/Combat/EntityHistory.lua"])
	local Targeting = assert(modules["src/Combat/Targeting.lua"])
	local TimingStore = assert(modules["src/Combat/TimingStore.lua"])
	local Scheduler = assert(modules["src/Combat/Scheduler.lua"])
	local ThreatArbiter = assert(modules["src/Combat/ThreatArbiter.lua"])
	local DetectorHub = assert(modules["src/Combat/Detection/DetectorHub.lua"])
	local InputAdapter = assert(modules["src/Combat/InputAdapter.lua"])
	local ActionExecutor = assert(modules["src/Combat/ActionExecutor.lua"])
	local TimingResolver = assert(modules["src/Combat/TimingResolver.lua"])
	local DefenseEngine = assert(modules["src/Combat/DefenseEngine.lua"])
	local Performance = assert(modules["src/Combat/Performance.lua"])
	local ValidationEngine = assert(modules["src/Combat/ValidationEngine.lua"])
	local ProbabilityResolver = assert(modules["src/Combat/ProbabilityResolver.lua"])
	local FallbackResolver = assert(modules["src/Combat/FallbackResolver.lua"])
	local Diagnostics = assert(modules["src/Combat/Diagnostics.lua"])
	local StateMonitor = assert(modules["src/Combat/StateMonitor.lua"])
	local PresetManager = assert(modules["src/Combat/PresetManager.lua"])
	local TimingPersistence = assert(modules["src/Combat/TimingPersistence.lua"])
	local AssistanceEngine = assert(modules["src/Combat/AssistanceEngine.lua"])
	local HitboxVisualizer = assert(modules["src/Combat/HitboxVisualizer.lua"])
	local HitboxWaiter = assert(modules["src/Combat/HitboxWaiter.lua"])

	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local UserInputService = game:GetService("UserInputService")

	local Combat = {}
	Combat.__index = Combat

	local MASTERED_FEATURES = {
		["Defense.Enabled"] = true,
		["AttackAssistance.AutoFeint"] = true,
		["AttackAssistance.DelayedFeint"] = true,
		["AttackAssistance.HoldM1"] = true,
		["AttackAssistance.FlourishFeint"] = true,
		["AttackAssistance.ActionRolling"] = true,
		["AttackAssistance.AnimationSpeed.Enabled"] = true,
		["CombatAssistance.Wisp"] = true,
		["CombatAssistance.GoldenTongue"] = true,
		["CombatAssistance.MantraFollowUp"] = true,
		["CombatAssistance.Ardour"] = true,
		["CombatAssistance.FlowState"] = true,
		["CombatAssistance.Rhythm"] = true,
		["CombatAssistance.RagdollResponse"] = true,
		["Diagnostics.Enabled"] = true,
	}

	function Combat.new(options)
		options = options or {}
		local persistence = Persistence.new(options.settingsPath)
		local savedSettings = persistence:load()
		local settings = Settings.new(savedSettings):safeStart()
		local state = State.new()
		local history = EntityHistory.new(settings:get("Validation.HistorySeconds"))

		local self = setmetatable({
			Settings = settings,
			Persistence = persistence,
			State = state,
			History = history,
			Timings = TimingStore.new(),
			Targeting = nil,
			Scheduler = nil,
			Threats = nil,
			Detectors = nil,
			Input = nil,
			Executor = nil,
			Resolver = nil,
			Defense = nil,
			Performance = nil,
			Validator = nil,
			Probability = nil,
			Fallbacks = nil,
			Diagnostics = nil,
			Monitor = nil,
			Presets = nil,
			TimingIO = nil,
			Assistance = nil,
			Hitboxes = nil,
			HitboxWaiter = nil,
			_connections = {},
			_lifetimeConnections = {},
			_lastScan = 0,
			_saveToken = 0,
		}, Combat)

		self.Targeting = Targeting.new(settings, options.targeting)
		self.Scheduler = Scheduler.new(state)
		self.Threats = ThreatArbiter.new(settings, state, self.Scheduler)
		local inputOptions = {
			custom = options.input and options.input.custom or nil,
			settings = settings,
		}
		self.Input = InputAdapter.new(inputOptions)
		self.Executor = ActionExecutor.new(settings, state, self.Input)
		self.Resolver = TimingResolver.new(settings)
		self.Performance = Performance.new(settings)
		self.Validator = ValidationEngine.new(settings, state, history, self.Executor)
		self.Probability = ProbabilityResolver.new(settings)
		self.Fallbacks = FallbackResolver.new(settings)
		self.Diagnostics = Diagnostics.new(settings, state, self.Performance)
		self.Hitboxes = HitboxVisualizer.new(settings, state)
		self.HitboxWaiter = HitboxWaiter.new(settings)
		self.Monitor = StateMonitor.new(state)
		self.Presets = PresetManager.new(settings)
		self.TimingIO = TimingPersistence.new(self.Timings, options.timingsPath)
		local remoteLoaded = false
		local remoteTimings = rawget(environment, "CLAW_TIMINGS_JSON")
		if type(remoteTimings) == "string" and #remoteTimings > 1024 then
			remoteLoaded = self.TimingIO:import(remoteTimings) == true
		end
		-- Release the 1.5 MB JSON string once it has been decoded. A local timing
		-- file is merged afterward, so user edits override the attributed baseline.
		environment.CLAW_TIMINGS_JSON = nil
		local localLoaded = self.TimingIO:load(remoteLoaded) == true
		self.TimingSource = localLoaded and (remoteLoaded and "bundled+local" or "local")
			or (remoteLoaded and "bundled" or "generic")
		environment.CLAW_TIMING_STATUS = {
			source = self.TimingSource,
			count = self.Timings:count(),
			ref = rawget(environment, "CLAW_DISTRIBUTION_REF"),
		}
		self.Assistance = AssistanceEngine.new(settings, state, self.Timings, self.Scheduler, self.Input, self.Executor)
		local detectorOptions = options.detectors
			or {
				shared = {
					ignoreTrack = function(track)
						local clawMark = environment.__CLAW_MARK or environment.__ANIM_LAB_V6
						return clawMark and clawMark.OwnGhostTracks and clawMark.OwnGhostTracks[track] == true
					end,
				},
			}
		self.Detectors = DetectorHub.new(settings, self.Timings, detectorOptions)
		self.Defense = DefenseEngine.new(
			settings,
			state,
			self.Timings,
			self.Scheduler,
			self.Executor,
			self.Resolver,
			self.Validator,
			self.Probability,
			self.Fallbacks,
			self.HitboxWaiter,
			self.Threats
		)
		self._lifetimeConnections[#self._lifetimeConnections + 1] = self.Detectors.Detected:Connect(function(event)
			self.Defense:handle(event)
		end)
		return self
	end

	function Combat:_bind(signal, callback)
		local connection = signal:Connect(callback)
		self._connections[#self._connections + 1] = connection
		return connection
	end

	function Combat:_recordTargets(candidates)
		for _, target in ipairs(candidates) do
			self.History:record(target.Character, target.Root.CFrame, target.Root.AssemblyLinearVelocity)
		end
	end

	function Combat:_step()
		if not self.State.Running or not self.Settings:get("Enabled") then
			return
		end

		local character = Players.LocalPlayer.Character
		if character ~= self.State.Character then
			self.State:setCharacter(character)
		end

		local now = os.clock()
		local scanInterval = self.Performance:scanInterval(self.Settings:get("Targeting.ScanInterval"))
		if now - self._lastScan < scanInterval then
			return
		end
		self._lastScan = now

		self.Performance:measure("target-scan", function()
			local candidates = self.Targeting:scan(character)
			self:_recordTargets(candidates)
			if self.State.Root then
				self.History:record(self.State.Character, self.State.Root.CFrame, self.State.Root.AssemblyLinearVelocity)
			end
			self.State:setTargets(self.Targeting:select(candidates))
		end)
	end

	function Combat:start()
		if self.State.Running or self.State.Destroyed then
			return false
		end

		self.State:set("Running", true)
		self.State:setCharacter(Players.LocalPlayer.Character)
		self.Monitor:start()
		self.Assistance:start()
		if self.Settings:get("Enabled") then
			self.Detectors:start()
		end
		self:_bind(RunService.Heartbeat, function()
			self:_step()
		end)
		self:_bind(UserInputService.InputBegan, function(input, processed)
			if processed or input.KeyCode == Enum.KeyCode.Unknown then
				return
			end
			local binding = self.Settings:get("Bindings.ToggleDefense")
			if
				type(binding) == "string"
				and binding ~= ""
				and string.lower(input.KeyCode.Name) == string.lower(binding)
			then
				self:set("Defense.Enabled", not self.Settings:get("Defense.Enabled"))
			end
		end)
		self.State:emit("started")
		return true
	end

	function Combat:stop()
		if not self.State.Running then
			return false
		end

		self.State:set("Running", false)
		self.Detectors:stop()
		self.Assistance:stop()
		self.Monitor:stop()
		self.Scheduler:cancelAll("combat stopped")
		self.Defense:reset()
		for _, connection in ipairs(self._connections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(self._connections)
		self.State:resetRuntime()
		self.State:emit("stopped")
		return true
	end

	function Combat:set(path, value, persist)
		local result = self.Settings:set(path, value)
		local enabledChanged = path == "Enabled"
		if path == "Defense.Enabled" and value and not self.Settings:get("Detection.Animations") then
			self.Settings:set("Detection.Animations", true)
			self.State:emit("setting", { path = "Detection.Animations", value = true })
		end
		if path == "Defense.Enabled" and value then
			self.Input:warmup()
		end
		if path == "Defense.Enabled" and not value then
			self.Scheduler:cancelAll("auto defense disabled")
			self.Defense:reset()
			self.Input:releaseAll("auto defense disabled")
		end
		if MASTERED_FEATURES[path] and value and not self.Settings:get("Enabled") then
			self.Settings:set("Enabled", true)
			enabledChanged = true
			self.State:emit("setting", { path = "Enabled", value = true })
		end
		if path == "Validation.HistorySeconds" then
			self.History:setWindow(value)
		end
		if path == "ThreatGuard.Enabled" then
			self.Threats:reset()
		end
		if path == "Detection.OnlyConfigured" or path == "Detection.Sounds" then
			self.Detectors:refresh()
		end
		local detectorName = string.match(path, "^Detection%.([^.]+)$")
		if detectorName and self.Detectors.Detectors[detectorName] then
			self.Detectors:sync(detectorName)
		end
		if enabledChanged and self.State.Running then
			if self.Settings:get("Enabled") then
				self._lastScan = -math.huge
				self:_step()
				self.Detectors:start()
			else
				self.Detectors:stop()
				self.Scheduler:cancelAll("combat disabled")
				self.Defense:reset()
				self.Input:releaseAll("combat disabled")
				self.State:setTargets({})
			end
		end
		if persist ~= false then
			self:queueSave()
		end
		self.State:emit("setting", { path = path, value = value })
		return result
	end

	function Combat:queueSave(delaySeconds)
		self._saveToken = self._saveToken + 1
		local token = self._saveToken
		task.delay(delaySeconds or 0.35, function()
			if token == self._saveToken and not self.State.Destroyed then
				self:save()
			end
		end)
	end

	function Combat:save()
		return self.Persistence:save(self.Settings:serialize())
	end

	function Combat:applyPreset(name)
		local ok, reason = self.Presets:apply(name)
		if ok then
			self.History:setWindow(self.Settings:get("Validation.HistorySeconds"))
			if self.State.Running then
				if self.Settings:get("Enabled") then
					self._lastScan = -math.huge
					self:_step()
					self.Detectors:start()
				else
					self.Detectors:stop()
				end
			end
			self.Detectors:refresh()
			self.Detectors:sync()
			self:save()
			self.State:emit("preset", name)
		end
		return ok, reason
	end

	function Combat:registerTiming(values, persist)
		local profile = self.Timings:register(values, true)
		if persist ~= false then
			self.TimingIO:save()
		end
		return profile
	end

	function Combat:removeTiming(category, id, persist)
		self.Timings:remove(category, id)
		if persist ~= false then
			self.TimingIO:save()
		end
	end

	function Combat:importTimings(encoded)
		local ok, reason = self.TimingIO:import(encoded)
		if ok then
			self.TimingIO:save()
		end
		return ok, reason
	end

	function Combat:exportTimings(copyToClipboard)
		if copyToClipboard then
			return self.TimingIO:copy()
		end
		return self.TimingIO:export()
	end

	function Combat:diagnosticReport(copyToClipboard)
		local report = self.Diagnostics:report({
			version = environment.CLAW and environment.CLAW.Version,
			distributionRef = rawget(environment, "CLAW_DISTRIBUTION_REF"),
			timingCount = self.Timings:count(),
			timingSource = self.TimingSource,
			native = {
				status = self.Input.Native.Status,
				last = self.Input.Native.LastTransition,
				stats = self.Input.Native.Stats,
			},
			clientEffects = self.Detectors.Detectors.ClientEffects and self.Detectors.Detectors.ClientEffects.Stats or {},
		})
		if not copyToClipboard then
			return report
		end
		local setclipboard = rawget(environment, "setclipboard")
		if type(setclipboard) ~= "function" then
			return false, "clipboard API is unavailable"
		end
		local ok, reason = pcall(setclipboard, report)
		return ok, ok and "diagnostic report copied" or tostring(reason)
	end

	function Combat:panic()
		self.Settings:safeStart()
		self.Detectors:stop()
		self.Scheduler:cancelAll("safe reset")
		self.Defense:reset()
		self.Assistance:stop()
		local released, releaseDetail = self.Input:releaseAll("safe reset")
		self.State:setTargets({})
		table.clear(self.State.Cooldowns)
		self.History:clear()
		if self.State.Running then
			self.Assistance:start()
		end
		self:save()
		self.State:emit("safe-reset", releaseDetail)
		return released, releaseDetail
	end

	function Combat:testAction(kind)
		local ok, reason = self.Executor:execute(Action.new({
			kind = kind,
			name = "Input self-test: " .. tostring(kind),
		}))
		return ok, reason
	end

	function Combat:Destroy()
		self._saveToken = self._saveToken + 1
		self:save()
		self:stop()
		for _, connection in ipairs(self._lifetimeConnections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(self._lifetimeConnections)
		self.Detectors:Destroy()
		self.Input:Destroy()
		self.Assistance:Destroy()
		self.Monitor:Destroy()
		self.Diagnostics:Destroy()
		self.Hitboxes:Destroy()
		self.HitboxWaiter:Destroy()
		self.Timings:Destroy()
		self.Scheduler:Destroy()
		self.History:clear()
		self.Threats:Destroy()
		self.State:Destroy()
	end

	return Combat
  end
  __clawEnvironment.__CLAW_MODULES[moduleName] = moduleFactory()
end
-- END MODULE: src/Combat/init.lua

