------------------------------------------------------------
-- Drag
------------------------------------------------------------

do

	local dragging = false

	local startMouse

	local startPosition

	bind(
		Top.InputBegan,
		function(input)

			if
				input.UserInputType
				==
				Enum.UserInputType.MouseButton1
			then

				dragging =
					true

				startMouse =
					input.Position

				startPosition =
					Main.Position
			end
		end
	)

	bind(
		UIS.InputEnded,
		function(input)

			if
				input.UserInputType
				==
				Enum.UserInputType.MouseButton1
			then

				local wasDragging = dragging

				dragging = false

				if wasDragging then
					PREFS.UIPosition = {
						xScale = Main.Position.X.Scale,
						xOffset = Main.Position.X.Offset,
						yScale = Main.Position.Y.Scale,
						yOffset = Main.Position.Y.Offset,
					}
				end
			end
		end
	)

	bind(
		UIS.InputChanged,
		function(input)

			if
				not dragging
				or
				input.UserInputType
					~=
				Enum.UserInputType.MouseMovement
			then
				return
			end

			local delta =
				input.Position
				-
				startMouse

			Main.Position =
				UDim2.new(
					startPosition.X.Scale,
					startPosition.X.Offset
						+ delta.X,

					startPosition.Y.Scale,
					startPosition.Y.Offset
						+ delta.Y
				)
		end
	)
end

