local function filterMatch(
	id,
	profile
)

	local query =
		string.lower(
			Search.Text or ""
		)

	if query == "" then
		return true
	end

	local data =
		string.lower(
			tostring(id)
			..
			" "
			..
			tostring(
				profile.name
			)
		)

	return
		string.find(
			data,
			query,
			1,
			true
		)
		~= nil
end

