			24,
			8
		)

	State.LiveRows[track] = {
		button = row,
		text = text,
	}

	bind(
		row.MouseButton1Click,
		function()

			local id =
				getId(track)

			if id then

				State.Selected =
					id

				PREFS.SelectedAnimation = id

				UI.RefreshBurst()

				if UI.RefreshGhost then
					UI.RefreshGhost()
				end
			end
		end
	)

	return
		State.LiveRows[track]
end

local function updateLiveCanvas()

	task.defer(function()

		LiveScroll.CanvasSize =
			UDim2.fromOffset(
				0,
				LiveLayout.AbsoluteContentSize.Y
			)
	end)
end

task.spawn(function()

	while not State.Destroyed do

		task.wait(
			CONFIG.PollRate
		)

		local animator =
			State.TargetAnimator

		if not animator then
			continue
		end

		local tracks =
			safe(
				function()

					return
						animator:
							GetPlayingAnimationTracks()
				end,
				{}
			)

		local now =
			os.clock()

		local active = {}

		for _, track
			in ipairs(tracks)
		do

			active[track] =
				true

			State.LastSeen[track] =
				now

			local row =
				makeLiveRow(track)

			local id =
				getId(track)
				or "?"

			local speed =
				safe(
					function()
						return track.Speed
					end,
					0
				)

			local pos =
				safe(
					function()
						return track.TimePosition
					end,
					0
				)

			local wc =
				safe(
					function()
						return track.WeightCurrent
					end,
					0
				)

			local wt =
				safe(
					function()
						return track.WeightTarget
					end,
					0
				)

			local pri =
				safe(
					function()
						return track.Priority.Name
					end,
					"?"
				)

			local looped =
				safe(
					function()
						return track.Looped
					end,
					false
				)

			row.text.TextColor3 =
				COLORS.TEXT

			row.text.Text =
				string.format(
					"● %-13s S:%4.2f P:%5.3f W:%0.6f>%0.4f %-7s L:%s",
					id,
					speed,
					pos,
					wc,
					wt,
					pri,
					looped
						and "Y"
						or "N"
				)
		end

		for track, seen
			in pairs(
				State.LastSeen
			)
		do

			if not active[track] then

				local age =
					now
					-
					seen

				local row =
					State.LiveRows[track]

				if
					age >
					CONFIG.RecentTTL
				then

					State.LastSeen[track] =
						nil

					if row then

						pcall(function()

							row.button:
								Destroy()
						end)

						State.LiveRows[track] =
							nil
					end

				elseif row then

					row.text.TextColor3 =
						COLORS.MUTED

					row.text.Text =
						string.format(
							"· %-13s recent %.2fs",
							getId(track)
								or "?",
							age
						)
				end
			end
		end

		updateLiveCanvas()
	end
end)

