local CombatRuntime =
	State.Combat

local CombatRefreshers = {}

local function combatRefreshAll()
	for _, refresh in ipairs(CombatRefreshers) do
		pcall(refresh)
	end
	refreshStatus()
end

local function combatSection(
	parent,
	title,
	x,
	y,
	width,
	height
)
	local panel =
		Instance.new("Frame")

	panel.Position =
		UDim2.fromOffset(x, y)

	panel.Size =
		UDim2.fromOffset(width, height)

	panel.BackgroundColor3 =
		Color3.fromRGB(20, 20, 24)

	panel.BorderColor3 =
		COLORS.BORDER

	panel.BorderSizePixel = 1

	panel.Parent =
		parent

	local heading =
		mkLabel(
			panel,
			title,
			8,
			3,
			width - 16,
			20,
			10
		)

	heading.TextColor3 =
		COLORS.ACCENT

	return panel
end

local function combatToggle(
	parent,
	label,
	path,
	x,
	y,
	width,
	enabledColor,
	disabledColor
)
	local button =
		mkButton(
			parent,
			"",
			x,
			y,
			width,
			23
		)

	local function refresh()
		local enabled =
			CombatRuntime
			and CombatRuntime.Settings:get(path)

		button.Text =
			label
			.. ": "
			.. (enabled and "ON" or "OFF")

		button.BackgroundColor3 =
			enabled
			and (enabledColor or COLORS.GREEN)
			or (disabledColor or COLORS.RED)
	end

	CombatRefreshers[#CombatRefreshers + 1] =
		refresh

	bind(
		button.MouseButton1Click,
		function()
			if not CombatRuntime then
				return
			end
			CombatRuntime:set(
				path,
				not CombatRuntime.Settings:get(path)
			)
			combatRefreshAll()
		end
	)

	refresh()
	return button
end

local function combatCycle(
	parent,
	label,
	path,
	values,
	x,
	y,
	width
)
	local button =
		mkButton(
			parent,
			"",
			x,
			y,
			width,
			23
		)

	local function refresh()
		local value =
			CombatRuntime
			and CombatRuntime.Settings:get(path)
			or "N/A"
		button.Text =
			label .. ": " .. tostring(value)
	end

	CombatRefreshers[#CombatRefreshers + 1] =
		refresh

	bind(
		button.MouseButton1Click,
		function()
			if not CombatRuntime then
				return
			end
			local current =
				CombatRuntime.Settings:get(path)
			local index =
				table.find(values, current)
				or 0
			index =
				(index % #values) + 1
			CombatRuntime:set(path, values[index])
			combatRefreshAll()
		end
	)

	refresh()
	return button
end

local function combatNumber(
	parent,
	label,
	path,
	x,
	y,
	minimum,
	maximum
)
	mkLabel(
		parent,
		label,
		x,
		y,
		116,
		22,
		9
	)

	local box =
		mkBox(
			parent,
			"",
			x + 120,
			y,
			72,
			22
		)

	local function refresh()
		local value =
			CombatRuntime
			and CombatRuntime.Settings:get(path)
			or 0
		box.Text =
			tostring(value)
	end

	CombatRefreshers[#CombatRefreshers + 1] =
		refresh

	bind(
		box.FocusLost,
		function()
			if not CombatRuntime then
				return
			end
			local current =
				CombatRuntime.Settings:get(path)
			CombatRuntime:set(
				path,
				clampNumber(
					box.Text,
					minimum,
					maximum,
					current
				)
			)
			refresh()
		end
	)

	refresh()
	return box
end

local function combatText(
	parent,
	label,
	path,
	x,
	y,
	labelWidth,
	boxWidth
)
	mkLabel(parent, label, x, y, labelWidth, 22, 9)
	local box =
		mkBox(
			parent,
			"",
			x + labelWidth + 4,
			y,
			boxWidth,
			22
		)

	local function refresh()
		if not CombatRuntime or box:IsFocused() then
			return
		end
		box.Text = tostring(CombatRuntime.Settings:get(path) or "")
	end

	CombatRefreshers[#CombatRefreshers + 1] = refresh
	bind(box.FocusLost, function()
		if CombatRuntime then
			CombatRuntime:set(path, box.Text)
		end
		refresh()
	end)
	refresh()
	return box
end

