bind(
	UIS.InputBegan,
	function(input, processed)

		if processed
			or State.Destroyed
		then
			return
		end

		if
			input.KeyCode
			==
			Enum.KeyCode[
				CONFIG.UIKey
			]
		then

			Gui.Enabled =
				not Gui.Enabled

			if Gui.Enabled then

				refreshStatus()
			end
		end
	end
)

