--==============================================================
-- DESTROY
--==============================================================

function State:Destroy()

	if self.Destroyed then
		return
	end

	stopGhostRunner()

	stopAllGhosts()

	if self.Combat then
		pcall(function()
			self.Combat:Destroy()
		end)
		if ENV.CLAW and ENV.CLAW.Combat == self.Combat then
			ENV.CLAW.Combat = nil
		end
		self.Combat = nil
	end

	leaveUI()

	self.Destroyed =
		true

	CONFIG.BursterMaster =
		false

	CONFIG.LoggingEnabled =
		false

	clearTargetConnections()

	for _, c
		in ipairs(
			self.Connections
		)
	do

		pcall(function()

			c:
				Disconnect()
		end)
	end

	table.clear(
		self.Connections
	)

	for track
		in pairs(
			self.OwnGhostTracks
		)
	do

		pcall(function()

			track:
				Stop(0)
		end)

		pcall(function()

			track:
				Destroy()
		end)
	end

	pcall(function()

		Gui:
			Destroy()
	end)

	if ENV.__CLAW_MARK == self then
		ENV.__CLAW_MARK = nil
	end

	if ENV.__ANIM_LAB_V6 == self then
		ENV.__ANIM_LAB_V6 = nil
	end

	print(
		"[CLAW] CLAW MARK unloaded"
	)
end

